window.CASTLE_LIBRARY = [{"id":"letter-01","title":"letter 01 💌","category":"letter","sequence":1,"duration":453.0155,"audio":"letter-01.mp3","palette":["#776348","#605743"],"cues":[{"text":"在提笔写这篇“作文”时，我其实在心里推翻过很多种开头。","paragraph":0,"style":"plain","start":2.02,"end":8.66},{"text":"毕竟隔着一块发光的屏幕去描述一个人，本身就像一场古老的“真幻之辩”，","paragraph":1,"style":"plain","start":9.88,"end":17.6},{"text":"或者说“蕉鹿之梦”。","paragraph":1,"style":"plain","start":18.12,"end":20.0},{"text":"话说古时有个砍柴人，在山里意外打到了一只鹿。","paragraph":2,"style":"plain","start":21.56,"end":27.18},{"text":"他怕被人发现，便急急忙忙用芭蕉叶把鹿藏在山沟里。","paragraph":2,"style":"plain","start":28.3,"end":34.54},{"text":"可转眼走远之后，他自己却怎么也找不到那个地方了，找来找去无果，最后索性自嘲一笑，","paragraph":2,"style":"plain","start":35.72,"end":44.88},{"text":"觉得刚刚猎到鹿的惊喜，大概不过是自己做的一场白日梦。","paragraph":2,"style":"plain","start":45.8,"end":51.72},{"text":"而另一个人偶然听说了这件事，循着痕迹真的找到了那只被蕉叶盖住的鹿，反倒也陷入了恍惚，","paragraph":2,"style":"plain","start":52.54,"end":63.28},{"text":"分不清这究竟是前人的梦境成真，还是世事本就虚幻难辨。","paragraph":2,"style":"plain","start":64.38,"end":70.46},{"text":"千百年来，人们总在争论究竟是醒时得鹿，还是梦里蕉遮，","paragraph":3,"style":"plain","start":71.14,"end":77.42},{"text":"把它写成了一则关于“真假与得失”的隐喻。","paragraph":3,"style":"plain","start":77.86,"end":82.94},{"text":"今晚隔着这块发光的屏幕、几千公里的电波去描述你的时候，我总觉得，我们身处的这个时代，","paragraph":4,"style":"plain","start":83.26,"end":92.88},{"text":"其实每天都在重演着这场现代版的“蕉鹿之梦”。","paragraph":4,"style":"plain","start":93.64,"end":98.22},{"text":"面对着跳动的数据流、不断刷新的公屏与环形灯下的光影，大家涌入直播间，按下关注，","paragraph":5,"style":"plain","start":100.14,"end":108.98},{"text":"留下只言片语，又在退出界面的那一刻如潮水般散去。","paragraph":5,"style":"plain","start":109.44,"end":115.04},{"text":"在这场流动的虚实之间，绝大多数人只是在浮光掠影里各取所需，填充着各自的孤独。","paragraph":5,"style":"plain","start":115.9,"end":125.42},{"text":"文学批评里常谈到一个词叫“语义漂流”——同一个形象在不同时代，会被不同的人各自认领、","paragraph":5,"style":"plain","start":126.7,"end":135.94},{"text":"各自填充，投射进各自的情绪与得失。","paragraph":5,"style":"plain","start":135.94,"end":140.12},{"text":"屏幕这端的生态大抵也是如此，每天穿梭而过的看客，都在按照自己的期待，为你贴上标签，","paragraph":5,"style":"plain","start":141.06,"end":149.82},{"text":"拼凑出一个属于他们的“你”。","paragraph":5,"style":"plain","start":150.42,"end":153.14},{"text":"很多人以为双子座的千面流转，就像掌握了七十二变的神通，在热闹与从容之间切换自如。","paragraph":6,"style":"plain","start":154.9,"end":163.06},{"text":"但隔着这方小小的方寸之地，我总觉得，那些被喧嚣推到台前的光芒，","paragraph":6,"style":"plain","start":164.04,"end":170.86},{"text":"只是时代与环境向你借走的投影。","paragraph":6,"style":"plain","start":171.01,"end":174.0},{"text":"比起那些被所有人热烈讨论的侧影，我更想去辨认那个在光晕暗淡下去之后的你。","paragraph":7,"style":"plain","start":175.14,"end":181.96},{"text":"ISFP的灵魂里往往藏着一座不对外开放的后花园，外面看起来随和温软，","paragraph":8,"style":"plain","start":182.504,"end":191.82},{"text":"内里却对真实有着近乎固执的洁癖。","paragraph":8,"style":"plain","start":192.26,"end":195.88},{"text":"在镜头前，你或许是一面明亮的镜子，映照着世间繁杂的目光；","paragraph":8,"style":"plain","start":197.08,"end":203.5},{"text":"但在某些极微小的间歇里——比如一首歌切歌时的停顿、你眼神离开公屏微微晃神的半秒、","paragraph":8,"style":"plain","start":204.5,"end":214.92},{"text":"或是谈起某件微不足道的小事时眼底掠过的微光——那更像戴锦华笔下所说的“一个密码，","paragraph":8,"style":"plain","start":215.98,"end":225.16},{"text":"一句暗语，一桩机关”。","paragraph":8,"style":"plain","start":225.72,"end":229.02},{"text":"那些细微而真实的瞬间，像一道无声升起的氤氲，瞬间绕过了所有预设的防线，","paragraph":9,"style":"plain","start":230.66,"end":237.4},{"text":"击中了我的灵魂深处。","paragraph":9,"style":"plain","start":237.82,"end":239.44},{"text":"大家都在试图定义你、认领你、或者向你索取陪伴与情绪。","paragraph":10,"style":"plain","start":240.86,"end":246.7},{"text":"但我并不想用任何轻率的形容词去将你装订成册，因为任何单向的定义，","paragraph":10,"style":"plain","start":247.5,"end":254.3},{"text":"都是对一个人鲜活本真的折损。","paragraph":10,"style":"plain","start":254.3,"end":256.74},{"text":"我不想成为人群里那个急切想要填充你意义的人，也不想扮演一个冲动而喧哗的闯入者。","paragraph":10,"style":"plain","start":257.78,"end":265.8},{"text":"我只是很庆幸，隔着茫茫的人海与虚拟的电波，我没有仅仅看到一个被聚光灯照亮的符号。","paragraph":11,"style":"plain","start":266.92,"end":276.32},{"text":"我看到了那个在喧嚣之外、有着自己节奏与审美的女孩；","paragraph":12,"style":"plain","start":277.64,"end":282.44},{"text":"看到了你在热闹与静谧交界处的呼吸；","paragraph":12,"style":"plain","start":283.42,"end":286.84},{"text":"也看到了你在流动的浮世里，悄悄守护着的那份真诚。","paragraph":12,"style":"plain","start":287.62,"end":293.1},{"text":"如果说喜欢一个人是一场不可预测的探索，那么“我该如何描述你”，","paragraph":13,"style":"plain","start":294.96,"end":301.36},{"text":"便成了一个极其艰难的命题。","paragraph":13,"style":"plain","start":301.78,"end":303.98},{"text":"因为在普遍热衷于归纳和定义的世俗里，人们总习惯把人装进固定的盒子里：用星座标签你，","paragraph":14,"style":"plain","start":305.32,"end":314.84},{"text":"用人设简化你，或者试图用几句轻浮的告白去占有你。","paragraph":14,"style":"plain","start":315.4,"end":321.68},{"text":"但我不想成为那个急不可耐地在你身上书写自己欲望的看客，更不想用任何自以为是的框架，","paragraph":14,"style":"plain","start":322.5,"end":330.52},{"text":"去束缚你原本就无拘无束的生命力。","paragraph":14,"style":"plain","start":330.52,"end":333.98},{"text":"喜欢这件事，如果隔着未曾谋面的距离，最体面的方式或许不是急于索求一个确凿的结果，","paragraph":15,"style":"plain","start":335.0,"end":343.0},{"text":"而是带着懂得与敬意，去凝视一个生命的舒展。","paragraph":15,"style":"plain","start":343.92,"end":347.98},{"text":"我喜欢你像风一样掠过人群时的机敏与生动，也喜欢你退回自己小小世界时、","paragraph":16,"style":"plain","start":350.9,"end":358.32},{"text":"那份不与外人道的孤单与纯粹；","paragraph":16,"style":"plain","start":358.76,"end":361.02},{"text":"我喜欢看你在聚光灯下闪闪发亮，但我也在心里默默珍惜着那个在关掉电源、摘下耳机后，","paragraph":16,"style":"plain","start":362.04,"end":371.08},{"text":"会感到疲惫却依然保持温良的你。","paragraph":16,"style":"plain","start":371.44,"end":375.66},{"text":"在这个语义不断漂流、一切事物都被快速消费又迅速遗忘的时代里，","paragraph":17,"style":"plain","start":376.22,"end":381.94},{"text":"我不想做那阵匆匆吹过又散去的风。","paragraph":17,"style":"plain","start":382.58,"end":385.8},{"text":"如果说去描述你是徒劳，那就让你继续做那朵捉摸不透的云吧，尽可以像风一样多变，","paragraph":18,"style":"plain","start":387.4,"end":395.94},{"text":"像画笔一样自由，保留你所有的神秘与留白，继续在你的宇宙里画画、探险、感知细碎的美好。","paragraph":18,"style":"plain","start":396.5,"end":406.32},{"text":"而我能给你最真实的表达，不过是在漫长的喧哗散尽之后，","paragraph":19,"style":"plain","start":407.46,"end":411.88},{"text":"依然站在一个刚刚好能看清你原本模样的位置。","paragraph":19,"style":"plain","start":412.52,"end":416.28},{"text":"看清了光影背后的全部虚妄，却依然坚定地为你眼底那抹真实的清澈动心。","paragraph":19,"style":"plain","start":417.38,"end":424.76},{"text":"在所有被世界认领的侧影之外，我独独喜欢的，是你未曾修剪的真实底色。","paragraph":20,"style":"plain","start":426.14,"end":432.16},{"text":"也许世界上有五千朵和你一模一样的花，但只有你，是我眼中独一无二的玫瑰。","paragraph":21,"style":"plain","start":433.58,"end":440.9},{"text":"斯人若彩虹，遇上方知有。","paragraph":22,"style":"plain","start":441.85,"end":445.947},{"text":"我喜欢你，从初次望向你的第一眼开始。","paragraph":23,"style":"closing","start":446.38,"end":450.54}]},{"id":"letter-02","title":"letter 02 💌","category":"letter","sequence":2,"duration":502.360792,"audio":"letter-02.mp3","palette":["#785447","#665145"],"cues":[{"text":"深圳十一月的风虽然吹得很轻，却还是在傍晚时分，悄悄把整座城市吹凉了。","paragraph":0,"style":"plain","start":1.58,"end":9.22},{"text":"这里的冬天向来没有萧瑟的落叶，行道旁的榕树和棕榈依旧保持着沉稳的绿意，","paragraph":0,"style":"plain","start":10.42,"end":18.44},{"text":"只有几株晚开的美丽异木棉，偶尔被风拂落一两片粉白色的花瓣，轻轻停在人行道边。","paragraph":0,"style":"plain","start":19.14,"end":26.64},{"text":"路灯一盏接着一盏亮起来，昏黄的光晕穿过层层叠叠的常绿枝叶，","paragraph":0,"style":"plain","start":28.08,"end":34.807},{"text":"在地面投下斑驳而安静的影子。","paragraph":0,"style":"plain","start":35.24,"end":38.06},{"text":"每当一天里最喧闹的部分退去，整座城市的节奏慢下来，","paragraph":0,"style":"plain","start":38.98,"end":44.2},{"text":"人就很容易想起一些具体而真切的事物——比如街角刚出炉时冒着热气的烤红薯，","paragraph":0,"style":"plain","start":44.78,"end":53.12},{"text":"比如耳机里循环到一半却舍不得切掉的旋律，又比如，不知从哪一天起，","paragraph":0,"style":"plain","start":54.24,"end":61.6},{"text":"悄无声息闯入我生活里的你。","paragraph":0,"style":"plain","start":61.835,"end":64.42},{"text":"看着窗外次第亮起的万家灯火，心里总会生出一种很踏实的念头：","paragraph":0,"style":"plain","start":65.88,"end":71.54},{"text":"哪怕此刻我们各自待在自己的世界里，吹过窗台的，也是同一阵晚风。","paragraph":0,"style":"plain","start":72.34,"end":79.9},{"text":"如果把走近一个人比作翻开一本书，我想，我们大概才刚刚读完扉页，正停在第一章的开头。","paragraph":1,"style":"plain","start":81.92,"end":90.62},{"text":"也正因为如此，我从不敢自以为是地说自己有多了解你。","paragraph":1,"style":"plain","start":91.5,"end":95.82},{"text":"成年人之间最难得的清醒，就是承认彼此的世界都足够辽阔，人与人之间的靠近，","paragraph":1,"style":"plain","start":96.92,"end":104.08},{"text":"从来不是靠几句轻巧的猜测就能抄近道的。","paragraph":1,"style":"plain","start":104.56,"end":107.8},{"text":"真正的理解，需要漫长的时光去一点点沉淀，需要陪你走过烈日当空的晴天，","paragraph":1,"style":"plain","start":108.46,"end":115.69},{"text":"也陪你看过雷雨交加的阴雨。","paragraph":1,"style":"plain","start":116.12,"end":118.94},{"text":"每个人心里都藏着一片未曾向外人敞开的湖泊，水底有什么样的暗流、岸边开着怎样的花，","paragraph":1,"style":"plain","start":119.36,"end":127.7},{"text":"只有等时间慢慢走过，才能一点点看清。","paragraph":1,"style":"plain","start":128.54,"end":131.7},{"text":"我能做的，只是把那些与你交汇的瞬间小心收好，像收集落在掌心里的微光，不急着定义，","paragraph":1,"style":"plain","start":132.6,"end":141.3},{"text":"也不急着下结论。","paragraph":1,"style":"plain","start":141.82,"end":143.62},{"text":"可即便只是站在故事的开头，你身上那种生动的气息，还是像一扇突然被推开的窗，","paragraph":2,"style":"plain","start":144.327,"end":152.7},{"text":"让清新的风一下子灌进了我原本按部就班的日子。","paragraph":2,"style":"plain","start":153.54,"end":157.24},{"text":"现在的很多人习惯把感情看作一场精密的博弈，讲究互相试探、彼此拉扯，","paragraph":2,"style":"plain","start":158.48,"end":165.6},{"text":"仿佛谁先动了真心谁就落了下风。","paragraph":2,"style":"plain","start":166.22,"end":169.253},{"text":"但我向来不喜欢那些弯弯绕绕的算计，于我而言，","paragraph":2,"style":"plain","start":169.66,"end":173.9},{"text":"遇见你更像是一场打破既定剧本的奇遇——就像原本沿着固定轨迹行走的人，","paragraph":2,"style":"plain","start":174.34,"end":180.9},{"text":"忽然偏离了枯燥的日常线，在转角处意外发现了一处宝藏。","paragraph":2,"style":"plain","start":181.34,"end":186.8},{"text":"你不仅成了我延展这个世界的契机，更让我看见了生活里另一种鲜活的可能。","paragraph":2,"style":"plain","start":187.44,"end":194.88},{"text":"我喜欢看你说话时的样子，语调里总带着几分灵气的起伏。","paragraph":3,"style":"plain","start":196.32,"end":201.32},{"text":"有时候明明上一秒还在随口打趣，眼底亮晶晶地藏着一点狡黠，","paragraph":3,"style":"plain","start":202.16,"end":208.58},{"text":"下一秒却会因为某个微小的念头忽然安静下来，眼神清澈，带着几分对世界的好奇与审视。","paragraph":3,"style":"plain","start":209.0,"end":218.053},{"text":"越是留意你，我就越能发现，在你活泼温柔的背后，其实藏着一股相当强大的自驱力。","paragraph":3,"style":"plain","start":218.52,"end":225.36},{"text":"你从不需要刻意去扮演任何讨人喜欢的模样，光是站在那里，随性地呼吸、停顿、笑起来，","paragraph":3,"style":"plain","start":226.28,"end":234.467},{"text":"就已经足够让周围的空气变得生动。","paragraph":3,"style":"plain","start":234.68,"end":237.44},{"text":"喜欢一个具体的人，大抵就是这样——不是爱上某种虚幻的想象，","paragraph":3,"style":"plain","start":238.58,"end":243.6},{"text":"而是真真切切地被你身上那股不加修饰的生命力所吸引。","paragraph":3,"style":"plain","start":244.22,"end":248.7},{"text":"在这个人人都习惯戴着盔甲赶路的时代，要守住心底那份干净的敏感与主见，","paragraph":4,"style":"plain","start":250.12,"end":256.26},{"text":"其实并不是一件容易的事。","paragraph":4,"style":"plain","start":256.92,"end":258.42},{"text":"你从来不是那种需要被放进温室里一味呵护的花朵，你心里有着属于自己的旷野和节奏，","paragraph":4,"style":"plain","start":259.36,"end":266.54},{"text":"你本身就是迎着风生长的春天。","paragraph":4,"style":"plain","start":267.16,"end":270.04},{"text":"外界的目光与声音总是纷繁复杂，但我想告诉你，你根本没必要为了三分钟的琐事，","paragraph":4,"style":"plain","start":270.9,"end":277.629},{"text":"去毁掉二十三小时五十七分的快乐，更不必为了迎合他人的节奏，而打乱你自己原本的步调。","paragraph":4,"style":"plain","start":277.833,"end":285.54},{"text":"你只要按着自己舒服的方式往前走就好，剩下的风吹草动，其实都没有那么重要。","paragraph":4,"style":"plain","start":286.54,"end":293.08},{"text":"不过，再独立、再有力量的人，也总会有觉得外面太吵、想要暂时躲起来歇一歇的时候。","paragraph":5,"style":"plain","start":294.22,"end":301.54},{"text":"如果哪天你累了，想把自己关进安静的城堡里，我绝不会去用力敲门打扰你，","paragraph":5,"style":"plain","start":302.6,"end":309.82},{"text":"更不会用所谓的关心去给你制造压力。","paragraph":5,"style":"plain","start":310.5,"end":313.14},{"text":"我只会在城堡外面，选一片阳光最好的空地，","paragraph":5,"style":"plain","start":313.98,"end":317.42},{"text":"静静地替你种一座花园——种下会随风摇晃的矢车菊，种下到了春天就会发芽的草籽，","paragraph":5,"style":"plain","start":318.02,"end":327.12},{"text":"再留一条铺满碎石的小径。","paragraph":5,"style":"plain","start":327.84,"end":330.2},{"text":"人们常说“爱人如养树”，真正的陪伴从来不是一阵急匆匆的骤雨，而是把耐心当成泥土，","paragraph":5,"style":"plain","start":330.64,"end":338.64},{"text":"把分寸当成阳光，安安静静地守在那里。","paragraph":5,"style":"plain","start":339.0,"end":342.46},{"text":"等你什么时候想推开窗透气了，一抬眼，就能看见满园的绿意。","paragraph":5,"style":"plain","start":342.46,"end":348.9},{"text":"最近天气一天比一天冷了，傍晚出门时，风吹在脸上已经有了几分初冬的寒意。","paragraph":6,"style":"plain","start":349.98,"end":358.733},{"text":"每当路过街角亮着暖光的便利店，或是看见晚风吹动路旁常绿的树梢，","paragraph":6,"style":"plain","start":359.14,"end":366.067},{"text":"我心里总会生出很多具体而微小的期待。","paragraph":6,"style":"plain","start":366.393,"end":369.66},{"text":"我想起有人说过，人要先感到幸福，才能真正看见玫瑰。","paragraph":6,"style":"plain","start":369.985,"end":375.827},{"text":"而我想的却是，如果以后有机会，我想和你一起在傍晚的街头随便走走，","paragraph":6,"style":"plain","start":376.16,"end":382.88},{"text":"一起喝一杯刚做好的温热奶茶；","paragraph":6,"style":"plain","start":383.42,"end":385.48},{"text":"或者在某个周末的午后，沿着城市的山脊线走走停停，看看花、吹吹风，","paragraph":6,"style":"plain","start":386.32,"end":393.28},{"text":"用轻松的闲聊消弭一周的疲倦。","paragraph":6,"style":"plain","start":394.0,"end":396.18},{"text":"哪怕一路上谁也不刻意找话题，只是听着风声和脚步声，沉默也能像呼吸一样自然。","paragraph":6,"style":"plain","start":396.98,"end":404.32},{"text":"甚至有时候我还会带着一点私心去想，真要谢谢从前那些不曾认真送你花的人，才让我有机会，","paragraph":6,"style":"plain","start":405.84,"end":415.24},{"text":"成为那个把第一束花递到你手里的人。","paragraph":6,"style":"plain","start":415.64,"end":419.1},{"text":"顺着这个念头往回想，对于那些我还没来得及参与的、你成长里的岁月，","paragraph":7,"style":"plain","start":420.3,"end":426.52},{"text":"心里总会生出几分单纯的贪心。","paragraph":7,"style":"plain","start":427.0,"end":429.64},{"text":"人这一路走来，即便大多时候都是晴朗顺遂的，也总难免会遇到几个突然起风或落雨的瞬间。","paragraph":7,"style":"plain","start":430.6,"end":439.84},{"text":"有时候我甚至会想，如果早点认识你就好了，在你小的时候，在你第一次难过的时候，","paragraph":7,"style":"plain","start":440.42,"end":447.48},{"text":"在你第一次特别需要陪伴的时候，在你最需要爱的时候。","paragraph":7,"style":"plain","start":448.32,"end":454.1},{"text":"时间是一条只往前奔涌的河，我们没法逆流而上，去捡回彼此错过的从前；","paragraph":8,"style":"plain","start":456.02,"end":463.16},{"text":"可好在渡口还在前方，往后的春夏秋冬，都还一页页地铺展在眼前。","paragraph":8,"style":"plain","start":463.66,"end":470.3},{"text":"你性子强，那我就软一点。","paragraph":8,"style":"plain","start":471.26,"end":473.28},{"text":"你喜欢说反话，那我就反过来听，情绪上来的时候推开我，那我就用力地抱紧你，你反复地推，","paragraph":8,"style":"plain","start":474.12,"end":482.76},{"text":"我就反复地抱。","paragraph":8,"style":"plain","start":483.16,"end":484.26},{"text":"因为我喜欢你，有刺，我也抱紧你。","paragraph":8,"style":"plain","start":484.506,"end":487.86},{"text":"一生中会遇到很多坏事，说天天开心好像太假了一点，","paragraph":9,"style":"plain","start":489.08,"end":493.8},{"text":"希望我们总有勇气去坦然地淋一场突如其来的雨。","paragraph":9,"style":"plain","start":494.88,"end":498.84},{"text":"我喜欢你，下封见。","paragraph":10,"style":"closing","start":499.74,"end":501.66}]},{"id":"next-letter","title":"letter03💌","category":"letter","duration":599.980375,"audio":"next-letter.mp3","palette":["#7d5948","#5b5045"],"cues":[{"text":"早上我走在路上。","paragraph":0,"style":"plain","start":1.54,"end":2.92},{"text":"阳光先洒入我的脸，再一截一截洒满身体。","paragraph":0,"style":"plain","start":3.66,"end":7.92},{"text":"冬天的风似乎带着暖，吹动蓬松的树叶。","paragraph":0,"style":"plain","start":9.02,"end":13.22},{"text":"一抬头，看见头顶那片干净的天空，忽然想问问你：你会偏爱蓝色吗？","paragraph":0,"style":"plain","start":14.8,"end":21.14},{"text":"天空、深海、暮色里的远山、画布上的颜料，还有陶瓷上的釉色，","paragraph":1,"style":"plain","start":22.54,"end":29.42},{"text":"以及我们常常会拿来形容情绪的特质的一些词，比如忧郁、澄明、辽阔，","paragraph":1,"style":"plain","start":30.24,"end":37.86},{"text":"都有蓝色的影子。","paragraph":1,"style":"plain","start":38.78,"end":40.02},{"text":"在远古的环境里，蓝色是安全的信号，头顶恒定的天穹，源源不断的水源，","paragraph":1,"style":"plain","start":40.8,"end":48.48},{"text":"这些都是生存得以延续的根基。","paragraph":1,"style":"plain","start":48.48,"end":51.4},{"text":"红色常常关联着火焰、危险，而绿色代表着生机。","paragraph":1,"style":"plain","start":52.72,"end":57.82},{"text":"蓝色呢，大多就指向遥远、稳定，不会骤然侵袭我们的事物。","paragraph":1,"style":"plain","start":58.48,"end":64.8},{"text":"很长一段时间里，蓝色是极其昂贵稀缺的。","paragraph":1,"style":"plain","start":65.54,"end":69.22},{"text":"在古代大地上，容易获取的颜料是赭石、炭黑、土黄，","paragraph":1,"style":"plain","start":70.04,"end":75.46},{"text":"能做成稳定的蓝色染料的材料特别少，比如说像青金石，要从遥远的地域去开采，","paragraph":1,"style":"plain","start":76.26,"end":83.6},{"text":"再研磨成粉，最后才能够绘制佛像、经卷。","paragraph":1,"style":"plain","start":84.22,"end":87.8},{"text":"所以你看，蓝色是昂贵的、神圣的，不属于俗世喧嚣的。","paragraph":1,"style":"plain","start":88.54,"end":93.56},{"text":"它也特别奇妙，形成了一种反差：我们日日抬头都能看见的蓝天，可是想要握住蓝色，","paragraph":1,"style":"plain","start":94.36,"end":102.06},{"text":"把它留在纸张、经卷上，却非常困难。","paragraph":1,"style":"plain","start":102.56,"end":105.6},{"text":"人的心里往往会有两种很矛盾的状态，一边很向往安宁，另一边对于未知又充满着渴望。","paragraph":1,"style":"plain","start":106.66,"end":114.2},{"text":"我们迷恋蓝色，本质上是在迷恋蓝色的特质——它拥有边界，却又无限延展；","paragraph":1,"style":"plain","start":115.0,"end":122.04},{"text":"它近在眼前，却又无法攥在手里。","paragraph":1,"style":"plain","start":122.88,"end":125.32},{"text":"蓝色就好像是在提醒我们，我们一定会拥有更大的空间，","paragraph":1,"style":"plain","start":125.64,"end":130.04},{"text":"可以容纳所有我们未说出口的向往，以及对无穷之境的想象。","paragraph":1,"style":"plain","start":130.58,"end":136.8},{"text":"遇见你之后，那些原本藏在心里、未说出口的向往，突然都长出了想要递出去的形状。","paragraph":2,"style":"plain","start":137.52,"end":144.98},{"text":"平时表达自己其实是一件很累的事情，像从我凌乱的一天里剪出一团毛线，","paragraph":2,"style":"plain","start":145.82,"end":152.54},{"text":"慢吞吞地缠起来，跟人说哪里是头，哪里是尾；","paragraph":2,"style":"plain","start":153.0,"end":157.32},{"text":"可绝大部分时间，我连气都不叹，就决定算了。","paragraph":2,"style":"plain","start":157.98,"end":162.76},{"text":"唯独对你不一样。","paragraph":2,"style":"plain","start":162.947,"end":164.02},{"text":"生活是个动词，生活分享给了谁，爱就分享给了谁。","paragraph":2,"style":"plain","start":165.02,"end":170.02},{"text":"当我看见世间一切细碎美好的事物时，","paragraph":2,"style":"plain","start":171.22,"end":173.72},{"text":"第一时间就想分享给你——比如路上看到奇形怪状的云，超美的晚霞，","paragraph":2,"style":"plain","start":174.26,"end":180.64},{"text":"吃到一口很好吃的菜，刷到一个非常治愈的视频。","paragraph":2,"style":"plain","start":181.26,"end":185.12},{"text":"这种下意识其实就是分享欲，它不是倾诉，也不是情绪的倾倒，","paragraph":2,"style":"plain","start":186.04,"end":191.833},{"text":"它就是我想让你参与我的普通人生，我的平平无奇，我的喜怒哀乐，我的无聊瞬间。","paragraph":2,"style":"plain","start":192.24,"end":199.1},{"text":"在琐碎和日常的那些生活当中，分享欲才是最高级的浪漫。","paragraph":2,"style":"plain","start":199.78,"end":205.06},{"text":"只是有些心意，一旦开了头，便再也由不得自己收住了。","paragraph":3,"style":"plain","start":206.16,"end":210.7},{"text":"最初向你靠近时，心里满是看见好风景的新奇与欢喜，觉得跟你说话格外舒展；","paragraph":3,"style":"plain","start":211.46,"end":218.62},{"text":"后来日子一天天叠上去，那点喜欢在不知不觉间越酿越浓，渗进了白昼与黑夜的每一道缝隙；","paragraph":3,"style":"plain","start":219.32,"end":227.92},{"text":"再往后，它变得越来越热烈，滚烫得让人几乎招架不住，直到如今，早已到了不能自已的地步。","paragraph":3,"style":"plain","start":228.6,"end":237.3},{"text":"一天有二十四个小时，我就这样想了你很多次。","paragraph":3,"style":"plain","start":238.44,"end":242.16},{"text":"今天天气很好想你一次，吃了什么早饭想你一次，上班摸鱼的时候想你一次，","paragraph":3,"style":"plain","start":243.08,"end":250.62},{"text":"工作餐吃什么想你一次，下班之后看见人来人往、车水马龙，或者短暂美丽的落日晚霞，","paragraph":3,"style":"plain","start":251.54,"end":259.96},{"text":"也会想你一次；","paragraph":3,"style":"plain","start":260.52,"end":261.44},{"text":"平安到家了想你一次，偶尔没收到你的消息也想你一次，","paragraph":3,"style":"plain","start":262.46,"end":267.605},{"text":"睡觉之前也会想你一次——梦里想你那次就不算，因为我不是每天都梦见你。","paragraph":3,"style":"plain","start":267.82,"end":275.72},{"text":"只是，当分享欲涌得太满，安静的缝隙里难免会生出一点落差。","paragraph":4,"style":"plain","start":276.98,"end":281.88},{"text":"你习惯把许多心事收在自己的世界里，不爱把日常的琐碎事无巨细地向外摊开，","paragraph":4,"style":"plain","start":282.68,"end":289.787},{"text":"有时离得很近，三言两语就能聊出许多火花，有时又像退回到了自己的轨道上，","paragraph":4,"style":"plain","start":290.26,"end":297.08},{"text":"忽远忽近。","paragraph":4,"style":"plain","start":297.6,"end":298.2},{"text":"常常是我这边兴冲冲地递出一整天的见闻，你那边却只落下一两句简短的回应，","paragraph":4,"style":"plain","start":298.653,"end":304.48},{"text":"或者是一整晚绵长的寂静。","paragraph":4,"style":"plain","start":305.28,"end":307.973},{"text":"人大概都是这样，能坦然接受全然的冷漠，唯独在尝过热络之后突然撞见安静，","paragraph":4,"style":"plain","start":308.4,"end":315.76},{"text":"心里便会跟着空落一下，忍不住去琢磨：怎么突然就安静下来了呢？","paragraph":4,"style":"plain","start":316.34,"end":321.46},{"text":"那些没等来回音的时刻，热腾腾递出去的分享悬在半空，夜深人静时，","paragraph":4,"style":"plain","start":322.1,"end":327.84},{"text":"思绪在期待与落空之间来回打转，也生出过几分说不清的拉扯。","paragraph":4,"style":"plain","start":328.56,"end":333.86},{"text":"直到前几天傍晚起风，空气里带着一点微凉的草木气息，突然让我想起了前阵子桂花盛开的季节。","paragraph":5,"style":"plain","start":335.1,"end":343.66},{"text":"我们好像天生就有一种本能，遇见美好的事物，第一反应就想要留住它。","paragraph":5,"style":"plain","start":344.58,"end":350.16},{"text":"可如今回头去想那短短十几天的桂花香，倒更像是在提醒我，世间很多动人的东西，生来短暂。","paragraph":5,"style":"plain","start":351.0,"end":358.74},{"text":"有一个概念叫做一期一会，它讲的是每一次的相逢都仅此一次、不可复制，","paragraph":5,"style":"plain","start":359.5,"end":366.38},{"text":"所以你要全然投入当下。","paragraph":5,"style":"plain","start":367.04,"end":368.68},{"text":"就像江上清风，山间明月，取之无尽，用之不竭，我们真正能够拥有的，","paragraph":5,"style":"plain","start":369.5,"end":376.12},{"text":"从来都不是事物本身，而是获得那一刻的感知。","paragraph":5,"style":"plain","start":376.58,"end":379.66},{"text":"生活里有太多这样短暂的美好了，我们只需要完整地接住那一瞬间，然后好好感受，认真看见；","paragraph":5,"style":"plain","start":380.88,"end":388.5},{"text":"当它离开的时候，允许自己怅然，然后轻轻道别。","paragraph":5,"style":"plain","start":389.56,"end":393.92},{"text":"我们总在寻找永不消失的美好，可世间很多动人的事物，本就是刹那的馈赠。","paragraph":5,"style":"plain","start":394.62,"end":401.093},{"text":"想通了这一点，心里的弦便慢慢松了下来。","paragraph":6,"style":"plain","start":401.38,"end":405.0},{"text":"当下的我，曾一度也太迷恋一种叫做“情绪稳定”的东西了，好像只有心如止水、","paragraph":6,"style":"plain","start":405.38,"end":411.98},{"text":"毫无波澜，才算得上通透。","paragraph":6,"style":"plain","start":411.98,"end":414.52},{"text":"直到后来才慢慢体悟到，人的一生，大抵会依次遇见尼采、加缪与庄子。","paragraph":6,"style":"plain","start":415.08,"end":421.98},{"text":"年轻的时候，先撞见尼采，劈开迷雾，告诉你说价值要自己创造，","paragraph":6,"style":"plain","start":422.74,"end":428.92},{"text":"于是你意识到依赖的权威并不存在，必须成为自己的光；","paragraph":6,"style":"plain","start":429.48,"end":434.26},{"text":"接着加缪又来了，你看到推着石头上山的西西弗不是幸福的，因为他登上顶峰的斗争，","paragraph":6,"style":"plain","start":435.26,"end":443.3},{"text":"足以充实一切重要，因此重要的不是治愈，而是要带着病痛活下去；","paragraph":6,"style":"plain","start":443.53,"end":449.28},{"text":"最后，庄子化成蝴蝶翩翩而来，他微笑拂袖指给你看，说天地有大美，万物皆可逍遥，","paragraph":6,"style":"plain","start":450.46,"end":458.4},{"text":"你这才发现，对抗本身仍是执着。","paragraph":6,"style":"plain","start":458.79,"end":462.34},{"text":"于是你松开拳头，让风穿过指缝——不再推石头，你已成了山的一部分；","paragraph":6,"style":"plain","start":462.68,"end":471.22},{"text":"不再追问意义，你已流淌成了江河。","paragraph":6,"style":"plain","start":471.8,"end":475.9},{"text":"松开拳头之后，那些在期待与静默之间打转的执念，也就跟着化开了。","paragraph":7,"style":"plain","start":476.9,"end":482.5},{"text":"其实我们每个人，都在这无序的世界里，努力活出自己有序的节奏。","paragraph":7,"style":"plain","start":483.08,"end":487.82},{"text":"允许自己在人群中感到孤独是一种自由，不要为了合群而破坏自己的节奏是一种自由，","paragraph":7,"style":"plain","start":488.48,"end":495.7},{"text":"坦然接受失去和得到也是一种自由。","paragraph":7,"style":"plain","start":496.12,"end":499.5},{"text":"这些种种的自由，才最终构成了那个不被任何人定义的完整的自我。","paragraph":7,"style":"plain","start":499.92,"end":505.3},{"text":"既然如此，我便不再强求每份热情都必须立刻等来回响，也不必为了显得豁达而假装无所谓。","paragraph":7,"style":"plain","start":505.86,"end":514.78},{"text":"真正的成熟不是没有情绪，而是允许悲和喜同时存在；","paragraph":7,"style":"plain","start":515.44,"end":519.74},{"text":"很多事情当下纠缠不清，心结一时解不开，便不强求马上得到一个结果，","paragraph":7,"style":"plain","start":520.52,"end":526.08},{"text":"也不逼自己立刻看透，把一时想不通的落差先放一放，交给时间，日子往前走，","paragraph":7,"style":"plain","start":526.96,"end":533.96},{"text":"局势总会慢慢明朗，对错取舍也终会自然分出昼和夜。","paragraph":7,"style":"plain","start":534.54,"end":540.09},{"text":"况且，如果这一切只是我过重的思念在大脑里的狂欢，那么想念你的时候，","paragraph":7,"style":"plain","start":540.44,"end":547.12},{"text":"我的心也已经在放烟火了。","paragraph":7,"style":"plain","start":547.54,"end":549.92},{"text":"喜欢从来不是一次性的誓言，它是千千万万次微小的奔赴，是理解、包容、承担与守护。","paragraph":7,"style":"plain","start":550.82,"end":560.0},{"text":"如果一次不够，那就一千次；","paragraph":7,"style":"plain","start":560.8,"end":562.84},{"text":"如果一千次不够，那就千千万万遍。","paragraph":7,"style":"plain","start":563.28,"end":566.83},{"text":"有时候，会很喜欢看你穿蓝色的衣服","paragraph":8,"style":"note","start":567.72,"end":570.44},{"text":"从此，看海看天，都心不在焉。","paragraph":8,"style":"note","start":571.34,"end":574.22},{"text":"明知那些蓝，各有各的深浅，","paragraph":8,"style":"note","start":575.04,"end":577.12},{"text":"眼里浮起的，还是你的容颜","paragraph":8,"style":"note","start":577.9,"end":579.98},{"text":"我会在这深浅不一的蓝色里，偷偷沦陷。","paragraph":8,"style":"note","start":581.22,"end":584.984},{"text":"一抬头，把每一抹蓝，都当成我们拥抱的瞬间。","paragraph":8,"style":"note","start":585.34,"end":589.38},{"text":"自此，你在云端，也在心尖。","paragraph":8,"style":"note","start":590.2,"end":593.91},{"text":"我喜欢迷湖宝宝，下一封见","paragraph":9,"style":"closing","start":594.6,"end":596.54}]},{"id":"too-long","title":"好像时间又有点长","category":"story","duration":1534.223667,"audio":"too-long.mp3","palette":["#465f52","#6a6950"],"cues":[{"text":"你相信缘分吗？","paragraph":0,"style":"plain","start":1.26,"end":2.58},{"text":"前段时间，我的订婚宴，亲朋好友们都在家里来吃饭。","paragraph":1,"style":"plain","start":3.58,"end":8.58},{"text":"饭后前的没事干了，他们就坐在电视机前，翻看我跟未婚妻的相册。","paragraph":2,"style":"plain","start":9.3,"end":14.6},{"text":"其中有一张照片让他们不停地问同一个问题。","paragraph":3,"style":"plain","start":15.54,"end":18.76},{"text":"这张照片里，你怎么在跟花花打架呀？","paragraph":4,"style":"plain","start":19.76,"end":22.7},{"text":"那是一张我高二时候的照片，当年我17岁，还很年轻。","paragraph":5,"style":"plain","start":23.7,"end":28.24},{"text":"跟我现在的未婚妻，也就是当年的高中同学，狠狠地打了一架，不分胜负。","paragraph":6,"style":"plain","start":29.0,"end":34.76},{"text":"我倒好凶对老王，看认了不前事大，投拍下了未来打赛的这张照片，时候发给我。","paragraph":7,"style":"plain","start":35.66,"end":41.56},{"text":"我保留至今，算是我最喜欢的一张我们之间的合影。","paragraph":8,"style":"plain","start":42.56,"end":47.04},{"text":"十多年前，我凭着全校前十的分数，考上了我们现成最好的高中，","paragraph":9,"style":"plain","start":48.16,"end":52.98},{"text":"可能是成绩带给我的自信当时年轻又愚蠢的我","paragraph":10,"style":"plain","start":53.66,"end":57.5},{"text":"优雅感十足不把任何人放在眼里","paragraph":12,"style":"plain","start":57.5,"end":60.2},{"text":"开始第一天办理鸡鸡沙沙的特别吵","paragraph":14,"style":"plain","start":60.98,"end":63.96},{"text":"其中有一个女生嗓门又其大","paragraph":16,"style":"plain","start":64.72,"end":67.06},{"text":"还得我特别近我耳膜都要被她震碎了","paragraph":18,"style":"plain","start":67.48,"end":70.7},{"text":"我就故意加上了嗓门燕阳怪气的","paragraph":20,"style":"plain","start":71.2,"end":73.98},{"text":"对空气说了一句人没长多大","paragraph":22,"style":"plain","start":73.98,"end":77.06},{"text":"嗓门倒挺大然后呢","paragraph":24,"style":"plain","start":77.06,"end":80.06},{"text":"就被她听到了她转过头","paragraph":26,"style":"plain","start":80.06,"end":82.46},{"text":"凶狠狠地盯着我，然后拿手指指着我。","paragraph":28,"style":"plain","start":82.86,"end":85.9},{"text":"哎，你说什么呢？","paragraph":29,"style":"plain","start":86.24,"end":87.72},{"text":"我立刻就来气了。","paragraph":30,"style":"plain","start":88.9,"end":90.1},{"text":"我说你嗓门大，怎么了？","paragraph":31,"style":"plain","start":90.84,"end":92.64},{"text":"那你不会好好说哈，阴阳怪气什么呢？","paragraph":32,"style":"plain","start":93.82,"end":96.22},{"text":"我就阴阳怪气你，怎么了？","paragraph":33,"style":"plain","start":97.24,"end":98.92},{"text":"大嗓门。","paragraph":34,"style":"plain","start":99.28,"end":99.66},{"text":"他见证，举起拳头，装穿一副要打我的样子。","paragraph":35,"style":"plain","start":100.72,"end":103.94},{"text":"我不为所动，甚至继续火上加油。","paragraph":36,"style":"plain","start":104.54,"end":106.76},{"text":"你嗓门大还有礼物是吧？","paragraph":37,"style":"plain","start":107.52,"end":109.06},{"text":"你还要揍我？","paragraph":38,"style":"plain","start":109.5,"end":110.2},{"text":"来来来，朝我到脑门上打。","paragraph":39,"style":"plain","start":110.7,"end":112.22},{"text":"不得不承认啊我当时绝对低估了他的报道程度","paragraph":40,"style":"plain","start":113.66,"end":117.62},{"text":"要不是有同学大喊一声班主任来了","paragraph":42,"style":"plain","start":118.22,"end":120.62},{"text":"他的拳头还真要揍在我的脑袋上开始第一课","paragraph":44,"style":"plain","start":121.06,"end":125.82},{"text":"全班要做自我介绍我得出了些嗓门大","paragraph":46,"style":"plain","start":126.3,"end":129.58},{"text":"脾气臭报道如雷的小姑娘姓袁","paragraph":48,"style":"plain","start":129.58,"end":132.06},{"text":"单名一个花圆花","paragraph":50,"style":"plain","start":132.58,"end":134.64},{"text":"要我说啊圆花名字中间的花","paragraph":52,"style":"plain","start":135.26,"end":137.74},{"text":"那一定是霸王花的花霸王花人长挺高的","paragraph":54,"style":"plain","start":138.1,"end":142.2},{"text":"一米七的样子长得还挺好看","paragraph":56,"style":"plain","start":142.2,"end":144.88},{"text":"就是这个脾气太暴躁了当时排座位的时候","paragraph":58,"style":"plain","start":145.42,"end":148.82},{"text":"老师竟然还把他安排在我的前座尽管开学的第一天","paragraph":60,"style":"plain","start":149.3,"end":154.34},{"text":"我俩就差点拿起来但高中时代的感情","paragraph":62,"style":"plain","start":154.34,"end":157.52},{"text":"跟位子之间的距离还是有很大关系的","paragraph":64,"style":"plain","start":157.52,"end":160.3},{"text":"位子离得越近就很容易玩得越好","paragraph":66,"style":"plain","start":160.98,"end":163.4},{"text":"我俩也算是不骂不相识再加上我又是个喜欢挑衅女生的主","paragraph":68,"style":"plain","start":164.16,"end":169.36},{"text":"前后中的那段时间我俩经常一起闹着玩","paragraph":70,"style":"plain","start":169.96,"end":172.84},{"text":"我老说她她老揍我","paragraph":72,"style":"plain","start":173.26,"end":175.34},{"text":"那我就不要脸地接着说大事情 骂事爱","paragraph":74,"style":"plain","start":176.34,"end":179.76},{"text":"爱到不行你就用脚踹","paragraph":76,"style":"plain","start":179.76,"end":181.8},{"text":"你今天要是敢打我你就说暗恋我","paragraph":78,"style":"plain","start":182.42,"end":184.92},{"text":"现在想想当年说这话的我","paragraph":80,"style":"plain","start":185.8,"end":188.16},{"text":"也特别不要脸不过那天","paragraph":82,"style":"plain","start":188.16,"end":191.32},{"text":"也是我人生中第一次受到女生","paragraph":84,"style":"plain","start":191.32,"end":193.72},{"text":"如此狂热的表白圆滑眼啊切齿","paragraph":86,"style":"plain","start":193.72,"end":196.8},{"text":"举之全都对我说我暗恋你","paragraph":88,"style":"plain","start":196.8,"end":199.6},{"text":"我他们暗恋死你了你看我打不打死你","paragraph":90,"style":"plain","start":200.06,"end":203.08},{"text":"那天他拿着他的雨伞追着我打绕了教学楼整整三圈","paragraph":92,"style":"plain","start":204.12,"end":208.08},{"text":"要不是上课领响了我屁股都要被他打开的话","paragraph":94,"style":"plain","start":208.54,"end":211.72},{"text":"班尼的同学觉得我俩就是一对冤家走到哪儿打到哪儿","paragraph":96,"style":"plain","start":212.94,"end":217.36},{"text":"谁看谁都不说在无数爱情故事的人物设定里","paragraph":98,"style":"plain","start":217.36,"end":221.64},{"text":"一旦男女主整天待在一起那不管做什么","paragraph":100,"style":"plain","start":221.98,"end":225.72},{"text":"他们俩很快就会陷入爱情的深渊了但我跟八王花可不太一样","paragraph":102,"style":"plain","start":226.04,"end":231.06},{"text":"如果说高一吵架说了点第一次的摩擦那高二打架就是我们关系的反向生化","paragraph":104,"style":"plain","start":231.72,"end":237.8},{"text":"爱情的深渊是见不到了但有情的末日估计是要来了","paragraph":106,"style":"plain","start":238.32,"end":242.66},{"text":"至于我打高一玩那么好高二为啥会打起来","paragraph":108,"style":"plain","start":243.78,"end":247.12},{"text":"这点确实怪我我当时确实不怎么干人事","paragraph":110,"style":"plain","start":247.12,"end":250.88},{"text":"老欺负着女同学老给人取外号那段时间，正逢萨洛特凡脑上一后特别火","paragraph":112,"style":"plain","start":251.48,"end":257.6},{"text":"留下了很多全是鸣梗其中就包括那句非常经典的","paragraph":114,"style":"plain","start":258.26,"end":262.02},{"text":"《沃烤》《元华》","paragraph":116,"style":"plain","start":262.5,"end":263.52},{"text":"因为《元华》的名字跟《元华》实在太过于相近难免会让人把他跟那个梗联想在一起","paragraph":118,"style":"plain","start":264.56,"end":270.34},{"text":"当时我们班里在《元华》面前玩这个梗的最多的就是我","paragraph":120,"style":"plain","start":271.3,"end":275.5},{"text":"因为是前后桌的关系嘛我经常莫名其妙地拍拍他的肩膀","paragraph":122,"style":"plain","start":276.08,"end":279.96},{"text":"然后等他转过头在顾作惊讶的大海影剧","paragraph":124,"style":"plain","start":280.62,"end":283.54},{"text":"我靠，圆滑那一般这种情况呢","paragraph":126,"style":"plain","start":283.54,"end":287.46},{"text":"圆滑都会非常无语且暴躁地冲我大喊一句","paragraph":128,"style":"plain","start":287.46,"end":290.6},{"text":"你想死啊每次他骂我的时候","paragraph":130,"style":"plain","start":290.6,"end":293.62},{"text":"我都会因为我的小金谋得逞而哈哈大叫","paragraph":132,"style":"plain","start":293.62,"end":296.62},{"text":"但后来似乎是我玩的有些过火了一个梗翻来覆去","paragraph":134,"style":"plain","start":297.5,"end":301.66},{"text":"不分场合的玩多了就已经失去了最初用来娱乐的作用","paragraph":136,"style":"plain","start":301.66,"end":305.82},{"text":"戏弄人名字这件事确实是我做的不对","paragraph":138,"style":"plain","start":306.46,"end":309.14},{"text":"而且圆滑同学的脾气也不是好惹的","paragraph":140,"style":"plain","start":310.24,"end":312.98},{"text":"有天当我又在莫名其妙地对他玩这个梗的时候他生气了","paragraph":142,"style":"plain","start":313.84,"end":318.72},{"text":"真的生气了特别的生气","paragraph":144,"style":"plain","start":318.72,"end":320.88},{"text":"二话不说寄往我的脑门来了一圈","paragraph":146,"style":"plain","start":321.22,"end":323.86},{"text":"我感到一只炫云顺势往后一躺","paragraph":148,"style":"plain","start":324.56,"end":327.22},{"text":"嘴里还固执着说好难不跟女斗","paragraph":150,"style":"plain","start":327.74,"end":330.44},{"text":"你现在手手还来得及但紧接着","paragraph":152,"style":"plain","start":330.82,"end":333.72},{"text":"又是一只狂风暴雨的拳都垂了下来打得我赶紧认错","paragraph":154,"style":"plain","start":333.72,"end":337.78},{"text":"但霸王花爆色的脾气可不可以赶你认不认错","paragraph":156,"style":"plain","start":338.78,"end":341.66},{"text":"紧接着他就把我桌上用树对点起来的长城推倒在地","paragraph":158,"style":"plain","start":342.18,"end":346.4},{"text":"目光随意地转移到桌下我的脚包落在了他的视野里","paragraph":160,"style":"plain","start":347.04,"end":351.02},{"text":"他邪媚的一笑用尽了全身的力气","paragraph":162,"style":"plain","start":351.54,"end":354.22},{"text":"狠狠地踩上了一脚把我疼得只抽出","paragraph":164,"style":"plain","start":354.22,"end":357.86},{"text":"生回的时候膝盖还撞到了桌板","paragraph":166,"style":"plain","start":358.36,"end":360.7},{"text":"把我给疼死了傍晚花对我的报复得逞了","paragraph":168,"style":"plain","start":361.4,"end":365.0},{"text":"可我也有些生气了你骂我打我都没问题","paragraph":170,"style":"plain","start":365.3,"end":368.54},{"text":"但你别猜我刚买的新鞋啊鞋子可是男孩的小命","paragraph":172,"style":"plain","start":368.92,"end":372.84},{"text":"踩在鞋上 痛在我心呢我伸出手抓住他的头发","paragraph":174,"style":"plain","start":373.18,"end":377.86},{"text":"想要阻止他继续对我发起进攻但是愚蠢了我 唯独忘了一点","paragraph":176,"style":"plain","start":377.86,"end":382.52},{"text":"头发那也是女生的命根啊霸王花对我发起的进攻更加猛烈了","paragraph":178,"style":"plain","start":382.96,"end":388.34},{"text":"当时在我好兄弟老王的眼中他说我俩打架挺好笑的","paragraph":180,"style":"plain","start":388.84,"end":392.52},{"text":"一个呢只会抓头发另一个只会踩鞋","paragraph":182,"style":"plain","start":392.92,"end":396.22},{"text":"一个进攻，一个躲，跟玩回合制的游戏一样","paragraph":184,"style":"plain","start":396.84,"end":400.22},{"text":"甚至好笑到他在拿出了偷藏的手机拍了段照片之后在慢吞吞的上了圈架","paragraph":185,"style":"plain","start":400.88,"end":406.58},{"text":"后来也不知道是哪个同学就告诉了班主任班主任刚开完会，就急速速地赶过来","paragraph":187,"style":"plain","start":408.06,"end":413.78},{"text":"大喊了一声，你们两个给我助手我这个时候才把拽着他头发的手松开","paragraph":189,"style":"plain","start":413.78,"end":419.46},{"text":"他也不再继续踩我的心血了打完这次下以后，班主任跟我们换了位置","paragraph":191,"style":"plain","start":419.9,"end":426.0},{"text":"我去了最东边，他去了最西边。","paragraph":193,"style":"plain","start":426.4,"end":428.78},{"text":"两个人隔得很远，学生时代的感情跟位子之间的距离真的有很大的关系。","paragraph":194,"style":"plain","start":429.52,"end":435.38},{"text":"他的头发掉了，我的心血脏了，朋友的关系闹掰了，前后的作为也换掉了。","paragraph":195,"style":"plain","start":436.16,"end":442.04},{"text":"话呢，也就不用再说了。","paragraph":196,"style":"plain","start":442.56,"end":444.36},{"text":"我心里其实很清楚，这件事归根结底是我做的不对。","paragraph":197,"style":"plain","start":445.22,"end":449.1},{"text":"我欠他一个道歉，但已经找不到合适的机会开口了。","paragraph":198,"style":"plain","start":449.86,"end":454.08},{"text":"接下来的整整一年，我们俩基本上都没有用正眼抢过对方，我是不敢，他应该是不屑吧。","paragraph":199,"style":"plain","start":455.1,"end":462.02},{"text":"一直到了高三，我因为成绩优异，被班主任，任免为了学习委员，","paragraph":200,"style":"plain","start":462.9,"end":468.2},{"text":"让同学们有不会的问题就来找我。","paragraph":200,"style":"plain","start":468.76,"end":470.6},{"text":"不管高一高二，玩都有多丰的人，一到了高三，大家都会冷静下来，","paragraph":201,"style":"plain","start":471.62,"end":476.14},{"text":"但你的学习氛围立刻就变成十分浓厚。","paragraph":201,"style":"plain","start":476.8,"end":479.12},{"text":"也正是在这种很浓的学习氛围下我看的关系因为一道数学题","paragraph":202,"style":"plain","start":479.9,"end":484.9},{"text":"迎来了破冰的机会有天来问我题目的同学里","paragraph":204,"style":"plain","start":485.22,"end":489.08},{"text":"出现了一个熟悉的声音没错 就是圆花","paragraph":206,"style":"plain","start":489.58,"end":493.02},{"text":"起初他还有些不好意思的跟我说哎 这题我不会做 你能教教我吗","paragraph":208,"style":"plain","start":493.86,"end":499.28},{"text":"我当时很尴尬我不知道怎么跟他沟通","paragraph":210,"style":"plain","start":500.12,"end":502.82},{"text":"就想跟他开个愚蠢的小玩笑先拉近一下距离","paragraph":212,"style":"plain","start":503.36,"end":506.52},{"text":"第一 我不叫哀哎 第二","paragraph":214,"style":"plain","start":507.3,"end":509.12},{"text":"没懂我话说完的他竟然转头就走了","paragraph":216,"style":"plain","start":510.3,"end":512.8},{"text":"我立刻找补哎哎 快回来回来回来","paragraph":218,"style":"plain","start":513.16,"end":516.2},{"text":"我教你 我教你还不行他立刻就停在","paragraph":220,"style":"plain","start":516.2,"end":519.56},{"text":"转过身来看我墙边这一丝笑容","paragraph":222,"style":"plain","start":519.56,"end":522.34},{"text":"那是高三的某个不知名的傍晚他撞过头来的时候","paragraph":224,"style":"plain","start":523.1,"end":527.0},{"text":"窗外吹进了一阵温柔的风外面的世界被粉丝的晚霞组包围","paragraph":226,"style":"plain","start":527.34,"end":532.1},{"text":"大家放下了手中的笔聚集在走廊处","paragraph":228,"style":"plain","start":532.54,"end":535.26},{"text":"抬头天望着那片写着希望与未来的天空","paragraph":230,"style":"plain","start":535.58,"end":538.6},{"text":"犹华同学又跟我讲话了我总感觉有什么东西是爱负责了","paragraph":232,"style":"plain","start":539.54,"end":544.4},{"text":"是友情吗不知道","paragraph":234,"style":"plain","start":544.4,"end":546.24},{"text":"但绝对不可能是爱情姑且乘之为高尚的同学情义吧","paragraph":236,"style":"plain","start":546.66,"end":551.12},{"text":"出于高尚的同学情义高三的我帮他解决了很多的数学问题","paragraph":238,"style":"plain","start":552.12,"end":556.44},{"text":"虽然他的嘴里从来都没有跟我说过任何一句感谢的话","paragraph":240,"style":"plain","start":557.24,"end":560.68},{"text":"但我知道高三我周天里","paragraph":242,"style":"plain","start":561.08,"end":563.24},{"text":"每隔几天就会出现的小零食应该都是出自他手吧","paragraph":244,"style":"plain","start":563.24,"end":567.1},{"text":"跟原画同学成为冤家的高中三年有过有效 有痛有累 有吃也有喝","paragraph":246,"style":"plain","start":568.02,"end":573.76},{"text":"所以当高稿一结束 大家都清楚以后不会再会有一批人","paragraph":248,"style":"plain","start":574.54,"end":579.22},{"text":"默契的会放下手中的笔齐聚在走廊处","paragraph":250,"style":"plain","start":579.22,"end":582.46},{"text":"抬头天望着那片写着希望与未来的天空","paragraph":252,"style":"plain","start":582.86,"end":586.02},{"text":"很多事情很多人可能都要一去不复返了","paragraph":254,"style":"plain","start":586.84,"end":589.9},{"text":"成绩出来以后 我考去了南京不知道他考去了哪里，我也没有主动问。","paragraph":256,"style":"plain","start":590.8,"end":596.38},{"text":"只是听同学说他考得好像还不错，甚至超长发挥。","paragraph":258,"style":"plain","start":596.9,"end":600.68},{"text":"他爸妈还在词里，瞧到打鼓地给他搭搭搭一场演习。","paragraph":259,"style":"plain","start":601.46,"end":605.04},{"text":"一般来说，大部分高中同学联系到这里就断调了。","paragraph":260,"style":"plain","start":606.0,"end":609.9},{"text":"下次再听到相关的消息，要么是婚信，要么是死去。","paragraph":261,"style":"plain","start":610.68,"end":615.28},{"text":"可我怎么都没有想到，我跟袁华同学还真就是被上天错误成的欢学院长。","paragraph":262,"style":"plain","start":616.3,"end":622.02},{"text":"原分这件事，你说不准，也摸不透。","paragraph":263,"style":"plain","start":622.76,"end":625.68},{"text":"因为就在大学新生报道的第一天，我竟然在我们学校的大门口撞见了他。","paragraph":264,"style":"plain","start":626.58,"end":631.6},{"text":"我靠，原花，你怎么在这儿？","paragraph":265,"style":"plain","start":632.52,"end":635.14},{"text":"他看到了我，也同样接纳了发问。","paragraph":266,"style":"plain","start":635.8,"end":637.98},{"text":"我来报道啊，我还想问你怎么在这儿呢？","paragraph":267,"style":"plain","start":638.6,"end":641.16},{"text":"我到大脑突然间变得有些呆滞，但心中又有一丝愚月感永来。","paragraph":268,"style":"plain","start":642.18,"end":646.52},{"text":"你不会是暗恋我吧？","paragraph":269,"style":"plain","start":647.22,"end":648.62},{"text":"偷偷摸摸跟我砍到一个学校来。","paragraph":270,"style":"plain","start":649.18,"end":651.02},{"text":"不会吧你听到我这么不要脸地说话","paragraph":271,"style":"plain","start":651.48,"end":654.8},{"text":"他又摆出那副我熟悉的八万花的模样你要死啊 我是自己考来的好吧","paragraph":273,"style":"plain","start":655.16,"end":660.58},{"text":"谁他们会暗恋你 真是臭不要脸后来的事实也证明","paragraph":275,"style":"plain","start":661.16,"end":665.96},{"text":"我跟元华同学之间的感情那绝对是高尚 纯洁 伟大的同学友谊","paragraph":277,"style":"plain","start":665.96,"end":671.78},{"text":"因为开校没多久他就在军训的时候","paragraph":279,"style":"plain","start":671.78,"end":674.68},{"text":"喜欢上了他们班里的一个男生那哥们军训的时候唱了几首好听的歌","paragraph":281,"style":"plain","start":675.2,"end":680.38},{"text":"再加上人还长得白白静静，高高瘦瘦，获得了很多青春少女的放心暗许。","paragraph":283,"style":"plain","start":680.92,"end":686.6},{"text":"那元华同学呢，就是其中一名。","paragraph":284,"style":"plain","start":687.4,"end":689.32},{"text":"有天，他竟然问我如何去追一个男生，我就非常认真的帮他做灵魁餐吗？","paragraph":285,"style":"plain","start":690.34,"end":695.78},{"text":"我说你想追男生啊，简单，你就记住，大部分的男生都没脑子。","paragraph":286,"style":"plain","start":696.46,"end":702.2},{"text":"只要女生轻轻挥动露出大腿的裙摆，他们就会经常上脑，打着寻找爱情的借口，","paragraph":287,"style":"plain","start":702.86,"end":708.46},{"text":"说着交换灵魂的理由缠着青春少女的肉体","paragraph":288,"style":"plain","start":708.8,"end":712.14},{"text":"屁点屁点的就在找你谈所谓的恋爱呢你觉得我说的对吗","paragraph":290,"style":"plain","start":712.52,"end":717.22},{"text":"是不是有点太偏激太主观了有点不对对吧","paragraph":292,"style":"plain","start":717.22,"end":721.18},{"text":"但不对那就对了呀我又没有追过男生","paragraph":294,"style":"plain","start":721.18,"end":724.32},{"text":"我怎么知道怎么追男生我就瞎说逗他玩","paragraph":296,"style":"plain","start":724.32,"end":727.48},{"text":"他不会真信吗可他还真就信了","paragraph":298,"style":"plain","start":727.48,"end":730.7},{"text":"就是这么单纯这爆炸的霸王花","paragraph":300,"style":"plain","start":730.7,"end":733.5},{"text":"变成了纯洁的小百合我跟他高中认识三年","paragraph":302,"style":"plain","start":733.88,"end":737.3},{"text":"浪神没见过他穿一回裙子正当小百合准备回动他露出大队的前辈的时候","paragraph":304,"style":"plain","start":737.3,"end":742.88},{"text":"对心仪之人发起猛烈进攻的时候我们学校的表白奖商出现了一个展新乍烈的情感大瓜","paragraph":306,"style":"plain","start":743.28,"end":749.82},{"text":"军信唱歌好听的那哥们儿被人挂了说是异地链弹了一个","paragraph":308,"style":"plain","start":750.7,"end":755.46},{"text":"校外弹了一个学校内撩了一个","paragraph":310,"style":"plain","start":755.92,"end":758.4},{"text":"脚踏三只船多次发生不正当的男女关系","paragraph":312,"style":"plain","start":758.78,"end":762.14},{"text":"还不带套被异地女友捉尖在窗","paragraph":314,"style":"plain","start":762.64,"end":765.28},{"text":"总之船的很离谱但估计搬着漫加吧","paragraph":316,"style":"plain","start":765.28,"end":768.84},{"text":"听到这个消息的时候我在突出管理学习","paragraph":318,"style":"plain","start":769.68,"end":772.42},{"text":"出于高尚的同学友谊我还是决定关心一下她","paragraph":320,"style":"plain","start":772.82,"end":776.1},{"text":"结果人压根就不理我那我也没办法","paragraph":322,"style":"plain","start":776.68,"end":779.74},{"text":"外面还下着大雨呢我要赶紧回警示呢","paragraph":324,"style":"plain","start":779.74,"end":782.52},{"text":"可没想到我刚从突出管理出来打扫回去的路上","paragraph":326,"style":"plain","start":783.22,"end":786.82},{"text":"就看见了一个熟悉的声音慢慢的走在雨里","paragraph":328,"style":"plain","start":787.22,"end":790.56},{"text":"是那么的瘦弱孤独","paragraph":330,"style":"plain","start":790.56,"end":792.54},{"text":"岐惨这不是小百合吗","paragraph":332,"style":"plain","start":792.54,"end":794.96},{"text":"他真被渣男给迫害了当时雨下的越来越大","paragraph":334,"style":"plain","start":795.3,"end":798.74},{"text":"我也来不及多想关键吧","paragraph":336,"style":"plain","start":799.08,"end":801.64},{"text":"我也没有过跟异星在一把伞下漫步与宗教团的经验","paragraph":338,"style":"plain","start":801.64,"end":806.18},{"text":"于是不知所措的我莽撞地冲了上去","paragraph":340,"style":"plain","start":806.94,"end":809.6},{"text":"把我的伞塞到他手里只留下了一句别灵语","paragraph":342,"style":"plain","start":809.6,"end":813.9},{"text":"然后转头就跑给小白和留下了一个在大雨中奔跑的背影","paragraph":344,"style":"plain","start":814.52,"end":819.06},{"text":"当时我觉得我的妈帅爆了这不妥妥的偶像剧男主出场吗","paragraph":346,"style":"plain","start":819.78,"end":824.28},{"text":"当然了，耍帅肯定要付出代价的。","paragraph":348,"style":"plain","start":825.26,"end":827.56},{"text":"第二天我就感冒了。","paragraph":349,"style":"plain","start":828.04,"end":829.24},{"text":"秦家在床上躺了一天，一地的餐巾纸，","paragraph":350,"style":"plain","start":829.92,"end":832.86},{"text":"室友回来，还以为我见近人往了呢。","paragraph":352,"style":"plain","start":833.54,"end":835.9},{"text":"室友老周回来的时候，疯狂地喊我的名字。","paragraph":353,"style":"plain","start":837.24,"end":839.92},{"text":"快起来快起来，秦室楼下有一姑娘等你呢。","paragraph":355,"style":"plain","start":840.74,"end":843.4},{"text":"你不整天张招拖单吗？","paragraph":357,"style":"plain","start":844.16,"end":845.54},{"text":"赶紧下去，把握住男女情缘啊。","paragraph":358,"style":"plain","start":845.94,"end":848.06},{"text":"我懵了，问她。","paragraph":359,"style":"plain","start":848.74,"end":850.1},{"text":"那姑娘找我干嘛？","paragraph":360,"style":"plain","start":850.72,"end":851.52},{"text":"哦，他说是还你散那他把散给你，让你带给我不就行了","paragraph":361,"style":"plain","start":852.28,"end":857.18},{"text":"老猪开始破口大妈你来SB，人家哪里是要还散","paragraph":363,"style":"plain","start":857.98,"end":861.92},{"text":"分明是要见你老猪也是个看热的不先事大的人","paragraph":365,"style":"plain","start":862.22,"end":866.08},{"text":"并且把我从床上拉起来赶进了楼","paragraph":367,"style":"plain","start":866.42,"end":869.12},{"text":"南谦楼下小百合穿着一席白裙在等我","paragraph":369,"style":"plain","start":870.04,"end":873.0},{"text":"他手里拿着一把散和一个袋子袋子里装了红培垫的小蛋糕和感冒药","paragraph":371,"style":"plain","start":873.42,"end":878.92},{"text":"还有一杯热奶茶","paragraph":373,"style":"plain","start":879.28,"end":880.28},{"text":"因为感冒，我怕传人给他，我刻意跟他保存了点距离，然后才开过问他，你找我有事吗？","paragraph":374,"style":"plain","start":881.12,"end":888.26},{"text":"随后他用一种我从来没有见过的温柔如水的语气跟我说，我来换你死啊，谢谢你啊。","paragraph":375,"style":"plain","start":889.28,"end":897.5},{"text":"我有些没有反应过来，他接着说，那个你过了天有空吗？","paragraph":376,"style":"plain","start":898.52,"end":903.44},{"text":"我想请你喝杯咖啡。","paragraph":376,"style":"plain","start":904.0,"end":905.04},{"text":"小百合的突然邀请让我有点措手不及我没有拒绝 也没有接受","paragraph":377,"style":"plain","start":906.4,"end":911.06},{"text":"说是几天后给她打复然后连着她弟给我的东西就回了宿舍","paragraph":379,"style":"plain","start":911.66,"end":916.6},{"text":"宿舍的那群狗儿子们一一而上把我的蛋糕给分了","paragraph":381,"style":"plain","start":917.52,"end":921.02},{"text":"你被人追了我立刻解释到","paragraph":383,"style":"plain","start":921.58,"end":924.12},{"text":"混蛋 那是我高中同学前两天下雨给她送了巴塞","paragraph":385,"style":"plain","start":924.12,"end":928.46},{"text":"话说我问你们她约我过两天喝咖啡","paragraph":387,"style":"plain","start":929.34,"end":932.08},{"text":"这什么意思啊我去还是不去","paragraph":389,"style":"plain","start":932.08,"end":934.34},{"text":"吃着我的东西 这群狗儿子自然得给我出主意大致呢 分没两派","paragraph":391,"style":"plain","start":935.18,"end":940.8},{"text":"一派是 道哥 人女孩主动约你 你都不去 你是人啊还有一派呢 嗯 我觉得不能去","paragraph":393,"style":"plain","start":941.28,"end":949.82},{"text":"八成是红门夜 绝对是红门夜你是刘邦 他是相遇","paragraph":395,"style":"plain","start":950.2,"end":954.64},{"text":"但我最终还是决定去了 为什么呢我得给自己找个理由 我想想","paragraph":397,"style":"plain","start":955.72,"end":961.52},{"text":"因为伟大的同学友谊还有不吃东西就会委屈的味","paragraph":399,"style":"plain","start":963.0,"end":967.34},{"text":"所以三天后的周六晚上在我们学校湖中心的咖啡店","paragraph":401,"style":"plain","start":968.42,"end":971.9},{"text":"他约我见的面那里的风景很好","paragraph":403,"style":"plain","start":972.5,"end":975.42},{"text":"一山傍水算是我们学校情侣的约会胜利","paragraph":405,"style":"plain","start":975.76,"end":979.18},{"text":"他主动找我呢主要是为了两件事","paragraph":407,"style":"plain","start":980.0,"end":982.52},{"text":"一是感谢我在雨中给他递了一把伞二是找我这个老同学","paragraph":409,"style":"plain","start":982.52,"end":988.08},{"text":"倾诉下他的大学生活我有些不好意思的问","paragraph":411,"style":"plain","start":988.08,"end":992.02},{"text":"你没被那渣男给祸害吧他立刻解释说","paragraph":413,"style":"plain","start":993.14,"end":996.56},{"text":"没没没我才跟他聊几天","paragraph":415,"style":"plain","start":996.56,"end":998.72},{"text":"就发生这事儿你说是不是所有男的","paragraph":417,"style":"plain","start":998.72,"end":1002.44},{"text":"都跟你说的一样只穿身子 不谈爱情","paragraph":419,"style":"plain","start":1002.44,"end":1005.58},{"text":"我就才意识到我在纯洁的小百合","paragraph":421,"style":"plain","start":1006.68,"end":1009.32},{"text":"还真把我说的胡话给听进去了","paragraph":423,"style":"plain","start":1009.32,"end":1011.44},{"text":"你先听我解释一下我当时说的话","paragraph":425,"style":"plain","start":1012.42,"end":1015.08},{"text":"是什么意思我当时呢","paragraph":427,"style":"plain","start":1015.08,"end":1016.8},{"text":"一共说了三句话第一句","paragraph":429,"style":"plain","start":1016.8,"end":1018.96},{"text":"大部分男生是没脑子的这句话没毛病","paragraph":431,"style":"plain","start":1019.32,"end":1022.26},{"text":"第二句呢只要女生轻听挥动","paragraph":433,"style":"plain","start":1022.94,"end":1025.32},{"text":"露出大腿的裙板他们就会精重上脑","paragraph":435,"style":"plain","start":1025.32,"end":1028.12},{"text":"这句话是性使人知本性","paragraph":437,"style":"plain","start":1028.48,"end":1030.5},{"text":"使人知常情第三句呢","paragraph":439,"style":"plain","start":1030.5,"end":1033.24},{"text":"打着寻找爱情的借口说着交换灵魂的理由","paragraph":441,"style":"plain","start":1033.24,"end":1036.9},{"text":"产着青春少女的肉体这句话是扎","paragraph":443,"style":"plain","start":1036.9,"end":1040.02},{"text":"如果克制不住第二句的性那就变成了第三句的扎","paragraph":445,"style":"plain","start":1040.7,"end":1043.84},{"text":"所以我说克制才是两性之间交流的基本前提","paragraph":447,"style":"plain","start":1044.36,"end":1047.66},{"text":"不是每个男生只缠身子也不是每个女生只谈爱情","paragraph":449,"style":"plain","start":1048.24,"end":1052.12},{"text":"主要还是得看人我这段夸夸气谈过后","paragraph":451,"style":"plain","start":1052.78,"end":1056.62},{"text":"她又有一些崇拜的眼神看我你怎么这么懂啊","paragraph":453,"style":"plain","start":1056.62,"end":1059.96},{"text":"你有经验啊我捧不住的笑了","paragraph":455,"style":"plain","start":1059.96,"end":1063.14},{"text":"没没没没我瞎说的瞎说的","paragraph":457,"style":"plain","start":1063.14,"end":1066.5},{"text":"我连恋爱都没谈过你千万别因为遇到一个渣男而难过","paragraph":459,"style":"plain","start":1066.5,"end":1070.66},{"text":"那就要怎么说了这样人生何处不相逢","paragraph":461,"style":"plain","start":1071.2,"end":1074.04},{"text":"算了算了你还是别和渣男相逢","paragraph":463,"style":"plain","start":1074.6,"end":1076.9},{"text":"这世上好男人多的是，你以后一定会跟一个好男人相逢的。","paragraph":465,"style":"plain","start":1077.38,"end":1081.1},{"text":"这天晚上并不是一场红门夜，反而小百合对我表达了感谢，说如果没有我高三的帮助，","paragraph":466,"style":"plain","start":1081.88,"end":1089.58},{"text":"他绝对靠不来这组学校。","paragraph":466,"style":"plain","start":1090.02,"end":1091.44},{"text":"我也终于把当年那生没有说出口的对不起说了出来。","paragraph":467,"style":"plain","start":1092.32,"end":1096.66},{"text":"是由老朱说小百合是来对我示好他对我意思","paragraph":468,"style":"plain","start":1097.4,"end":1101.18},{"text":"但我不以为然我觉得我们俩只是冤家","paragraph":470,"style":"plain","start":1101.88,"end":1105.14},{"text":"没有在一起的缘分尽管在大学的后半程中","paragraph":472,"style":"plain","start":1105.62,"end":1109.42},{"text":"我们有过一段走得很近的时光经常一起约吃饭","paragraph":474,"style":"plain","start":1109.42,"end":1113.74},{"text":"看电影 跑步做一些情侣会做的事情","paragraph":476,"style":"plain","start":1113.74,"end":1117.54},{"text":"双方都有一些好感产生吧但当这段感情","paragraph":478,"style":"plain","start":1118.26,"end":1122.48},{"text":"逐渐陷入爱情深渊的时候我们要毕业了","paragraph":480,"style":"plain","start":1122.48,"end":1126.12},{"text":"我有一个军旅梦毕业后要去当兵","paragraph":482,"style":"plain","start":1127.14,"end":1129.9},{"text":"他家里需要用钱所以毕业就得去工作","paragraph":484,"style":"plain","start":1130.66,"end":1134.58},{"text":"我们都是喜欢按照自己人生规划来走路的人他毕业照的时候","paragraph":486,"style":"plain","start":1135.38,"end":1140.08},{"text":"他硬拉着我留下了一张合影后来我应征入伍去当了兵","paragraph":488,"style":"plain","start":1140.08,"end":1145.52},{"text":"他也离开了南京这段没有说出口的感情","paragraph":490,"style":"plain","start":1146.08,"end":1149.58},{"text":"也就在沉默当中逐渐消失了","paragraph":492,"style":"plain","start":1149.58,"end":1152.16},{"text":"我在部队的两年，我俩一次都没有见，只是在休假的时候用手机聊过几次天，","paragraph":493,"style":"plain","start":1152.98,"end":1158.82},{"text":"听说他在找工作不太顺利，想找一份离家近，有双休，待遇又不低的工作，但确实很难，","paragraph":493,"style":"plain","start":1159.62,"end":1167.82},{"text":"基本没有。","paragraph":493,"style":"plain","start":1168.44,"end":1169.0},{"text":"两年后我退伍，24岁。","paragraph":494,"style":"plain","start":1169.96,"end":1172.2},{"text":"我在南京一家还不错的公司实习，","paragraph":495,"style":"plain","start":1173.0,"end":1174.88},{"text":"平常跟原花除了偶尔的节日祝福以外，已经很少联系了，成了彼此联系人类的尸体。","paragraph":496,"style":"plain","start":1175.56,"end":1182.08},{"text":"又过了两年，我26岁。","paragraph":498,"style":"plain","start":1182.98,"end":1184.88},{"text":"很多同学到了我这个年纪，该相亲的相亲，该结婚的结婚。","paragraph":499,"style":"plain","start":1186.44,"end":1190.66},{"text":"该生小孩的生小孩，我倒也不着急，用事业都还没成，怎么成家的谢口，","paragraph":500,"style":"plain","start":1191.36,"end":1197.26},{"text":"堂侧了我爸爸妈妈很多年当然也有一部分的原因是","paragraph":502,"style":"plain","start":1197.26,"end":1201.9},{"text":"可能远分还没到吧我始终没有遇见那个","paragraph":504,"style":"plain","start":1201.9,"end":1205.48},{"text":"让我的心未知颤抖的女孩在我26岁即将结束的最后一个月里","paragraph":506,"style":"plain","start":1205.92,"end":1211.46},{"text":"我有点获得了一个回老家出差了项目的机会去当地公司对接项目的时候","paragraph":508,"style":"plain","start":1211.46,"end":1217.44},{"text":"遇见了一个熟悉的人我靠 圆滑","paragraph":510,"style":"plain","start":1217.86,"end":1221.34},{"text":"你怎么又在这十个四年再见到我","paragraph":512,"style":"plain","start":1221.88,"end":1225.12},{"text":"太傻了我在这工作啊等客户呢","paragraph":514,"style":"plain","start":1225.12,"end":1229.44},{"text":"你怎么在这啊我的大脑疯狂运转","paragraph":516,"style":"plain","start":1229.44,"end":1232.82},{"text":"突然想明白了这一切大概也许","paragraph":518,"style":"plain","start":1233.34,"end":1237.18},{"text":"可能好像","paragraph":520,"style":"plain","start":1237.18,"end":1238.8},{"text":"没必我就是你要等的客户吧","paragraph":522,"style":"plain","start":1238.8,"end":1241.74},{"text":"我俩愣在原地没有说话反映过来之后","paragraph":524,"style":"plain","start":1242.7,"end":1245.94},{"text":"才冲着对方不好意思的傻笑这可真是人生和初步相逢啊","paragraph":526,"style":"plain","start":1245.94,"end":1250.34},{"text":"后来那个项目我们完成的特别好","paragraph":528,"style":"plain","start":1251.22,"end":1253.64},{"text":"等下公司的老板都特别满意亲公宴上也喝了很多酒","paragraph":530,"style":"plain","start":1253.98,"end":1258.38},{"text":"亲公宴结束后我老板喝多了揉着我的肩膀说","paragraph":532,"style":"plain","start":1259.04,"end":1262.88},{"text":"对面公司那个小元你以前就认识吧","paragraph":534,"style":"plain","start":1263.5,"end":1266.24},{"text":"呦 这当老板的眼光就是这么独烂吗我有些不好意思的说","paragraph":536,"style":"plain","start":1267.08,"end":1271.94},{"text":"高中同学 高中同学老板带着一脸最情绪的自信","paragraph":538,"style":"plain","start":1272.28,"end":1276.58},{"text":"接着说 装吧你嫂子挺会装","paragraph":540,"style":"plain","start":1276.58,"end":1279.82},{"text":"什么高中同学我看是你的初恋吧","paragraph":542,"style":"plain","start":1280.46,"end":1283.1},{"text":"你晓得对人家还有意思看来还是忘不了啊","paragraph":544,"style":"plain","start":1283.92,"end":1287.76},{"text":"老板都这么说了我就只能低声复合","paragraph":546,"style":"plain","start":1288.34,"end":1291.02},{"text":"我说是是是谁知道他又说","paragraph":548,"style":"plain","start":1291.02,"end":1294.32},{"text":"你放心吧这件事我帮你去跟他们的老板提一嘴","paragraph":550,"style":"plain","start":1294.32,"end":1298.38},{"text":"也让他给你们俩创造一点机会记住啊","paragraph":552,"style":"plain","start":1298.82,"end":1302.24},{"text":"缘分这件事就跟项目的利润一样只认为可控的","paragraph":554,"style":"plain","start":1302.24,"end":1306.18},{"text":"后来也不知道是不是他真的帮了忙在我回去工作之前","paragraph":556,"style":"plain","start":1307.12,"end":1311.12},{"text":"原花竟然主动约我出来见一面她在见我的那天","paragraph":558,"style":"plain","start":1311.54,"end":1316.6},{"text":"穿着一身鞋红色的长裙白漆的皮肤","paragraph":560,"style":"plain","start":1316.96,"end":1320.58},{"text":"深邃的眼睛美的不可放物","paragraph":562,"style":"plain","start":1320.98,"end":1323.96},{"text":"这哪是当年暴躁的霸王花纯净的小百合呀","paragraph":564,"style":"plain","start":1323.96,"end":1327.52},{"text":"这是一朵鲜艳的红玫瑰她轻轻的挥动","paragraph":566,"style":"plain","start":1328.12,"end":1332.04},{"text":"那没有露出大腿的裙摆我的心就一直颤抖","paragraph":568,"style":"plain","start":1332.04,"end":1335.7},{"text":"就相打着寻找爱情的借口跟她交换一下灵魂","paragraph":570,"style":"plain","start":1336.22,"end":1339.34},{"text":"但是我还是客制住了她问我","paragraph":572,"style":"plain","start":1340.28,"end":1343.2},{"text":"好看吗我浪了半天在回国省","paragraph":574,"style":"plain","start":1343.2,"end":1346.46},{"text":"疯狂点头哦 好看 好看 好看","paragraph":576,"style":"plain","start":1346.46,"end":1350.62},{"text":"哦 对了我准备了一份礼物送给你","paragraph":578,"style":"plain","start":1350.98,"end":1353.46},{"text":"她非常惊讶是吗","paragraph":580,"style":"plain","start":1354.26,"end":1356.0},{"text":"我也给你准备了一份礼物我们送给对方的礼物特别默契","paragraph":582,"style":"plain","start":1356.0,"end":1360.56},{"text":"都是照片我送给她的是高尔我们打架时拍下的合照","paragraph":584,"style":"plain","start":1360.56,"end":1365.26},{"text":"她送我的是大四毕业我们即将分离的合照","paragraph":586,"style":"plain","start":1365.94,"end":1369.62},{"text":"我们不约而同心疲怒明多一笑","paragraph":588,"style":"plain","start":1370.34,"end":1372.84},{"text":"他接着问我你相信缘分吗？","paragraph":590,"style":"plain","start":1373.58,"end":1375.98},{"text":"我忧逆地回答原本不相信","paragraph":592,"style":"plain","start":1376.72,"end":1379.08},{"text":"但遇见你之后我就信了","paragraph":594,"style":"plain","start":1379.52,"end":1381.72},{"text":"他一脸闲气觉得我忧逆","paragraph":596,"style":"plain","start":1382.5,"end":1384.84},{"text":"脸上又展露出几分藏不住的气息","paragraph":598,"style":"plain","start":1385.32,"end":1388.04},{"text":"你还是跟以前一样有嘴滑舌呀","paragraph":600,"style":"plain","start":1388.6,"end":1390.74},{"text":"我回敬了一句你就跟以前不一样了","paragraph":602,"style":"plain","start":1391.48,"end":1394.5},{"text":"脾气没有以前那么暴躁了听到我说这话，她的脸上又出现了一种非常诡异的笑容。","paragraph":604,"style":"plain","start":1394.5,"end":1401.22},{"text":"当时愚蠢的我，还想不明白这笑容究竟代表了什么。","paragraph":606,"style":"plain","start":1401.86,"end":1406.06},{"text":"一直到两个月以后，我们互相表明心意，确定关系，正式开始谈恋爱。","paragraph":607,"style":"plain","start":1407.12,"end":1412.66},{"text":"谈了三年，三年后29岁，我们也决定结婚，彻底陷入爱情的深渊。","paragraph":608,"style":"plain","start":1413.34,"end":1419.74},{"text":"这个时候我才明白，原来女人最温柔，男人最有脑子的阶段，就是两个人刚开始谈恋爱的阶段。","paragraph":609,"style":"plain","start":1420.56,"end":1427.86},{"text":"电话应用结束的那个晚上，我跟她回忆我们从冤家到重逢，再到恋爱的过程，","paragraph":610,"style":"plain","start":1429.78,"end":1435.64},{"text":"最后没忍住的吐藏了一句。","paragraph":610,"style":"plain","start":1436.28,"end":1437.84},{"text":"你刚跟我谈恋爱的时候，你很温柔的呀，现在怎么又跟高中时候一样暴躁了？","paragraph":611,"style":"plain","start":1438.54,"end":1444.0},{"text":"她终于露出了那副许久未见的八王花的模样，暴躁如雷，大骂了一句，你要死吗？","paragraph":612,"style":"plain","start":1444.88,"end":1451.4},{"text":"我好久没打你，你又疲痒了是吧？","paragraph":613,"style":"plain","start":1452.04,"end":1454.18},{"text":"学习屁股让我再打一下。","paragraph":613,"style":"plain","start":1454.82,"end":1455.94},{"text":"我记还修又不好意思，见嘻嘻地说，那你要这么说的话，那我可要打着爱情的借口，","paragraph":614,"style":"plain","start":1457.08,"end":1463.52},{"text":"深刻地跟你交换一下灵魂了。","paragraph":614,"style":"plain","start":1463.98,"end":1465.64},{"text":"结婚前夕，我们还去了两个地方。","paragraph":615,"style":"plain","start":1466.36,"end":1468.72},{"text":"一，是回到了我们曾经就读过的高中。","paragraph":616,"style":"plain","start":1469.44,"end":1472.04},{"text":"给当年劝我俩打架的班主任送了喜糖，班主任一脸惊讶，不敢相信地说，","paragraph":617,"style":"plain","start":1472.82,"end":1478.58},{"text":"你俩行呀，这打架打的都打得民众局去了。","paragraph":619,"style":"plain","start":1479.22,"end":1482.66},{"text":"从学校出来后，我们还去了月老庙，祈求婚姻的祝福。","paragraph":620,"style":"plain","start":1483.9,"end":1488.06},{"text":"走之前，我们在挂满了人间愿望的学员树上，留下了一根祈福的红丝带。","paragraph":622,"style":"plain","start":1488.92,"end":1494.34},{"text":"上面只写了一句话，八个字是我们对彼此爱情的真实写照","paragraph":624,"style":"plain","start":1495.06,"end":1500.74},{"text":"也是给这世间有缘人的真挚祝福有缘之人，自悔相逢","paragraph":626,"style":"plain","start":1501.72,"end":1507.44},{"text":"故事讲完了，迷惑爸爸又是一个把星星熬成了糖浆","paragraph":628,"style":"plain","start":1509.58,"end":1515.5},{"text":"而月亮熬成了蛋糕配熬暖风熬成了奶油的夜晚","paragraph":630,"style":"plain","start":1516.18,"end":1520.82},{"text":"我已经闭好了一只眼睛等你睡着以后再闭上另一只","paragraph":632,"style":"plain","start":1521.82,"end":1527.18},{"text":"做个蛋糕的好梦吧小迷湖公主","paragraph":634,"style":"plain","start":1528.38,"end":1531.16},{"text":"晚安","paragraph":636,"style":"plain","start":1531.8,"end":1532.36}]},{"id":"emergency-contact","title":"紧急联络人","category":"story","sequence":2,"duration":718.367333,"audio":"emergency-contact.mp3","palette":["#485f52","#7b6a53"],"cues":[{"text":"我跟他分手以后，一直都想找个不太丢脸的理由去联系他。","paragraph":0,"style":"plain","start":1.8,"end":6.2},{"text":"比如他喜欢的电影上映了，我想问他还看不看。","paragraph":0,"style":"plain","start":7.12,"end":10.72},{"text":"以前常去的那家店关门了，我又觉得是不是应该告诉他一声。","paragraph":0,"style":"plain","start":11.76,"end":16.28},{"text":"可每次点开聊天框，看见最后他说的那句，东西收到了，谢谢。","paragraph":0,"style":"plain","start":17.32,"end":22.88},{"text":"我就不知道该怎么继续接下去。","paragraph":0,"style":"plain","start":23.74,"end":25.62},{"text":"后来我把他的置顶取消了，这样手机一打开就不用先看见他。","paragraph":1,"style":"plain","start":26.86,"end":32.14},{"text":"朋友问起，我也能很自然地说，分开挺久了，没怎么联系。","paragraph":1,"style":"plain","start":33.04,"end":37.86},{"text":"只有我自己知道，碰到特别开心或者特别难熬的事，我还是会先想到他，然后再找别的人讲。","paragraph":1,"style":"plain","start":38.96,"end":46.68},{"text":"他的号码一直留在紧急联系人那一栏。","paragraph":2,"style":"plain","start":47.9,"end":50.55},{"text":"我想起来过，也点进去过，但总觉得今天先不改也行，反正平时用不到，就让他在那里待着吧。","paragraph":2,"style":"plain","start":50.92,"end":59.36},{"text":"他又不会知道，更不用回答我：我们都分开了，你怎么还留着这个。","paragraph":2,"style":"plain","start":60.1,"end":65.16},{"text":"直到那天，我从白朗峰摔了下来，我们当时正在往下撤，雪很亮，风却比上升的时候大了不少。","paragraph":3,"style":"plain","start":66.64,"end":74.48},{"text":"我低着头，跟着前面的人一步一步走，后来脚下突然塌了。","paragraph":3,"style":"plain","start":75.22,"end":80.38},{"text":"我记得绳子拽住过我，也记得自己撞上了岩壁。","paragraph":3,"style":"plain","start":81.04,"end":84.7},{"text":"再之后只剩下一些零碎的声音，有人一直叫我睁眼，我想回答，嘴却动得不听使唤。","paragraph":3,"style":"plain","start":85.25,"end":93.28},{"text":"醒过来的时候，护士是拿着我的手机，对着电话那头讲英语。","paragraph":4,"style":"plain","start":94.4,"end":98.84},{"text":"我听见医院的名字，又听护士说，我已经恢复了意识，可以试着说几句话。","paragraph":4,"style":"plain","start":99.72,"end":105.54},{"text":"我这才明白，拨出去的是那个号码。","paragraph":4,"style":"plain","start":106.28,"end":109.16},{"text":"赶紧伸手去够手机，肩膀却疼得我几乎动不了。","paragraph":4,"style":"plain","start":110.02,"end":113.74},{"text":"护士以为我着急说话，反而把电话放到了我的耳边。","paragraph":4,"style":"plain","start":115.16,"end":119.7},{"text":"我还没想好该怎么解释，就听见他叫了我一声，接着问，你能听见吗？","paragraph":4,"style":"plain","start":120.56,"end":126.48},{"text":"你别吓我。","paragraph":4,"style":"plain","start":127.02,"end":127.56},{"text":"我想过那么多次重新跟他讲话，真听见他的声音，第一句却还是，没什么事，你不用过来。","paragraph":5,"style":"plain","start":128.9,"end":137.12},{"text":"他问我伤得怎么样，我说骨折了，养养就行。","paragraph":5,"style":"plain","start":138.48,"end":142.16},{"text":"电话那头安静了几秒，他说，刚才医生提到你在昏迷，还输了血。","paragraph":5,"style":"plain","start":143.32,"end":149.16},{"text":"我只好补了一句，现在已经醒了。","paragraph":5,"style":"plain","start":150.12,"end":152.66},{"text":"他没有跟我争，只是在问医院在哪个地方，让我把地址发给他。","paragraph":6,"style":"plain","start":153.8,"end":158.97},{"text":"我一听就知道他想做什么，赶紧说，香港离这里那么远，来回得折腾多久，你别过来。","paragraph":6,"style":"plain","start":159.5,"end":167.02},{"text":"他问，你是不是还没把地址发过来？","paragraph":6,"style":"plain","start":167.64,"end":170.44},{"text":"我说，我是怕你麻烦。","paragraph":6,"style":"plain","start":171.38,"end":172.8},{"text":"他又问了一遍，这次连我的名字都带上了，我就不敢继续废话了。","paragraph":6,"style":"plain","start":173.36,"end":179.08},{"text":"这趟旅行其实最早是两个人来的。","paragraph":7,"style":"plain","start":180.9,"end":183.64},{"text":"他不喜欢爬山，怕冷。","paragraph":7,"style":"plain","start":184.02,"end":186.147},{"text":"看我发过去的照片，问山下有没有暖气。","paragraph":7,"style":"plain","start":186.68,"end":189.78},{"text":"我说你能不能先欣赏一下风景。","paragraph":7,"style":"plain","start":190.66,"end":192.5},{"text":"他很认真的回答，欣赏风景和冻死是两件事。","paragraph":7,"style":"plain","start":193.32,"end":197.44},{"text":"后来我们商量，我上山，他在山下住着。","paragraph":7,"style":"plain","start":198.4,"end":201.78},{"text":"等我下来，再一起去别的地方。","paragraph":7,"style":"plain","start":202.38,"end":204.48},{"text":"他查过酒店，选中一家窗户很大的。","paragraph":7,"style":"plain","start":205.36,"end":208.32},{"text":"楼下养着只狗，还报了个法语入门班，说总不能到那儿，连杯咖啡都不会点。","paragraph":7,"style":"plain","start":208.78,"end":215.02},{"text":"但那趟旅行一直没能成行，他请完了假，我说工作走不开。","paragraph":8,"style":"plain","start":216.04,"end":221.14},{"text":"他改了日期，我又说那时候可能更忙。","paragraph":8,"style":"plain","start":221.64,"end":224.42},{"text":"最后一次，他把重新查好的机票发给我，我看完价格，回他，算了，你不用等我，跟朋友去吧。","paragraph":8,"style":"plain","start":225.3,"end":234.28},{"text":"我当时觉得自己挺体贴，至少没继续耽误他。","paragraph":8,"style":"plain","start":235.24,"end":238.68},{"text":"他很久没有回复，晚上才发了一句，那其他事情呢，我还等不等。","paragraph":9,"style":"plain","start":239.64,"end":245.28},{"text":"我知道他问的是什么，我们说过要一起住，聊过以后要留在哪座城市，他也认真地问过我，","paragraph":10,"style":"plain","start":246.58,"end":254.62},{"text":"有没有想好下一步，我每次都说，再等等吧。","paragraph":10,"style":"plain","start":255.18,"end":258.94},{"text":"看见那条消息的时候，我打了一堆关于工作和未来的解释，最后发出去的却是让他好好想想。","paragraph":11,"style":"plain","start":260.1,"end":268.46},{"text":"我把决定交给了他，也再没去找他，后来我们就分开了。","paragraph":11,"style":"plain","start":268.46,"end":274.04},{"text":"分开以后，我反而请出了这趟假。","paragraph":11,"style":"plain","start":275.12,"end":277.68},{"text":"日历上那几天被空出来的时候，我自己都愣了一下。","paragraph":11,"style":"plain","start":278.66,"end":282.04},{"text":"原来有些事情，真去安排，也没有我之前说的那么难，但他已经不在旁边了。","paragraph":11,"style":"plain","start":282.92,"end":289.1},{"text":"我最后订了另外一家酒店，房间很小，窗外对着隔壁的墙。","paragraph":12,"style":"plain","start":289.86,"end":295.12},{"text":"前台问我是不是一个人入住，我说是的，那时候还不知道，过几天，","paragraph":12,"style":"plain","start":296.06,"end":302.24},{"text":"这座城市里又会多一个为我而赶来的人。","paragraph":12,"style":"plain","start":303.0,"end":305.76},{"text":"挂掉电话以后，我把医院地址发给他，又写了一长段话，说这边有人照顾，医生也联系了家里，","paragraph":13,"style":"plain","start":307.66,"end":315.36},{"text":"让他安心上班。","paragraph":13,"style":"plain","start":315.84,"end":316.74},{"text":"千万别为我请假。","paragraph":13,"style":"plain","start":317.58,"end":318.98},{"text":"他只回了四个字，地址收到。","paragraph":13,"style":"plain","start":319.88,"end":322.16},{"text":"第二天，我忍不住问他在干什么。","paragraph":14,"style":"plain","start":323.54,"end":325.56},{"text":"隔了很久，我才收到他的消息，他说，在转机。","paragraph":14,"style":"plain","start":326.54,"end":330.72},{"text":"我盯着那三个字，先是高兴，紧接着又开始发慌。","paragraph":14,"style":"plain","start":332.06,"end":336.12},{"text":"他真要来，我该怎么见他？","paragraph":14,"style":"plain","start":336.98,"end":338.84},{"text":"人躺在这里，头没洗，衣服也没换。","paragraph":14,"style":"plain","start":339.82,"end":342.92},{"text":"见面第一句话总不能又说，不好意思，麻烦你了。","paragraph":14,"style":"plain","start":343.74,"end":347.32},{"text":"我问护士，能不能帮忙拿条毛巾？","paragraph":14,"style":"plain","start":348.26,"end":350.32},{"text":"想稍微擦一下脸，护士过来帮我弄好。","paragraph":14,"style":"plain","start":351.12,"end":353.98},{"text":"又问我是不是有什么人要来。","paragraph":14,"style":"plain","start":354.43,"end":356.44},{"text":"我说，一个朋友。","paragraph":14,"style":"plain","start":357.08,"end":358.52},{"text":"说完我自己先觉得很别扭。","paragraph":14,"style":"plain","start":359.24,"end":361.52},{"text":"他是在第三天下午到的。","paragraph":15,"style":"plain","start":362.6,"end":364.32},{"text":"我没听见开门的声音，只看见有人把一个行李箱推进病房。","paragraph":15,"style":"plain","start":364.32,"end":368.96},{"text":"他脱了外套，先出去跟护士说了几句话，再回来，把手机放到我的面前。","paragraph":15,"style":"plain","start":369.56,"end":376.14},{"text":"你发的那一大段，我在飞机上看完了。","paragraph":15,"style":"plain","start":376.74,"end":379.46},{"text":"我有点心虚，问他看完什么感觉。","paragraph":15,"style":"plain","start":380.36,"end":382.94},{"text":"他说，挺想把你手机收了，让你少操点心。","paragraph":16,"style":"plain","start":383.52,"end":387.33},{"text":"然后坐下来，从袋子里拿出一瓶水，拧开，放到我能够得着的地方。","paragraph":16,"style":"plain","start":388.1,"end":394.18},{"text":"我看着他眼下的疲惫，准备好的那些废话，一句都没敢说出来。","paragraph":16,"style":"plain","start":395.3,"end":400.2},{"text":"他后来告诉我，第一通电话响的时候，他差点没接。","paragraph":17,"style":"plain","start":401.2,"end":405.16},{"text":"陌生的国际号码，接起来又是法语，他以为是诈骗，已经准备挂了。","paragraph":17,"style":"plain","start":405.86,"end":411.86},{"text":"直到对方换成英语，念出我的名字，他才从床上坐起来。","paragraph":17,"style":"plain","start":412.46,"end":417.08},{"text":"我问他，那时候是不是很害怕？","paragraph":17,"style":"plain","start":417.94,"end":420.02},{"text":"他低头在找充电线，边找边说，你前面讲了那一堆，我就只听清楚你出了事。","paragraph":17,"style":"plain","start":421.04,"end":427.78},{"text":"我还想追问他当时到底怎么想的。","paragraph":18,"style":"plain","start":428.78,"end":430.96},{"text":"他就把手机塞给我，让我先跟家里通个视频，说父母也等了一晚上，我照着做。","paragraph":18,"style":"plain","start":431.68,"end":437.84},{"text":"他坐在旁边帮我把摄像头抬高，又把医生交代的情况跟我妈说了一遍。","paragraph":19,"style":"plain","start":438.84,"end":444.66},{"text":"我妈问他什么时候到的，吃没吃东西。","paragraph":19,"style":"plain","start":445.16,"end":447.66},{"text":"他才想起来，自己从落地到现在只喝过一杯咖啡。","paragraph":19,"style":"plain","start":447.973,"end":452.32},{"text":"我让他先去吃点东西，他把手机往我的方向推了推。","paragraph":19,"style":"plain","start":453.16,"end":457.38},{"text":"那你先陪阿姨说话吧。","paragraph":19,"style":"plain","start":457.88,"end":459.54},{"text":"到了晚上，他帮我把医生说的注意事项记了下来，我看他还在手机上回工作消息，","paragraph":20,"style":"plain","start":460.7,"end":467.62},{"text":"最后说了一次，其实你不用过来的。","paragraph":20,"style":"plain","start":468.02,"end":471.62},{"text":"他这次没像电话里那样催我，反而把手机扣在了桌上，问道：你是真不想让我来，","paragraph":21,"style":"plain","start":472.54,"end":479.28},{"text":"还是觉得我不会来？","paragraph":21,"style":"plain","start":479.84,"end":481.24},{"text":"我说都不是。","paragraph":21,"style":"plain","start":482.16,"end":483.08},{"text":"他等在旁边，我强撑了一会儿，还是承认了。","paragraph":21,"style":"plain","start":483.68,"end":487.64},{"text":"我怕你说我们已经分开了，你找错人了。","paragraph":21,"style":"plain","start":488.38,"end":491.86},{"text":"他点了点头，像是终于听明白了。","paragraph":21,"style":"plain","start":492.35,"end":495.16},{"text":"所以你就先替我说不用来了。","paragraph":22,"style":"plain","start":496.04,"end":498.16},{"text":"我没有回答。","paragraph":22,"style":"plain","start":499.22,"end":500.16},{"text":"他坐在那里看着我，过了一会才说，接到电话的时候，我没空想我们现在算什么。","paragraph":22,"style":"plain","start":500.94,"end":507.64},{"text":"我想知道你人怎么样，想过来看看你，所以就来了。","paragraph":22,"style":"plain","start":508.26,"end":512.04},{"text":"我说那现在呢？","paragraph":22,"style":"plain","start":513.04,"end":514.12},{"text":"他说现在什么？","paragraph":22,"style":"plain","start":514.98,"end":515.66},{"text":"我不太敢看他，盯着被子说，现在看完了。","paragraph":22,"style":"plain","start":516.62,"end":520.22},{"text":"他低头笑了一下，可笑完又很认真。","paragraph":22,"style":"plain","start":521.28,"end":523.94},{"text":"你得让我想想，别因为我来了，就觉得以前那些事不用再说了。","paragraph":23,"style":"plain","start":524.76,"end":529.9},{"text":"我赶紧说，我知道。","paragraph":23,"style":"plain","start":530.58,"end":531.84},{"text":"他看了我一眼，你最好真知道。","paragraph":23,"style":"plain","start":532.47,"end":536.13},{"text":"他只能留两天，假请得很急，后面的工作还得回去处理。","paragraph":23,"style":"plain","start":536.615,"end":541.66},{"text":"临走的那天，他把我能用到的东西都放在我的床边，又跟护士确认了一遍复查的时间。","paragraph":23,"style":"plain","start":542.48,"end":549.16},{"text":"我看着他拉上行李箱，很想叫他再待一点。","paragraph":24,"style":"plain","start":550.32,"end":553.44},{"text":"可他已经为了这趟路改了那么多的安排，我也把话咽了回去。","paragraph":24,"style":"plain","start":554.22,"end":558.8},{"text":"他走到门口，忽然回头问，还有什么要说的。","paragraph":24,"style":"plain","start":559.96,"end":563.32},{"text":"我说路上小心，他看了我几秒，叹了声气，推着箱子走了。","paragraph":24,"style":"plain","start":564.6,"end":570.62},{"text":"病房安静下来以后，我又拿起手机，聊天框全是医院地址，是航班时间，","paragraph":25,"style":"plain","start":571.82,"end":577.86},{"text":"还有我发出的那些不用。","paragraph":25,"style":"plain","start":578.52,"end":580.16},{"text":"我向上翻，翻到了半年前，那张他查好的机票截图。","paragraph":25,"style":"plain","start":580.96,"end":585.2},{"text":"当时我觉得，如果把话说得客气一点，他就不会为难。","paragraph":25,"style":"plain","start":586.02,"end":590.4},{"text":"我也不用听见一个明确的拒绝。","paragraph":25,"style":"plain","start":591.06,"end":592.78},{"text":"可从那以后，我们真的没有再一起出过门。","paragraph":25,"style":"plain","start":593.6,"end":596.42},{"text":"我不知道他这时候到哪了，也不知道这通电话会不会打得不太合适。","paragraph":26,"style":"plain","start":597.92,"end":602.76},{"text":"手指在拨号键上停了一会儿，我还是按了。","paragraph":26,"style":"plain","start":603.5,"end":606.58},{"text":"他接得很快，问我怎么了，是不是哪里不舒服。","paragraph":26,"style":"plain","start":607.4,"end":610.78},{"text":"我说没有。","paragraph":26,"style":"plain","start":611.44,"end":611.94},{"text":"他的声音一下紧张起来，那怎么了，你慢慢说。","paragraph":26,"style":"plain","start":613.32,"end":616.52},{"text":"我听见他那边有车流声，忽然觉得自己这回必须要好好讲，不能再让他猜。","paragraph":26,"style":"plain","start":617.58,"end":624.08},{"text":"我想让你回来，再跟我见一面。","paragraph":27,"style":"plain","start":625.28,"end":628.0},{"text":"我说等我回到香港，你愿不愿意跟我吃个饭？","paragraph":27,"style":"plain","start":629.18,"end":632.16},{"text":"以前那些没说清楚的事情，我想跟你说清楚。","paragraph":27,"style":"plain","start":633.42,"end":636.7},{"text":"他没有立刻回答，我也没赶着补那句，不方便就算了。","paragraph":27,"style":"plain","start":637.64,"end":641.68},{"text":"我拿着手机，老老实实等他的决定。","paragraph":27,"style":"plain","start":642.44,"end":645.64},{"text":"过了一会儿，他说可以，但你别又等我来安排。","paragraph":27,"style":"plain","start":646.66,"end":650.78},{"text":"我赶紧答应，说地方我找，时间等他有空。","paragraph":27,"style":"plain","start":651.8,"end":655.64},{"text":"他在那头嗯了一声，又问，说完了？","paragraph":28,"style":"plain","start":656.66,"end":659.66},{"text":"我说，还有一句。","paragraph":28,"style":"plain","start":660.4,"end":661.58},{"text":"他让我继续讲，我就看着窗外，终于没拿别的话绕过去。","paragraph":28,"style":"plain","start":662.43,"end":667.9},{"text":"刚才你走的时候，我其实很舍不得。","paragraph":28,"style":"plain","start":668.7,"end":671.16},{"text":"刚才你走的时候，我其实很舍不得。","paragraph":28,"style":"plain","start":672.38,"end":674.92},{"text":"电话那头传了一声很轻的叹息。","paragraph":28,"style":"plain","start":675.76,"end":678.09},{"text":"他说，我知道啊，我在门口可是等了你半天。","paragraph":28,"style":"plain","start":678.385,"end":683.52},{"text":"故事讲完了，迷湖宝宝。","paragraph":29,"style":"plain","start":688.48,"end":690.36},{"text":"这个故事其实是改编自歌曲《紧急联络人》，但其实改得一般，下次再换个有趣的题材吧。","paragraph":29,"style":"plain","start":691.3,"end":700.08},{"text":"生理期记得要吃饱饱，睡饱饱。","paragraph":29,"style":"plain","start":701.22,"end":704.027},{"text":"晚安，迷湖宝宝，祝你今天的梦里能吃到小蛋糕。","paragraph":29,"style":"plain","start":704.24,"end":709.54}]},{"id":"friend-experience","title":"我有一个朋友，和这个经历差不多","category":"story","sequence":3,"duration":1385.351837,"audio":"friend-experience.mp3","palette":["#485f52","#726451"],"cues":[{"text":"我一直觉得影像是个很神奇的东西。","paragraph":0,"style":"plain","start":1.34,"end":4.84},{"text":"时间是不可选择，不能倒退的。","paragraph":0,"style":"plain","start":5.8,"end":8.22},{"text":"但照片和视频就可以让时间停留在某个瞬间。","paragraph":0,"style":"plain","start":9.06,"end":12.86},{"text":"就像时间魔法一样，能够让人感受到当下的情绪。","paragraph":0,"style":"plain","start":13.76,"end":17.94},{"text":"所以我的理想很早就落地了。","paragraph":0,"style":"plain","start":18.92,"end":21.22},{"text":"同学们问起以后的梦想，说的都是博士、宇航员这些、有点遥远的东西。","paragraph":1,"style":"plain","start":22.06,"end":27.72},{"text":"而我就想当个摄影师但现实比较骨感上学的时候我对自己的人生没有多少话语权爸妈基本上替我","paragraph":1,"style":"plain","start":28.72,"end":39.78},{"text":"完成了大部分的选择研究生毕业的我即便成了人们口中的土木老哥工作以后赚钱了吗当时正好赶","paragraph":1,"style":"plain","start":39.78,"end":49.72},{"text":"上HM3刚发售看了乱七八糟各种各样的测评","paragraph":1,"style":"plain","start":49.72,"end":54.04},{"text":"说是拍照和录像的性能都比较平均我一咬牙就掏出了攒了半年的工资下单了","paragraph":2,"style":"plain","start":54.74,"end":61.36},{"text":"相机到手的时候特别兴奋摸来摸去的感觉能玩一辈子甚至觉得自己已经不需要女朋友了那阵子就","paragraph":3,"style":"plain","start":63.9,"end":73.92},{"text":"到处拍拍拍上班也带着然后让领导知道了也有给我安排了一堆现场记录的活从来以后我就再也不","paragraph":3,"style":"plain","start":73.92,"end":83.78},{"text":"敢显摆了刚开始我拍了很多的风景和人文啥的白话来讲就是没事出去扫街嘛用来熟悉基础的光圈","paragraph":3,"style":"plain","start":83.78,"end":94.36},{"text":"和快门什么的但拍来拍去的也没啥目的性","paragraph":3,"style":"plain","start":94.36,"end":98.74},{"text":"后来加了一些本地的摄影群一些老哥的工作多忙不过来的时候就会让我去兼职拍一拍活动和婚礼","paragraph":4,"style":"plain","start":99.24,"end":107.92},{"text":"啥的顺便赚一点零散的外快事情就发生在一次婚礼的跟拍上一般来讲新人两边都会安排三个人分","paragraph":4,"style":"plain","start":108.01,"end":119.3},{"text":"别是摄影 摄像 以及化妆那天我在新娘这边负责接亲前的记录我早上5点就出发了但到的时候","paragraph":4,"style":"plain","start":119.3,"end":128.94},{"text":"发现另外两个人比我还早摄像是个快200斤的老哥","paragraph":4,"style":"plain","start":128.94,"end":133.94},{"text":"扛着三脚架 稳如老狗化妆的那个女生也已经开始给新娘在忙活了新娘人很不错知道时间比较早","paragraph":5,"style":"plain","start":134.54,"end":143.94},{"text":"还给我们准备了吃的但毕竟是人家的大喜日子我也没吃就揣了两个鸡蛋就开始工作了过程挺顺利","paragraph":5,"style":"plain","start":143.94,"end":153.24},{"text":"的也不是很忙就拍一拍新娘的装造和现场气氛啥的直到新郎接亲的时候才忙起来然后经过一系列","paragraph":5,"style":"plain","start":153.24,"end":162.76},{"text":"的塞红包啊抢媳妇的流程也算完成了前半程的接亲仪式","paragraph":5,"style":"plain","start":162.76,"end":167.64},{"text":"去往婚礼现场我们三个坐的是一辆车摄像体型比较大坐在了前面那个化妆就会有坐在后排然后忙","paragraph":6,"style":"plain","start":170.24,"end":180.78},{"text":"活一早上我也饿了吃煮鸡蛋的时候有化妆就在旁边一个劲地咽口水我就把另一个分给了她她也没","paragraph":6,"style":"plain","start":180.78,"end":190.34},{"text":"客气接过来的时候有点不好意思的说早上一直在给新娘忙活没来得及吃点什么这时候我才有精力","paragraph":6,"style":"plain","start":190.34,"end":199.413},{"text":"打量她一番她穿了一身黑 脸很小","paragraph":6,"style":"plain","start":199.5,"end":203.16},{"text":"留着一头柔亮的短发 很漂亮虽然婚礼上最好看的人应该是新娘但从审美的角度来说我觉得她比","paragraph":7,"style":"plain","start":203.98,"end":212.74},{"text":"新娘和贵宾团的那些女生都要漂亮到了婚礼现场我跟摄像接着拍场地和空境化妆就跟着新娘最后","paragraph":7,"style":"plain","start":212.74,"end":222.5},{"text":"台补妆换衣服啥的接着就是新婚仪式嘛主持人开场新人上台完成誓言和敬茶改口期间我就满场来","paragraph":7,"style":"plain","start":222.5,"end":233.38},{"text":"回跑尽量记录下人家最重要的日子直到新人轮番敬酒","paragraph":7,"style":"plain","start":233.5,"end":239.04},{"text":"宾客都吃得差不多了我跟他们说了句新婚快乐也算是完成了今天的工作","paragraph":8,"style":"plain","start":239.56,"end":245.26},{"text":"那个女化妆给新娘换完敬酒服后就收工了但一直没走 还在我收拾东西的时候叫住了我悄咪咪的","paragraph":9,"style":"plain","start":247.66,"end":257.12},{"text":"问我饿不饿 忙活了这么一大圈就吃了个煮鸡蛋说实话我都饿晕了 她就笑着把我带到角落里一","paragraph":9,"style":"plain","start":257.12,"end":266.99},{"text":"个已经散场的餐桌上 说吃完了再走 不然也浪费了我看还剩了不少饭菜心想自己也在见证的新","paragraph":9,"style":"plain","start":266.99,"end":275.82},{"text":"人的爱情那吃两口他们的席也不过分吧","paragraph":9,"style":"plain","start":275.82,"end":279.48},{"text":"于是就跟化妆师悄悄地吃了起来吃饭的时候聊了两句她也是来兼职的那个摄像老哥是婚庆公司的","paragraph":10,"style":"plain","start":279.96,"end":289.42},{"text":"已经跟着同事走了我们这也算是互相请客了吧话赶话的就加上了微信说是以后她缺摄影我缺化妆","paragraph":10,"style":"plain","start":289.9,"end":299.46},{"text":"的时候可以互补一下然后吃着饭菜呢新娘突然过来了我心想糟了就有种偷吃被抓包的感觉但人家","paragraph":10,"style":"plain","start":299.46,"end":310.26},{"text":"非但没怪我们还道歉说太忙没顾得上给我们准备吃的","paragraph":10,"style":"plain","start":310.26,"end":314.48},{"text":"最后塞了一百块的红包我们两个就一个劲地说谢谢祝愿人家幸福美满茶的回去的地铁我们俩比较","paragraph":11,"style":"plain","start":315.06,"end":324.34},{"text":"顺路就有一搭没一搭的闲聊她比我小三岁，","paragraph":11,"style":"plain","start":324.34,"end":328.8},{"text":"不是本地人，职业就是干化妆的，所以就叫她小妆娘嘛。","paragraph":11,"style":"plain","start":329.02,"end":334.96},{"text":"那天真的是给我累坏了，到家以后，蒙头就睡，一睁眼已经是晚上六点多。","paragraph":12,"style":"plain","start":336.2,"end":342.7},{"text":"望着窗外泛着红云的天空，整个人都神清气爽的。","paragraph":13,"style":"plain","start":344.92,"end":349.34},{"text":"手机那边出乎意料的，竟然收到了小妆娘的消息。","paragraph":13,"style":"plain","start":350.34,"end":353.72},{"text":"说她后天有个工作缺摄影 问我来不来我以为先前就是客气一下没想到人家还真想着我但细问了","paragraph":13,"style":"plain","start":354.56,"end":364.08},{"text":"才知道那是个什么儿童比赛摄影给的不多所以很多老哥都不爱去那两天是五一假期嘛我没啥事也","paragraph":13,"style":"plain","start":364.08,"end":373.6},{"text":"不挑权当锻炼身体了于是就接了下来","paragraph":13,"style":"plain","start":373.6,"end":377.38},{"text":"当天她在演出附近的地铁站等着我这时候我才发现婚礼那天她全程都是素颜现在化了妆以后更漂","paragraph":14,"style":"plain","start":378.22,"end":387.83},{"text":"亮了我就开玩笑地说了句你这条件不应该在幕后啊她明白得很快笑着笑着也没接茬就从包里掏出","paragraph":14,"style":"plain","start":387.83,"end":398.42},{"text":"两个煮鸡蛋问我吃饭没我说你怎么又是煮鸡蛋她笑着说这两天有点上瘾我吃过早饭了但还是顺手","paragraph":14,"style":"plain","start":398.42,"end":408.0},{"text":"揣到了兜里接着我俩就一起到了演出的场馆","paragraph":14,"style":"plain","start":408.19,"end":412.34},{"text":"大致了解一下工作内容就是几组小孩轮流的戏曲演出我记录一下台上台下的反应就行小妆娘的事","paragraph":15,"style":"plain","start":412.78,"end":421.72},{"text":"就比较多了虽然还有别的化妆师但人手依旧不足后台一堆小孩哥小孩姐等着化妆呢我对戏曲一窍","paragraph":15,"style":"plain","start":421.72,"end":431.46},{"text":"不通就看那一个一个小人浓妆艳抹的上台像模像样的唱着戏腔跳着舞步抽空的时候，","paragraph":15,"style":"plain","start":431.5,"end":439.68},{"text":"我就后台看了一眼小妆娘真聚精会神的化着妆","paragraph":15,"style":"plain","start":440.16,"end":443.64},{"text":"别在耳后的短发散落在脸上在灯光下勾勒出一层金边显得格外好看我没忍住，","paragraph":16,"style":"plain","start":444.78,"end":453.14},{"text":"就借着记录后台的名义偷偷拍了两张她的照片演出的时间不长，","paragraph":16,"style":"plain","start":453.46,"end":460.28},{"text":"一共也就两三个小时中午12点多也就结束了她工作完在外面看着表演我在想偷拍就被发现了最","paragraph":16,"style":"plain","start":460.62,"end":470.84},{"text":"后只抓到了几张很有偷感的身影结束以后我请她吃炉端火锅毕竟是人家介绍的兼职我多少也赚了","paragraph":16,"style":"plain","start":470.84,"end":480.54},{"text":"几百块","paragraph":16,"style":"plain","start":480.54,"end":480.98},{"text":"吃饭的时候她知道我是干土木的一脸疑惑的问我你这单薄的身材下得了工地吗工作快一年了类似","paragraph":17,"style":"plain","start":481.86,"end":492.2},{"text":"的问题总能遇到只能说人心中的成见是座大山我也没解释，","paragraph":17,"style":"plain","start":492.2,"end":497.66},{"text":"就搞笑地回了句我可不是小弟弟的女王，有的是力气和手段她听了就跟那捂嘴笑，","paragraph":17,"style":"plain","start":497.86,"end":505.72},{"text":"反正聊得还挺开心的也算是消除了一些陌生感吧临走的时候，她把帐A了，我说不用","paragraph":17,"style":"plain","start":506.28,"end":513.76},{"text":"她就有点不好意思地说自己已经吃过我的回扣了我无奈地笑了笑，","paragraph":18,"style":"plain","start":514.34,"end":519.7},{"text":"也没再坚持晚上整理工作图片的时候，","paragraph":18,"style":"plain","start":519.94,"end":523.36},{"text":"又收到了小妆娘的消息问我要今天偷拍的几张照片问我有没有留下什么黑照我就挑着她发了过去","paragraph":18,"style":"plain","start":523.88,"end":532.88},{"text":"意外的是她觉得我拍的还不错夸我很有天赋我看着她那张专心工作的照片吃着白天她送我的煮鸡","paragraph":18,"style":"plain","start":533.48,"end":542.6},{"text":"蛋回了一句可惜她问可惜什么","paragraph":18,"style":"plain","start":542.6,"end":546.78},{"text":"我说可惜再也没有这么好看的模特了她那边正在输入了一会儿说道那拍你女朋友吗我非常正经 ","paragraph":19,"style":"plain","start":548.2,"end":557.5},{"text":"非常严肃地回答我有女朋友的话是不会跟女生单独出去吃饭的她那边发了一串哈哈哈哈说你这个","paragraph":19,"style":"plain","start":557.74,"end":567.22},{"text":"人怎么这么老实然后又回了句也不一定没有机会了我说真的她发了一个得意的表情包回答道但本","paragraph":19,"style":"plain","start":567.22,"end":578.24},{"text":"小姐的出场费可是很贵的","paragraph":19,"style":"plain","start":578.24,"end":580.26},{"text":"我也回了一个豁达的表情说小事回购和煮鸡蛋都给你吃总之我们也算达成了某种口头约定五一结","paragraph":20,"style":"plain","start":582.54,"end":592.26},{"text":"束后又开始上班了嘛所以也没去定具体的拍摄时间反正联系没有断每天都有一搭没一搭的闲聊着","paragraph":20,"style":"plain","start":592.26,"end":601.3},{"text":"那阵子总有一些莫名的念头在心里闪来闪去我就拍拍自己的脸告诉自己不要乱想这只是为了精进","paragraph":20,"style":"plain","start":602.28,"end":611.24},{"text":"拍照技术而且人家那么好看不知道有多少人想追呢","paragraph":20,"style":"plain","start":611.24,"end":615.32},{"text":"怎么也轮不到自己吧但在闲聊中还是忍不住想要更多的了解它小妆娘在一家传媒公司上班就是那","paragraph":21,"style":"plain","start":615.84,"end":625.4},{"text":"种拍短剧短视频的地方她就负责给演员化妆啥的我还看到两个他们的视频只能说导演不会选角女","paragraph":21,"style":"plain","start":625.4,"end":634.36},{"text":"主完全没有她好看我也好奇的问过她她为什么没有站在台前她说自己有镜头恐惧症也不喜欢在互","paragraph":21,"style":"plain","start":634.36,"end":643.087},{"text":"联网上抛头露面以至于我一直没敢约她出来","paragraph":21,"style":"plain","start":643.153,"end":646.88},{"text":"直到过了半个多月吧小妆娘那边先找到了我说她最近新学了几个妆面希望拍一些定妆照当客片用","paragraph":22,"style":"plain","start":649.08,"end":657.62},{"text":"我当然满口答应了5月下旬的天气已经算比较热了花草树木的春芽已经退去枝繁叶茂的，","paragraph":22,"style":"plain","start":658.2,"end":667.84},{"text":"长满了夏天的气息那天她穿着短裙和小白袜上身是一件长袖搭配她的短发看起来甜酷甜酷的之前","paragraph":22,"style":"plain","start":668.0,"end":680.4},{"text":"没怎么拍过人像嘛所以我事先做了好多功课","paragraph":22,"style":"plain","start":680.4,"end":684.0},{"text":"包括构图，怎么打光，","paragraph":23,"style":"plain","start":684.46,"end":686.28},{"text":"怎么引导之类的但等上手之后才明白为什么说人像三要素的真理是美女这小姑娘往那一站无论怎","paragraph":23,"style":"plain","start":686.6,"end":695.89},{"text":"么拍都好看","paragraph":23,"style":"plain","start":695.89,"end":696.74},{"text":"她需求上要一些怼脸拍的视角短视频里经典的那种露脑袋长镜头的说到时候选择起来比较直观一","paragraph":24,"style":"plain","start":699.86,"end":709.02},{"text":"点两人离得很近嘛我透过镜头仿佛在跟她眼神对视她还凑过来想着能不能反向看到我一对着镜头","paragraph":24,"style":"plain","start":709.02,"end":719.52},{"text":"挤眉把她拍成了一个一米二的大头娃娃她就追着我的屁股让我给删了甚至指着公园的湖水以死相","paragraph":24,"style":"plain","start":719.753,"end":727.86},{"text":"逼但真的要删的时候她又说算了 也挺可爱的","paragraph":24,"style":"plain","start":727.86,"end":732.66},{"text":"后来我有过她的很多黑照但这张大头娃娃我一直留着其实认识的这段时间里我一直觉得小妆娘有","paragraph":25,"style":"plain","start":733.54,"end":742.86},{"text":"种超越同龄人的成熟感说不上她为什么尽管我比她大三岁但还是觉得她比我更懂人情世故然后休","paragraph":25,"style":"plain","start":742.86,"end":752.42},{"text":"息的时候 闲聊才知道她已经工作五六年了算起来高中的时候就进入了社会具体因为啥她也没说","paragraph":25,"style":"plain","start":752.42,"end":761.04},{"text":" 我也没问反正是个人还是家庭原因吧","paragraph":25,"style":"plain","start":761.04,"end":766.1},{"text":"既然已经到了这步那也没有必要再回忆过去的糟心事了傍晚的时候我俩一起吃了饭她又要A我说","paragraph":26,"style":"plain","start":767.0,"end":776.2},{"text":"这是你的出场费她才没继续坚持吃完饭我又陪她去买甜食很可惜我是个食肉动物看着她那些蛋糕","paragraph":26,"style":"plain","start":776.2,"end":786.46},{"text":"泡芙真是吃不了一点她撇了撇嘴说我没有口福有时候下次可以请我吃烤肉我凭着感觉顺嘴说了句","paragraph":26,"style":"plain","start":786.46,"end":796.32},{"text":"你不用什么都想着还我来的她愣了一下","paragraph":26,"style":"plain","start":796.76,"end":801.04},{"text":"半天在小声地嘟囔道或许是我想跟你一起吃呢这下换我愣住了不知道该怎么理解她这句有点暧昧","paragraph":27,"style":"plain","start":801.66,"end":811.4},{"text":"的话想了一下还是认真的回答说你想吃什么我都可以陪你她脸色红红的但还是抬起头在看着我说","paragraph":27,"style":"plain","start":811.4,"end":821.32},{"text":"那就吃烤肉吧我说好","paragraph":27,"style":"plain","start":822.02,"end":824.72},{"text":"之后两个人就在那尴尬地沉默气氛尴尬中又透露着暧昧我把她送上了地铁一个人在站台发呆了很","paragraph":28,"style":"plain","start":826.84,"end":836.18},{"text":"久有种月老上身的错觉那天过后明显感觉我们的关系近了不少小妆娘开始陆续地跟我分享生活和","paragraph":28,"style":"plain","start":836.18,"end":846.22},{"text":"工作中的事情看我给她发的工地照片还会叮嘱我小心点什么呢那段时间我有时候没事就约小妆娘","paragraph":28,"style":"plain","start":846.22,"end":855.14},{"text":"出来拍照人像水平也得到了长足的进步","paragraph":28,"style":"plain","start":855.14,"end":858.94},{"text":"主要是模特儿好看怎么拍都出片小妆娘经过我一段时间的说话训练好像也慢慢摆脱了镜头恐惧也","paragraph":29,"style":"plain","start":859.46,"end":869.2},{"text":"没那么抗拒在各种平台上展示自己了她原本就是在传媒公司上班嘛有着一些相关的经验脑子里存","paragraph":29,"style":"plain","start":869.2,"end":878.54},{"text":"了不少奇怪的想法我也开始学习拍照和剪辑没事的时候就帮她发了个视频意外的还吸引了一些观","paragraph":29,"style":"plain","start":878.78,"end":887.75},{"text":"众接了几个商单虽然赚的不多吧","paragraph":29,"style":"plain","start":887.75,"end":891.62},{"text":"但感觉小妆娘还是挺受鼓舞的兴高采烈的要跟我分账但人家自己的账号我也没要虽然她请我吃了","paragraph":30,"style":"plain","start":891.62,"end":900.22},{"text":"一顿烤肉她酒足饭饱了还跟我吹牛说你以后就跟姐混保证你吃香的和辣的这期间大概经历了四五","paragraph":30,"style":"plain","start":900.22,"end":910.32},{"text":"个月吧那段时间她都很有能量整个人都特别开朗仿佛对全世界都充满了欢喜而这个全世界里应该","paragraph":30,"style":"plain","start":910.32,"end":921.06},{"text":"也包括了我我变成了她的御用摄影、","paragraph":30,"style":"plain","start":921.06,"end":924.22},{"text":"剪辑以及陪玩","paragraph":30,"style":"plain","start":924.68,"end":925.94},{"text":"有的时候还要充当她视频里的角色别的女生约我拍摄她就会变着法儿的给我搞砸了但这种在乎我","paragraph":31,"style":"plain","start":926.54,"end":937.0},{"text":"其实也挺开心的甚至家里的老两口都明显感觉到了问我是不是有对象 谈朋友了我也不回答 就","paragraph":31,"style":"plain","start":937.0,"end":945.64},{"text":"笑而不语说实话 那个时候我们两个的关系已经非常近了我也觉得是时候表明态度然后有天要拍","paragraph":31,"style":"plain","start":945.64,"end":955.0},{"text":"那种情侣的剧本嘛小妆娘给我上妆的时候我就问她","paragraph":31,"style":"plain","start":955.0,"end":959.38},{"text":"真情侣来演会不会效果更好一点她捧着我的脑袋盯着我的眼睛我歪着头没说话然后很快一个俯冲","paragraph":32,"style":"plain","start":960.32,"end":970.54},{"text":"亲在我的嘴上在我还没有反应过来的时候说现在是真情侣了吧然后那天就延误了拍摄反正就算拍","paragraph":32,"style":"plain","start":970.66,"end":980.96},{"text":"了也过不了审总之我们就这样确定了关系在一起之后每天感觉都很幸福两个人牵手走在街上觉得","paragraph":32,"style":"plain","start":980.96,"end":991.36},{"text":"自己特有钱跟个富二代似的","paragraph":32,"style":"plain","start":991.36,"end":993.64},{"text":"说起来小妆娘的粉丝里确实有那种富哥我在评论区也见过她担心我会多想还直接把账号甩过来理","paragraph":33,"style":"plain","start":994.36,"end":1004.02},{"text":"由是我上传视频啥的也能省事一点我当然能从她的行为里感受到她对我都喜欢但也疑惑地问过她","paragraph":33,"style":"plain","start":1004.02,"end":1013.285},{"text":"究竟看上我什么她半天没吱声然后有点难过地说因为你像我爸我看她那个样子还以为令尊离世了","paragraph":33,"style":"plain","start":1013.49,"end":1024.0},{"text":"安慰了几句她嗤了我一声说我爸没死","paragraph":33,"style":"plain","start":1024.44,"end":1028.54},{"text":"然后结果我讲了她家里的事情","paragraph":34,"style":"plain","start":1029.6,"end":1031.44},{"text":"故事其实也没那么复杂就是她妈妈很漂亮在她刚上初中的时候跟一个有钱人跑了她爸爸呢是个老","paragraph":35,"style":"plain","start":1033.38,"end":1042.68},{"text":"师心疼女儿就没再婚后来她学习越来越差高二就退学了我听完就问她那我是个老实人吗她说不是","paragraph":35,"style":"plain","start":1042.68,"end":1054.82},{"text":"说我和她爸都有一种让她安心的感觉她妈妈分开那么久小妆娘都没有听到她爸骂过她妈我问她那","paragraph":35,"style":"plain","start":1055.52,"end":1064.6},{"text":"你记恨你妈妈吗？","paragraph":35,"style":"plain","start":1064.6,"end":1065.6},{"text":"她想了一下，摇摇头说印象中，妈妈的美甲很美所以高中辍学以后，","paragraph":36,"style":"plain","start":1067.36,"end":1074.2},{"text":"她就去美甲店做了学徒所以开始教给她化妆的，就是那个店长小妆娘说这些事情的时候，","paragraph":36,"style":"plain","start":1074.68,"end":1082.9},{"text":"情绪很平静好像在念流水账一样但我却在平静的背后，","paragraph":36,"style":"plain","start":1083.3,"end":1088.38},{"text":"看到了一个小女孩安抚着爸爸望着远去的妈妈一个人跌跌撞撞向前追逐的样子我无权评价她的父","paragraph":36,"style":"plain","start":1088.76,"end":1098.16},{"text":"母只是很心疼面前的姑娘","paragraph":36,"style":"plain","start":1098.16,"end":1100.22},{"text":"又不想气氛太沉重就抱着她说放心吧我不会跟有钱人跑的她就在我的怀里掐了掐我的后背表示了","paragraph":37,"style":"plain","start":1100.64,"end":1110.26},{"text":"她的愤怒那次谈心以后我们的感情更好了但她的问题解决了我的麻烦又浮现了出来10月份，","paragraph":37,"style":"plain","start":1110.26,"end":1120.1},{"text":"我们一起去看了漫展在我的百般请求下，一起出了石头门的男女主后来我看返图啥的，","paragraph":37,"style":"plain","start":1120.3,"end":1127.84},{"text":"像极了科学怪人在绑架美少女但也算实现了某种心愿","paragraph":37,"style":"plain","start":1128.07,"end":1133.02},{"text":"紧接着10月中旬的时候，她接了一个大单要跟足两个月的时间虽然我可以去找她，","paragraph":38,"style":"plain","start":1134.0,"end":1141.16},{"text":"但不能随时见面晚上休息的时候，","paragraph":38,"style":"plain","start":1141.54,"end":1144.68},{"text":"两个人煲电话粥我跟爸妈住在一起他们观察了一阵子就开始旁敲侧击的瞎打听问我小姑娘的条件","paragraph":38,"style":"plain","start":1145.16,"end":1154.58},{"text":"他们一定是外地人学历还不高就一副欲言又止的样子每两天就开始劝分这事我当然不能听他们的","paragraph":38,"style":"plain","start":1154.58,"end":1165.08},{"text":"一连吵了好几天","paragraph":38,"style":"plain","start":1165.08,"end":1166.36},{"text":"有次吵架的时候还忘记闭麦被小妆娘听见了她那边也不理我了当时我真是一个头两个大郁闷了好","paragraph":39,"style":"plain","start":1167.0,"end":1175.96},{"text":"几天","paragraph":39,"style":"plain","start":1175.96,"end":1176.3},{"text":"仔细想了一下我先在外面租了个房子然后晚上的时候跟爸妈心平气和地谈了一下我问他们自己是","paragraph":40,"style":"plain","start":1178.74,"end":1188.673},{"text":"不是一个听话懂事的儿子他们东拉西扯地也不回答我打断他们又重复了一遍既然我很认真他们说","paragraph":40,"style":"plain","start":1188.673,"end":1197.22},{"text":"是我说从小到大我什么都听你们的学什么东西交什么朋友读什么专业都听你们的我也愿意相信你","paragraph":40,"style":"plain","start":1197.22,"end":1207.5},{"text":"们所谓的经验之谈但这一次不行因为我喜欢那个姑娘","paragraph":40,"style":"plain","start":1207.5,"end":1212.0},{"text":"我也不想跟你们解释她是一个什么样的人甚至今天跟你们说这些跟她的关系也不是很大我只是希","paragraph":41,"style":"plain","start":1212.36,"end":1220.18},{"text":"望你们能够尊重我的选择也相信你们培养出来的孩子说完这些以后我就回房间也不指望他们根深","paragraph":41,"style":"plain","start":1220.18,"end":1229.68},{"text":"蒂固的想法能因为这几句话突然就改变所以第二天我就自己搬到新家去而且也该开始自己的新生","paragraph":41,"style":"plain","start":1229.68,"end":1239.0},{"text":"活了我很想找小妆娘说清楚","paragraph":41,"style":"plain","start":1239.0,"end":1242.1},{"text":"但她还没告诉我剧组在什么地方我只好把新家的地址发给了她还好她并没有拉黑和删除我的微信","paragraph":42,"style":"plain","start":1243.02,"end":1251.26},{"text":"第二天很晚的时候小妆娘突然打了电话然后就说了两个字开门","paragraph":42,"style":"plain","start":1252.44,"end":1258.34},{"text":"那时候已经11月份了我着急忙慌地穿好衣服，打开门，就看到她身上冒着凉气地站着呢。","paragraph":43,"style":"plain","start":1260.22,"end":1268.56},{"text":"本来板着一张脸，见到我后，就啪嗒啪嗒地掉着眼泪。","paragraph":43,"style":"plain","start":1269.24,"end":1273.44},{"text":"印象中她是一个很要强的人，那时我第一次见到她哭。","paragraph":43,"style":"plain","start":1274.46,"end":1278.86},{"text":"一边哭，还一边跟我道歉，说对不起，因为她我被爸妈赶出了家门。","paragraph":44,"style":"plain","start":1279.82,"end":1285.3},{"text":"我就给她擦着眼泪已经进了屋说不是被赶出来的是我想跟你一起生活这就是我们的小家其实她也","paragraph":44,"style":"plain","start":1286.7,"end":1297.12},{"text":"明白这事没那么快解决于是抱着我也带调侃地说以后姐会让你住上大房子的就算爸妈不要你了你","paragraph":44,"style":"plain","start":1297.12,"end":1306.1},{"text":"还有我呢我可以当你妈妈我就拍了一下她的脑袋壳说你怎么还占人家便宜呢","paragraph":44,"style":"plain","start":1306.1,"end":1313.76},{"text":"那一刻我抱着怀里的姑娘第一次感受到可以对抗整个世界的力量好像她陪在身边一切都不是问题","paragraph":45,"style":"plain","start":1314.96,"end":1323.88},{"text":"后来一直到过年的时候为表抗议我都没有回去见爸妈但春节怎么也要回去的嘛经过几个月的拖字","paragraph":45,"style":"plain","start":1325.04,"end":1333.813},{"text":"诀老两口的态度有缓和了不少我想了一下还是把小妆娘带回去了她很害怕也很忐忑但我从小听话","paragraph":45,"style":"plain","start":1333.92,"end":1345.48},{"text":"懂事，","paragraph":45,"style":"plain","start":1345.48,"end":1345.88},{"text":"也代表我很了解父母","paragraph":45,"style":"plain","start":1346.18,"end":1348.1},{"text":"老两口都是体面人，在人前不能说什么过分的话果不其然，双方见面都客客气气的，","paragraph":46,"style":"plain","start":1348.78,"end":1356.68},{"text":"事后还一个劲的夸她漂亮","paragraph":46,"style":"plain","start":1356.68,"end":1358.4},{"text":"故事到这差不多就结束了婚礼那天，","paragraph":47,"style":"plain","start":1360.22,"end":1363.56},{"text":"我特意给每桌都加了一盘煮鸡蛋还特意给摄影和化妆300块的红包看着他们离开的背影，","paragraph":47,"style":"plain","start":1364.06,"end":1371.7},{"text":"我和她相视一笑，仿佛看到了当初的我们。","paragraph":47,"style":"plain","start":1372.22,"end":1376.36},{"text":"故事讲完了，小迷湖公主，晚安，做个好梦。","paragraph":48,"style":"plain","start":1378.8,"end":1383.32}]},{"id":"odd-and-tangled","title":"略有点奇葩且拧巴，哈哈哈","category":"story","sequence":4,"duration":1320.568163,"audio":"odd-and-tangled.mp3","palette":["#516153","#6d5f54"],"cues":[{"text":"今天讲的故事，事情开始在我大学毕业实习那年。","paragraph":0,"style":"plain","start":2.32,"end":6.6},{"text":"刚刚结束新手保护期，我身份上还没准备过来。","paragraph":0,"style":"plain","start":7.34,"end":11.2},{"text":"但也没有人会等你准备好。","paragraph":0,"style":"plain","start":12.04,"end":13.8},{"text":"一出校门，所有人就默认你已经掌握了身为社畜的生存方式。","paragraph":0,"style":"plain","start":14.4,"end":18.74},{"text":"然而实际上，我当时连打印机都不太会用。","paragraph":0,"style":"plain","start":19.98,"end":22.86},{"text":"我进的是一家品牌活动和营销执行的公司说的高端一点就是帮客户做方案跑项目 低情商的说就","paragraph":1,"style":"plain","start":24.04,"end":32.69},{"text":"是个臭外包的直属的小领导是个女生具体比我大多少我不知道不过在这家公司已经工作两年了虽","paragraph":1,"style":"plain","start":32.69,"end":42.96},{"text":"然职位不是很高但很多项目的进度以及供应商对接傻的基本都是由她负责她的声音很轻 说话也","paragraph":1,"style":"plain","start":42.96,"end":51.8},{"text":"不急不像我想象中那种雷厉风行的职场姐","paragraph":1,"style":"plain","start":51.8,"end":55.32},{"text":"长得也没有什么攻击性穿着简单的白衬衫和黑色长裤笑起来的时候眼睛会弯出一个好看的弧度怎","paragraph":2,"style":"plain","start":56.18,"end":66.06},{"text":"么说呢就是你刚到一个完全陌生的地方周围全都是看不懂的流程和叫不上名字的同事但只要她正","paragraph":2,"style":"plain","start":66.06,"end":74.26},{"text":"在旁边就会让人稍微安心一点","paragraph":2,"style":"plain","start":74.26,"end":77.0},{"text":"当然这种安心也只维持到了第一次开会当时我抱着电脑坐在她旁边客户一口气提了十几个修改意","paragraph":3,"style":"plain","start":80.72,"end":90.02},{"text":"见我还在想什么是视觉再年轻一点质感再成熟一点她已经一边回应一边把重点全都记了下来会议","paragraph":3,"style":"plain","start":90.02,"end":100.44},{"text":"结束后她瞄了一眼我的电脑问我听懂了多少我很诚实地回答大概60%吧她说挺好的我刚要松口","paragraph":3,"style":"plain","start":100.44,"end":110.92},{"text":"气她又补充到剩下的刚好都是重点","paragraph":3,"style":"plain","start":110.92,"end":114.96},{"text":"那天我整理的会议记录和需求清单只忙活了一下午自认为写的十分专业但交过去以后就被她像老","paragraph":4,"style":"plain","start":116.24,"end":124.4},{"text":"师一样批改的到处都是标注我有点不好意思说自己是不是耽误她工作了她却摇摇头告诉我新人不","paragraph":4,"style":"plain","start":124.4,"end":134.013},{"text":"知道很正常不问才麻烦又把我的椅子拉到旁边一条一条的解释为什么要这么写那时候已经快到下","paragraph":4,"style":"plain","start":134.013,"end":143.34},{"text":"班时间了窗外的天色慢慢的暗了下来","paragraph":4,"style":"plain","start":143.34,"end":146.62},{"text":"电脑屏幕映着她的侧脸她没有不耐烦也没有故意说一些高深的黑话只是把自己踩过的坑一点一点","paragraph":5,"style":"plain","start":147.3,"end":156.42},{"text":"的告诉我最后的日子我就整天跟着她跑业务上午去客户公司开会下午到商场看活动场地有时候还","paragraph":5,"style":"plain","start":156.42,"end":168.12},{"text":"要跑去郊区的制作工厂确认物料她也不藏着掖着大事小事都会顺手教一下然后耐着性子告诉我为","paragraph":5,"style":"plain","start":168.12,"end":176.653},{"text":"什么我有什么事情做得好她也会大大方方地夸我两句","paragraph":5,"style":"plain","start":176.653,"end":180.66},{"text":"对于我这种刚入社会的新人来说很多时候最好的鼓励就是认可和肯定嘛那可以让你在工作里找到","paragraph":6,"style":"plain","start":181.64,"end":190.2},{"text":"某种成就感所以对她的每一声领导那都是出于心底的尊重但她似乎不太喜欢这个称呼说自己就是","paragraph":6,"style":"plain","start":190.2,"end":199.26},{"text":"个项目执行算不上什么领导所以从那以后就叫她姐因为和她混熟一点以后我拍马屁的时候都会说","paragraph":6,"style":"plain","start":199.26,"end":209.06},{"text":"上一句李姐万岁她也会白了我一眼说","paragraph":6,"style":"plain","start":209.06,"end":212.72},{"text":"你怎么不去跑业务呢相处久了我发现她的温柔并不是好说话供应商敷衍的工作，","paragraph":7,"style":"plain","start":212.72,"end":220.76},{"text":"她照样会一条一条地提出问题。","paragraph":7,"style":"plain","start":221.11,"end":223.04},{"text":"客户临时改需求，她也会明确告诉对方时间和预算上的边界。","paragraph":7,"style":"plain","start":223.94,"end":228.18},{"text":"但是她说话永远不急，总能给别人留一点台阶。","paragraph":8,"style":"plain","start":228.96,"end":232.1},{"text":"不过慢慢地，你就会发现，你站在了她想让你站的位置上。","paragraph":9,"style":"plain","start":234.24,"end":239.28},{"text":"总之我在她的身上，学到了不少东西，然后我也不知道该怎么感谢人家。","paragraph":9,"style":"plain","start":240.38,"end":245.3},{"text":"就只能每天早上准时准点的给她带一杯爱喝的燕麦拿铁她也不白喝有什么客户那边送的小礼物也","paragraph":9,"style":"plain","start":245.78,"end":254.74},{"text":"会给我带上一份就这样三个月过去了我在李姐的小教室也算顺利的转正我们之间的聊天","paragraph":9,"style":"plain","start":254.74,"end":263.24},{"text":"也从工作情理纯粹的业务沟通慢慢有了一些私人微信上的闲聊比如一起吐槽大老板或者介绍一下","paragraph":10,"style":"plain","start":263.24,"end":272.02},{"text":"客户的离谱要求但从来没有说过情感话题那时候我也没有什么非分之想直到后来有一次我们做了","paragraph":10,"style":"plain","start":272.02,"end":281.72},{"text":"一个时尚相关的项目我记得那甲方的公司里基本都是女的颜值另说但都挺会打扮的不过是那种很","paragraph":10,"style":"plain","start":281.72,"end":291.41},{"text":"有距离感的穿着我看了半天","paragraph":10,"style":"plain","start":291.41,"end":293.98},{"text":"还是觉得旁边的李姐更好看一些然后晚上闲聊的时候说几白天的事我们就第一次聊到的情感话题","paragraph":11,"style":"plain","start":294.36,"end":302.22},{"text":"她直言不讳地说公司有规定啊不能和客户之间有什么关系我寻思我怎么了她就说我白天的时候眼","paragraph":11,"style":"plain","start":302.7,"end":312.74},{"text":"睛都看直了我说那是在分析客户的类型只没看碟下菜呢再说了她没听我的解释却捕捉到了我没说","paragraph":11,"style":"plain","start":312.74,"end":322.82},{"text":"完的话再说什么我想说他们都没你好看","paragraph":11,"style":"plain","start":322.82,"end":327.52},{"text":"敢说就没敢说出来她就猜我是不是已经有对象了我说您看我像是有对象的人吗她说你大学都没谈","paragraph":12,"style":"plain","start":328.26,"end":338.0},{"text":"女朋友吗我就发了一个流汗的表情没有回答话头一转到了她的身上你别光说我呀我也没见你男朋","paragraph":12,"style":"plain","start":338.0,"end":347.38},{"text":"友啊","paragraph":12,"style":"plain","start":347.38,"end":347.94},{"text":"她嘴硬地表示我那是忙着搞钱跟你在学校的摸鱼可不一样而且我认识的男生不是客户就是同事看","paragraph":13,"style":"plain","start":350.12,"end":359.92},{"text":"谁都像个待解决的问题我很好奇的问她那我是大问题还是小问题没想到她却说你是我的小帮手那","paragraph":13,"style":"plain","start":359.92,"end":371.56},{"text":"天晚上我抱着手机笑了半天也不知道在高兴些什么大概也就是从这次对话以后两个人偶尔会说一","paragraph":13,"style":"plain","start":371.56,"end":380.13},{"text":"点情感话题言语里也会带一些暧昧","paragraph":13,"style":"plain","start":380.13,"end":383.58},{"text":"然后我们整天跑现场嘛有时候结束的很晚她看我赶不上地铁最后代步的小车顺路送了一段第一次","paragraph":14,"style":"plain","start":384.94,"end":393.76},{"text":"我还挺不好意思的后来坐得多了脸皮就逐渐厚了车里很乱跟她的人不太一样后排塞了一堆活动的","paragraph":14,"style":"plain","start":393.76,"end":403.26},{"text":"物料说是为了方便用就一直放在车上我有问过她送我会不会绕远但她每次都说顺路直到后来有一","paragraph":14,"style":"plain","start":403.26,"end":413.14},{"text":"次我送她回家才发现她住的地方跟我家完全不沾边","paragraph":14,"style":"plain","start":413.14,"end":417.54},{"text":"我记得那是一次比较大的公司聚会有个男同事一直都挺喜欢李姐的平时就借着工作找她说话那天","paragraph":15,"style":"plain","start":418.86,"end":428.6},{"text":"喝了点酒以后就更加积极了一会过去敬一杯一会又说项目结束必须单独感谢她李姐开始还礼貌性","paragraph":15,"style":"plain","start":428.6,"end":438.54},{"text":"地喝两口后来明显有些不舒服，","paragraph":15,"style":"plain","start":438.54,"end":441.22},{"text":"笑容也变得很勉强。","paragraph":15,"style":"plain","start":441.94,"end":443.38},{"text":"那男同事应该也看出来了，但还在给她灌酒。","paragraph":16,"style":"plain","start":444.2,"end":447.3},{"text":"我心里有点不爽，但也不好直接说什么。","paragraph":16,"style":"plain","start":448.28,"end":451.06},{"text":"于是就拿起自己的杯子，把那个男同事给拦了过来。","paragraph":16,"style":"plain","start":451.8,"end":455.54},{"text":"也一杯接一杯地给他灌酒。","paragraph":16,"style":"plain","start":456.36,"end":457.86},{"text":"好在那时候我年轻，身体素质够硬。","paragraph":16,"style":"plain","start":458.7,"end":461.28},{"text":"那男同事后来喝得有点蒙圈，也没力气再打扰李姐了。","paragraph":17,"style":"plain","start":462.02,"end":466.32},{"text":"她呢，就全程没有说话，只是抬眼看着我。","paragraph":17,"style":"plain","start":467.22,"end":470.32},{"text":"后面她又喝了一点，散场的时候整个人晕乎乎的，肯定是不能开车了。","paragraph":17,"style":"plain","start":471.3,"end":477.1},{"text":"我就帮忙叫了代驾，跟她一起回去。","paragraph":17,"style":"plain","start":477.86,"end":480.3},{"text":"平时的李姐总是坐得很端正，那天就软绵绵的瘫在了座椅上，身上还带着淡淡的酒香味。","paragraph":18,"style":"plain","start":481.58,"end":489.98},{"text":"我怕吵醒她，我自觉的呼吸都放轻了。","paragraph":18,"style":"plain","start":490.54,"end":494.02},{"text":"她倒是没睡着，闭着眼睛说了句谢谢你帮我挡酒。","paragraph":18,"style":"plain","start":494.9,"end":498.98},{"text":"我愣了一下，说是为了明天的工作。","paragraph":19,"style":"plain","start":499.94,"end":503.06},{"text":"她带着醉意的问，真的啊，难道没有一点别的心思？","paragraph":19,"style":"plain","start":504.6,"end":508.24},{"text":"我心脏猛的跳了一下，虽然还是平静的回答，你是真没少喝呀。","paragraph":19,"style":"plain","start":509.2,"end":515.0},{"text":"没想到她就变本加厉地靠过来眼神有点迷离地说小朋友可以吃醋但是要少喝酒知道吗李姐离得很","paragraph":19,"style":"plain","start":516.18,"end":526.94},{"text":"近车窗外的路灯一下扫过她的脸我看着她那正经的模样就深吸的一口气回答说好 我知道了","paragraph":19,"style":"plain","start":526.94,"end":536.76},{"text":"她嘟嘟囔囔地说了句这样才乖然后没多久就睡着了等她再醒来的时候已经到了她家楼下她整个人","paragraph":20,"style":"plain","start":537.6,"end":547.86},{"text":"还是懵懵的楼门的密码按了两三遍才输入正确就这没有心思调戏我站在门口学着那些言情剧里的","paragraph":20,"style":"plain","start":547.86,"end":558.04},{"text":"样子问我要不要上楼喝口水我知道她是说着玩的就催促她赶紧回去休息他们一眯眼睛笑着说姐姐","paragraph":20,"style":"plain","start":558.04,"end":568.62},{"text":"都邀请你了一点都不心动吗我就努力地控制自己","paragraph":20,"style":"plain","start":568.62,"end":573.66},{"text":"说明天你要还记得的话可以再邀请一次她愣了几秒然后很轻的说着去晚安就上楼了我站在门外听","paragraph":21,"style":"plain","start":573.66,"end":586.84},{"text":"着她远去的脚步有点后悔想着刚才如果自己不要脸一点不知道会发生什么样的事情不过后来想了","paragraph":21,"style":"plain","start":586.84,"end":595.56},{"text":"想还是算了喜欢一个人又不是去抢什么限量商品没必要趁着人家神志不清醒的时候下单果不其然","paragraph":21,"style":"plain","start":595.56,"end":605.2},{"text":"第二天李姐就什么都不记得了或者说装作什么都不记得","paragraph":21,"style":"plain","start":605.64,"end":610.64},{"text":"她又变回了那个成熟稳重的小领导只不过那天早上她给我带了一杯喝的还着重的说了句这是她从","paragraph":22,"style":"plain","start":611.34,"end":620.16},{"text":"家里带来的从那以后我们的关系就彻底进入了一种谁都看得出来但谁都没有明说的阶段那时候部","paragraph":22,"style":"plain","start":620.16,"end":630.14},{"text":"门又安排我接触了别的项目不能每天跟着她跑业务了不过可能是距离产生美吧我们下班以后联系","paragraph":22,"style":"plain","start":630.14,"end":638.78},{"text":"的反而变得更多了节假日也开始单独出来玩","paragraph":22,"style":"plain","start":638.78,"end":642.74},{"text":"夏天刚结束的时候我们那边的游乐场有什么促销活动她刷到视频以后就问我想不想去我说这种地","paragraph":23,"style":"plain","start":643.94,"end":652.79},{"text":"方不是小情侣小两口区的吗她回对了一句那也可以使家长带着小儿去我看着手机笑出了声最后回","paragraph":23,"style":"plain","start":652.79,"end":661.5},{"text":"了个购票成功的截图去游乐园那天她把头发扎成了高高的马尾完全没了在公司里那种成熟稳重的","paragraph":23,"style":"plain","start":661.5,"end":670.7},{"text":"形象一进门就拉着我去研究地图说要先玩刺激的项目","paragraph":23,"style":"plain","start":670.7,"end":676.04},{"text":"结果第一个云霄飞车她就吓得失去个表情管理尖叫声差点没把我直接送走本来我还想笑她，","paragraph":24,"style":"plain","start":676.4,"end":684.34},{"text":"后来发现她好像是真的害怕，就紧紧握住了她的手。","paragraph":24,"style":"plain","start":684.52,"end":689.02},{"text":"那天我看到了她很多工作以外的样子，她会因为套中一个小玩偶，开心半天，","paragraph":24,"style":"plain","start":690.44,"end":695.82},{"text":"或在鬼屋里像个小女孩一样抓着我的衣角。","paragraph":24,"style":"plain","start":696.52,"end":699.16},{"text":"也会买两个幼稚的头箍，然后强行把另外一个套在了我的头上。","paragraph":25,"style":"plain","start":700.22,"end":704.4},{"text":"以前我总觉得她像一杯温度刚好的白开水，稳定柔和，很少会出现特别强烈的情绪。","paragraph":25,"style":"plain","start":705.4,"end":713.1},{"text":"但那天我才发现，这杯温水的下面也藏着一个爱玩、怕高、会撒娇的小姑娘。","paragraph":25,"style":"plain","start":713.68,"end":720.24},{"text":"只不过她太早习惯了独立，很少会把不为人知的一面表现出来。","paragraph":26,"style":"plain","start":721.06,"end":725.86},{"text":"傍晚的时候，我们一起去坐了摩天轮，随着机器缓缓转动，游乐园的灯光在脚下铺成了一片，","paragraph":26,"style":"plain","start":726.88,"end":734.74},{"text":"下面喧闹的人们也渐渐听不清了。","paragraph":26,"style":"plain","start":735.76,"end":738.12},{"text":"她坐在我的对面，手里一直捏着那个套圈得到的小玩偶。","paragraph":27,"style":"plain","start":738.98,"end":743.18},{"text":"问我是不是觉得她和平时不太一样，我说确实不太一样，今天比较像个毛手毛脚的实习生。","paragraph":27,"style":"plain","start":743.96,"end":751.5},{"text":"她笑了一下，没有像往常一样回对，好像在做什么心理斗争过了一会儿才说，","paragraph":27,"style":"plain","start":752.21,"end":759.02},{"text":"这是她第一次来游乐场这种地方玩","paragraph":27,"style":"plain","start":759.82,"end":761.84},{"text":"我知道她比较有事业心，也比较好强，但却是没想到这是她第一次来她跟我说，","paragraph":28,"style":"plain","start":764.2,"end":771.5},{"text":"也不是自己不想来，是没有机会来家里有一个哥哥和一个弟弟，","paragraph":28,"style":"plain","start":772.26,"end":777.34},{"text":"自己夹在中间哥哥从小不争气父母呢又把所有的希望放在那弟弟的身上好的东西都先给两个儿子","paragraph":28,"style":"plain","start":777.88,"end":787.1},{"text":"所以别说什么游乐园了大学的学费都是她自己靠着助学贷款和兼职交上的毕业以后她就留在了这","paragraph":28,"style":"plain","start":787.84,"end":796.54},{"text":"座城市","paragraph":28,"style":"plain","start":796.54,"end":797.16},{"text":"没和父母要过一分钱别人总觉得她温柔稳定什么都可以处理得很好那是因为她曾早就知道出了问","paragraph":29,"style":"plain","start":797.6,"end":807.04},{"text":"题不会有任何人为她兜底所以就更没有放松的机会她说这句话的时候很平静甚至比赛公司里做最","paragraph":29,"style":"plain","start":807.04,"end":816.9},{"text":"简单的项目还要平静但我看着她紧紧捏住手里的玩偶还是能够感觉到她对那些事情的耿耿于怀我","paragraph":29,"style":"plain","start":816.9,"end":826.26},{"text":"不知道该怎么安慰她什么都过去了你很优秀之类的","paragraph":29,"style":"plain","start":826.26,"end":830.88},{"text":"听上去都太轻巧了于是就坐到她的旁边把那个快要被捏变形的小玩偶解救出来又把自己的手递给","paragraph":30,"style":"plain","start":831.3,"end":840.22},{"text":"了她","paragraph":30,"style":"plain","start":840.22,"end":840.54},{"text":"我说那以后我带你去玩有什么事情也可以分我一点","paragraph":31,"style":"plain","start":842.6,"end":847.52},{"text":"你一个小朋友能兜着什么呢我就拿着小玩偶在她面前表演大项目不一定小领导应该没问题她终于","paragraph":32,"style":"plain","start":849.36,"end":860.54},{"text":"被逗笑了靠在了座椅上望着窗外越来越近的最高点问我小实习生啊你是在和我告白吗我深吸了一","paragraph":32,"style":"plain","start":860.54,"end":871.82},{"text":"口气回答说是的我喜欢你很久了不是因为你的照顾也不是觉得你可怜我就是喜欢跟你待在一起工","paragraph":32,"style":"plain","start":871.82,"end":882.62},{"text":"作当中也好日常当中也罢你所有的样子我都喜欢","paragraph":32,"style":"plain","start":882.62,"end":887.74},{"text":"她直勾勾的看着我半天良久才说出了自己的担心说自己其实不太敢结婚和孩子什么的她害怕自己","paragraph":33,"style":"plain","start":888.84,"end":898.88},{"text":"的孩子会重新经历自己的痛苦我听完没怎么过脑子就直接说那我们只要一个男还是女孩都行反正","paragraph":33,"style":"plain","start":898.88,"end":908.86},{"text":"只要是跟你的孩子那我肯定都会喜欢但话说出口整个座舱里一下就安静了我就才反应过来我们连","paragraph":33,"style":"plain","start":908.86,"end":919.68},{"text":"关系都没确定的孩子生几个都想好了","paragraph":33,"style":"plain","start":919.68,"end":922.5},{"text":"所以试图补救等于说了句我的意思是假如以后有这个机会的话","paragraph":34,"style":"plain","start":923.52,"end":929.18},{"text":"她又被我局促的样子逗笑了然后靠在我的肩膀上笑就说那就允许你的恋爱项目试运行一下吧","paragraph":35,"style":"plain","start":931.32,"end":940.76},{"text":"那天我们在游乐场待到了很晚","paragraph":36,"style":"plain","start":942.74,"end":945.0},{"text":"两个人把之前的互相试探的那些心思全都翻了出来她说每次看到我兴冲冲地跑到现场都会想起自","paragraph":37,"style":"plain","start":946.9,"end":955.24},{"text":"己刚工作时候的样子就是终于可以赚钱了也终于可以去追寻自己的生活了我问她是什么时候开始","paragraph":37,"style":"plain","start":955.24,"end":964.3},{"text":"故意送我回家的她装着糊涂的回答说不是一直顺路吗我说 领导你这个顺路顺得有点违背交通规","paragraph":37,"style":"plain","start":964.41,"end":974.26},{"text":"则吧她被拆穿以后也不尴尬反而笑着问","paragraph":37,"style":"plain","start":974.26,"end":978.72},{"text":"那你知道不顺路还上车我说因为我想跟你顺路吗她望了我一会儿然后伸手抱住了我那是我们的第","paragraph":38,"style":"plain","start":979.38,"end":989.84},{"text":"一次拥抱没有酒精也没有神志不清两个人都很确定自己在做什么就这样我们确认了关系","paragraph":38,"style":"plain","start":989.84,"end":998.72},{"text":"两个人的恋情跟普通情侣也没有什么区别上班时尽量公事公办下班以后一起吃饭逛街看电影后来","paragraph":39,"style":"plain","start":1001.74,"end":1011.78},{"text":"我去了另外一个项目组李姐也正式升职成为了正职的项目经理年龄差没有造成太多的问题也就偶","paragraph":39,"style":"plain","start":1011.78,"end":1020.2},{"text":"尔会有一些情侣期间的正常斗嘴一切似乎都在向好的方向发展但真正的麻烦还是她一直在逃避的","paragraph":39,"style":"plain","start":1020.2,"end":1029.76},{"text":"那个家庭","paragraph":39,"style":"plain","start":1029.76,"end":1030.42},{"text":"在一起的第三个年头吧她用工作这些年攒下的钱在工作附近买了一套不大不小的二手房首付几乎","paragraph":40,"style":"plain","start":1032.68,"end":1041.94},{"text":"掏空了积蓄每个月还要还一笔房贷但拿到钥匙的那天她特别开心在空荡荡的客厅里来回走了好几","paragraph":40,"style":"plain","start":1041.94,"end":1051.34},{"text":"圈说以后终于有一个真的属于自己的地方我陪着她装饰新家弄了一身脏也觉得很高兴可房子刚装","paragraph":40,"style":"plain","start":1051.34,"end":1062.54},{"text":"修好没多久她的父母听说她买房了就打了电话没有道喜","paragraph":40,"style":"plain","start":1062.54,"end":1067.66},{"text":"反而有点埋怨说弟弟申请了国外的学校各种前期费用加起来要不少钱话里话外希望她能够拿出来","paragraph":41,"style":"plain","start":1068.26,"end":1077.34},{"text":"20万她不是一点都不愿意帮说自己可以拿出几万块再多确实是没有了因为刚接完首付嘛装修也","paragraph":41,"style":"plain","start":1077.34,"end":1087.28},{"text":"花了一笔钱而且她自己也要生活但她父母不这么想理所当然觉得弟弟留学是全家的事道德绑架地","paragraph":41,"style":"plain","start":1087.28,"end":1097.72},{"text":"说她当姐姐的就应该帮着想办法","paragraph":41,"style":"plain","start":1097.72,"end":1099.68},{"text":"我本以为她会言辞激烈地拒绝没想到她沉默了半天最后竟然应了下来我虽然跟她在一起但她家里","paragraph":42,"style":"plain","start":1100.82,"end":1110.22},{"text":"的事情还是不好多嘴只能问她需不需要帮忙她什么都没说只是摇个摇头不过没一会儿她就在旁边","paragraph":42,"style":"plain","start":1110.22,"end":1119.9},{"text":"缩成一团哭了起来那是我第一次见到她如此脆弱的样子就心疼的把她紧紧的抱在了怀里试图给她","paragraph":42,"style":"plain","start":1119.9,"end":1129.43},{"text":"一点安慰","paragraph":42,"style":"plain","start":1129.48,"end":1130.04},{"text":"平静了一些之后我问她打算怎么办她又恢复了往常成熟的模样说先把房子卖了帮完父母这一次也","paragraph":43,"style":"plain","start":1132.78,"end":1141.72},{"text":"算尽了孝道之后就再也不管了但我回家以后，","paragraph":43,"style":"plain","start":1141.72,"end":1146.12},{"text":"脑子里就反反覆覆的出现，她拿到钥匙和哭泣的样子我不忍心看她失去那个属于自己的地方，","paragraph":43,"style":"plain","start":1146.64,"end":1154.5},{"text":"然后算了一下这两年自己攒的钱，最后发现就只有5万多块没办法，","paragraph":43,"style":"plain","start":1155.06,"end":1161.42},{"text":"我想了想还是去找了自己的原生家庭","paragraph":43,"style":"plain","start":1161.98,"end":1164.82},{"text":"我家虽然不是什么大富大贵，但日子过得还算可以，而且是独生子女嘛，父母也比较关注我","paragraph":44,"style":"plain","start":1165.98,"end":1173.58},{"text":"我一五一十地跟他们说了前因后果，爸妈都没有见过李姐，自然是一口回绝。","paragraph":45,"style":"plain","start":1176.12,"end":1182.74},{"text":"我直接跟爸妈立下的字据，说这笔钱算借的，他们拗不过我，","paragraph":45,"style":"plain","start":1183.24,"end":1188.1},{"text":"最后语重心长的提醒了我要小心诈骗，最后还是给我转了一笔钱。","paragraph":45,"style":"plain","start":1188.68,"end":1194.0},{"text":"李姐那边的人不肯收下这份钱我没办法就像急中生智地说那你要不要嫁给我这算是我给你的彩礼","paragraph":46,"style":"plain","start":1195.52,"end":1203.9},{"text":"她一听又反而有点生气结婚这事在她的心里其实还是挺神圣的不希望牵扯到金钱什么我也是真的","paragraph":46,"style":"plain","start":1204.39,"end":1213.28},{"text":"没招了那要不就算我借你的吧你想什么时候还都行","paragraph":46,"style":"plain","start":1213.28,"end":1217.76},{"text":"反正好说歹说的她勉强同意了然后又问我你求婚的事还算不算数我说当然算数她说好那我给你一","paragraph":47,"style":"plain","start":1219.6,"end":1230.36},{"text":"个特殊的借条刚开始我还以为是结婚证但登记那天刚去民政局她转头又带我去的银行和不动产的","paragraph":47,"style":"plain","start":1230.36,"end":1239.04},{"text":"登记中心然后在她那套房子上加上了我的名字我才反应过来这才是她说的借条我本来想拒绝了因","paragraph":47,"style":"plain","start":1239.04,"end":1248.87},{"text":"为那是她自己梦寐以求的独属于自己的家","paragraph":47,"style":"plain","start":1248.87,"end":1251.78},{"text":"但她的态度却很坚决笑着跟我说你现在已经是我的家人了事后我看着结婚证和房本却觉得有点好","paragraph":48,"style":"plain","start":1252.42,"end":1262.42},{"text":"笑按理说我们两个都不是什么特别传统的人结婚也不要求彩礼和车房什么的但这一圈下来好像又","paragraph":48,"style":"plain","start":1262.42,"end":1272.31},{"text":"一个都没少总之我们就这样结成了夫妻李姐不喜欢热闹的酒席也不想为了面子把婚礼变成一场活","paragraph":48,"style":"plain","start":1272.42,"end":1281.86},{"text":"动策划所以只是在简单的饭店里请了一下亲朋好友","paragraph":48,"style":"plain","start":1281.86,"end":1286.76},{"text":"走了一个过场但最后她还是没有叫上父母我们两个用这几年攒的假期出去旅游半个多月回来的时","paragraph":49,"style":"plain","start":1287.18,"end":1297.2},{"text":"候又是她开着车不过这一次我们的人生不是顺路而是在同一条路上","paragraph":49,"style":"plain","start":1297.2,"end":1304.96},{"text":"拧巴的故事讲完了","paragraph":50,"style":"plain","start":1307.34,"end":1308.72},{"text":"晚安小迷湖公主做个好梦","paragraph":51,"style":"plain","start":1310.64,"end":1312.94},{"text":"真实的故事就在这几天看你能不能猜到","paragraph":52,"style":"plain","start":1314.94,"end":1317.78}]},{"id":"bad-guys-away","title":"打跑所有的坏蛋","category":"story","sequence":5,"duration":1222.478367,"audio":"bad-guys-away.mp3","palette":["#465a4f","#7b6952"],"cues":[{"text":"你有没有想过现在的人最适合什么样的爱情？","paragraph":0,"style":"plain","start":4.42,"end":7.84},{"text":"我想过，甚至还特别仔细地想过。","paragraph":0,"style":"plain","start":9.22,"end":11.72},{"text":"就从大家不爱出门这点来说，我觉得现在的人最适合入室抢劫般的爱情，就主打一个强制爱，","paragraph":0,"style":"plain","start":12.44,"end":20.733},{"text":"让你在大门不出二门不迈的情况下遇到对方。","paragraph":0,"style":"plain","start":21.14,"end":24.38},{"text":"我也是真没想到啊有生之年自己还能遇到他妈的爱心劫匪事情就发生在前两个月","paragraph":1,"style":"plain","start":25.64,"end":33.4},{"text":"我高三刚毕业考上了一所本地还算不错的大学这一放假可给我爽快了今年好玩的游戏又特别多我","paragraph":2,"style":"plain","start":35.72,"end":45.12},{"text":"就整天在家里打游戏我不知道你爸妈啥样反正我爸妈就是那种看我在家里闲着浑身都难受的类型","paragraph":2,"style":"plain","start":45.12,"end":53.26},{"text":"但我又毕业了他们又拿我没办法最后就只能眼不见为净把我赶到郊区那边回迁的房子里说正好离","paragraph":2,"style":"plain","start":54.22,"end":62.94},{"text":"学校比较近让我先去适应一下大学生活我倒没啥意见","paragraph":2,"style":"plain","start":62.94,"end":67.54},{"text":"反正就是换个地方睡觉打游戏嘛而且没人管我了游戏操作都变得更加顺畅所以我几乎是连夜扛着","paragraph":3,"style":"plain","start":68.18,"end":77.14},{"text":"电脑搬过去的然后我记得特别清楚刚过去没几天的一个周四的晚上因为那天我正为了肯德基的5","paragraph":3,"style":"plain","start":77.14,"end":85.87},{"text":"0块钱发愁我妈打电话说明早要来一个租客让我收拾一下房间我不是很乐意怎么我都搬出来了你","paragraph":3,"style":"plain","start":85.87,"end":95.84},{"text":"还要找一个人打扰我的假期生活呢","paragraph":3,"style":"plain","start":95.84,"end":97.98},{"text":"她没好意思就说是为了赚钱然后撂下一句明天我去检查就挂断了语音我放眼望去已经被我住成猪","paragraph":4,"style":"plain","start":98.86,"end":108.19},{"text":"窝的房间再变回人住的地方，","paragraph":4,"style":"plain","start":108.3,"end":110.9},{"text":"那要费老鼻子劲了我收拾了半天，","paragraph":4,"style":"plain","start":111.32,"end":114.28},{"text":"楼上楼下的来回倒了三次大垃圾才勉强有点人样收拾的差不多了，","paragraph":4,"style":"plain","start":114.92,"end":120.86},{"text":"就看到我妈推了个微信说是那个租客的我加上一看，","paragraph":4,"style":"plain","start":121.04,"end":125.78},{"text":"头像是那种玲娜贝儿的表情包叫什么离离原上谱","paragraph":4,"style":"plain","start":126.38,"end":129.96},{"text":"就明显是个跟我差不多大的女生女生？","paragraph":5,"style":"plain","start":130.72,"end":134.78},{"text":"我又不知道我妈是咋想的我怎么也是十八九岁的小伙子她也不怕进去时两个人出来时三个因为时","paragraph":5,"style":"plain","start":135.32,"end":144.15},{"text":"间比较晚了嘛我加上那个女生的微信也没聊什么约定好时间我就继续熬夜打游戏第二天一睁眼还","paragraph":5,"style":"plain","start":144.15,"end":153.22},{"text":"差点错过了约好的时间简单洗漱一下就赶紧下楼去接她","paragraph":5,"style":"plain","start":153.22,"end":157.78},{"text":"她也特别好认倒不是人有什么特别主要是大包小包的堆在地上光是收纳箱就有五个，","paragraph":6,"style":"plain","start":160.16,"end":167.32},{"text":"不知道的还以为是来逃难的我跟人家简单打了个招呼，然后就帮她搬东西六月中旬已经很热了，","paragraph":6,"style":"plain","start":167.56,"end":176.46},{"text":"跑来跑去的搞得我浑身大汗干完活，就看到我妈像个领导一样，","paragraph":6,"style":"plain","start":176.78,"end":182.34},{"text":"背着手来做检查然后拉着人家嘘寒问暖，听两人的对话，好像还是个朋友的女儿","paragraph":6,"style":"plain","start":182.84,"end":190.32},{"text":"也在我那所学校上大三，","paragraph":7,"style":"plain","start":190.72,"end":192.45},{"text":"算是正儿八经的学姐从小到大我也没怎么和女生有太多的接触就更别说共处一室了所以我妈要走","paragraph":7,"style":"plain","start":192.82,"end":201.9},{"text":"的时候我就偷摸问了一嘴自己能不能搬回去她说那你能不打游戏吗我就摆摆手回答哎得算我没问","paragraph":7,"style":"plain","start":201.9,"end":211.36},{"text":"我妈走了以后这学姐就在布置房间我也不好意思在客厅待着就回房间玩了一下午的塞尔达因为昨","paragraph":7,"style":"plain","start":212.22,"end":221.28},{"text":"天晚上熬夜了","paragraph":7,"style":"plain","start":221.36,"end":222.32},{"text":"我玩着玩着就睡着了，这一觉就睡到了第二天的中午，打开微信看到学姐说，","paragraph":8,"style":"plain","start":222.96,"end":229.44},{"text":"我妈没给人家倒没药吃。","paragraph":8,"style":"plain","start":229.94,"end":231.24},{"text":"我出门发现她就在客厅里，也就不用再去找她。","paragraph":8,"style":"plain","start":232.18,"end":235.48},{"text":"昨天没怎么注意，现在细看一下，她还挺可爱的。","paragraph":9,"style":"plain","start":237.28,"end":241.42},{"text":"穿了一身米白色的衣服，深红色的头发扎在两个小辫，浅色的头绳点着的发尾，","paragraph":9,"style":"plain","start":242.02,"end":248.46},{"text":"就像个高中生一样。","paragraph":9,"style":"plain","start":248.94,"end":250.26},{"text":"完全看不出比我大了三岁嗯 但是我这里也只有一把钥匙再让我妈跑一趟也有点麻烦所以我们就","paragraph":9,"style":"plain","start":250.88,"end":259.5},{"text":"在附近找了一个锁具店打算再配一把到的时候店长在那儿刷着抖音他都看着我 又看了看学姐","paragraph":9,"style":"plain","start":259.5,"end":267.42},{"text":"感觉像是骂人一样 说了句我个人一把 你配吗我说 配配配配配然后店长半天才反应过来 我","paragraph":10,"style":"plain","start":268.02,"end":277.42},{"text":"也在骂人学姐反应到挺快的在旁边一个劲地偷笑配完钥匙以后我又让店长上门给学姐换了个锁芯","paragraph":10,"style":"plain","start":277.42,"end":286.84},{"text":"这是我妈吩咐的说就算两家认识人家女孩多少也会觉得不安","paragraph":10,"style":"plain","start":287.26,"end":292.4},{"text":"我觉得我妈妈说的对并且多给她要了100块的辛苦费反正就是乱七八糟的折腾下来已经下午三","paragraph":11,"style":"plain","start":294.24,"end":302.28},{"text":"点了我一死宅 运动量本来就不多再加上一天没吃饭整个人就头晕目眩的学姐还礼貌地问了我怎","paragraph":11,"style":"plain","start":302.35,"end":311.167},{"text":"么了我说我好像看到我太奶了正好她也饿了嘛我们俩就点了两份饭一起吃但也不知道说些什么就","paragraph":11,"style":"plain","start":311.167,"end":321.22},{"text":"只能尬聊她说她明年就要考研了想找个安静的空间学习","paragraph":11,"style":"plain","start":321.22,"end":326.3},{"text":"正巧又知道我妈这边有合适的地方于是就搬了过来我一听到这句话还有点不好意思我打游戏的时","paragraph":12,"style":"plain","start":326.8,"end":334.627},{"text":"候声音还是挺大的所以从那以后，","paragraph":12,"style":"plain","start":334.627,"end":337.36},{"text":"平时我都会自觉地放低音量过了12点就戴上耳机这么一想，","paragraph":12,"style":"plain","start":337.8,"end":343.18},{"text":"到底还是被我妈给算计到了说起来，","paragraph":12,"style":"plain","start":343.38,"end":346.92},{"text":"我本以为学姐的到来不会对我的生活有什么影响感觉就是家里多个人而已但没想到这和父母一起","paragraph":12,"style":"plain","start":347.34,"end":354.76},{"text":"住的情况完全不同","paragraph":12,"style":"plain","start":354.76,"end":355.82},{"text":"别的先不说天气一天比一天热她在家里穿的，","paragraph":13,"style":"plain","start":356.48,"end":361.38},{"text":"就一天比一天少大学那边因为还没放假嘛白天基本上看不到但晚上就会看到她穿着个吊带短裤什","paragraph":13,"style":"plain","start":361.66,"end":370.8},{"text":"么的在家里瞎晃悠偶尔路过还能闻到她身上的香味也不知道是香水还是沐浴露的味道我一个血气","paragraph":13,"style":"plain","start":370.8,"end":379.82},{"text":"方刚的小伙子哪受得了这个所以只好尽量在房间里待着","paragraph":13,"style":"plain","start":379.82,"end":384.54},{"text":"但人是关住了魂却飞了听她在客厅里走动的声音我就总想出去跟她说说话搞得玩游戏都有点分心","paragraph":14,"style":"plain","start":386.7,"end":395.42},{"text":"我家这房子原本打算是个爷爷奶奶住的但老人在乡下住惯了死活不来所以基本上就是个空房子只","paragraph":14,"style":"plain","start":396.3,"end":405.76},{"text":"有两张床和一台洗衣机以及我家里换下来的旧沙发可以说是家徒四壁学姐买了一堆锅碗瓢盆住在","paragraph":14,"style":"plain","start":405.84,"end":415.14},{"text":"寝室没条件附近的外卖也吃腻了","paragraph":14,"style":"plain","start":415.22,"end":417.92},{"text":"所以想自己研究点美食啥的我还是照常点外卖嘛她看到了就跟我说这有新鲜的 吃什么外卖呢我","paragraph":15,"style":"plain","start":418.52,"end":428.06},{"text":"本来想拒绝但实在是太香了我说的是学姐的饭菜太香了我就这样抱着碗在她学习的小桌上等待着","paragraph":15,"style":"plain","start":428.06,"end":437.22},{"text":"大餐说实话她做的真没外卖好吃但毕竟刚开始学嘛不过我却吃的比外卖还香我俩也就认识十多天，","paragraph":15,"style":"plain","start":437.22,"end":448.12},{"text":"相比最开始也算少了一些尴尬","paragraph":15,"style":"plain","start":448.84,"end":451.34},{"text":"最初我以为她是个性格比较内敛的女生，但相处下来其实还是挺热情的","paragraph":16,"style":"plain","start":451.88,"end":458.12},{"text":"我过两个月就要去报到了嘛，所以学姐跟我说了一堆入学要准备的事情不过因为我是走读，","paragraph":17,"style":"plain","start":459.92,"end":466.88},{"text":"可以省去很多麻烦我从小到大都没有经历过集体生活，","paragraph":17,"style":"plain","start":467.16,"end":471.28},{"text":"所以还挺好奇住校是什么体验学姐一脸惆怅的表情说其实她自己搬出来主要还是和一个室友不太","paragraph":17,"style":"plain","start":471.94,"end":480.02},{"text":"对付我也没好意思细问是什么原因就装模作样的安慰她说哎 有人的地方就有江湖嘛她知道我在","paragraph":17,"style":"plain","start":480.02,"end":489.38},{"text":"逗她","paragraph":17,"style":"plain","start":489.38,"end":489.68},{"text":"就会心一笑整个人开心了一点然后说有时间的话可以带我去学校里逛一下提前感受一下那天吃完","paragraph":18,"style":"plain","start":489.78,"end":499.48},{"text":"饭我发现她的食材没地方保存跟我妈反应以后我妈也不知道从哪儿淘了一个二手的小冰箱还挺新","paragraph":18,"style":"plain","start":499.48,"end":507.5},{"text":"的就是外表稍微有点旧学姐看到以后喜出望外完全没有嫌弃的意思开心的把冰箱塞满了各种吃的","paragraph":18,"style":"plain","start":507.5,"end":516.88},{"text":"大概也是从那天以后吧","paragraph":18,"style":"plain","start":517.46,"end":519.08},{"text":"我俩晚上时不时的就会在一起吃个饭她忙不过来的时候还会叫我帮忙打下手她的厨艺是越来越好","paragraph":19,"style":"plain","start":519.46,"end":527.96},{"text":"我也渐渐的开始期待晚上的时间每次听到大门的响声，","paragraph":19,"style":"plain","start":528.48,"end":532.9},{"text":"就像巴甫洛夫的狗一样，开始条件反射的分泌唾液。","paragraph":19,"style":"plain","start":533.3,"end":536.74},{"text":"这事我和好兄弟说了以后，她一脸嫌弃的表示，呸，你那是馋人家的饭吗？","paragraph":20,"style":"plain","start":538.14,"end":543.92},{"text":"你下贱。","paragraph":20,"style":"plain","start":544.38,"end":544.86},{"text":"我也不置可否，对于一个青春期的小伙子来说，住在同一个屋檐下的化学反应，还是太致命了。","paragraph":21,"style":"plain","start":547.02,"end":554.08},{"text":"我也说不上来到底是不是喜欢，反正一想到她就会觉得很开心。","paragraph":21,"style":"plain","start":554.8,"end":559.1},{"text":"心学姐那边终于放假了但也没有回家的意思说受不了父母的唠叨我就调侃道这也算是同一个世界","paragraph":21,"style":"plain","start":559.1,"end":568.46},{"text":"同一个妈了我俩熟了以后她也不装了每到这时候就像个老流氓似的一脸挑逗的跟我说","paragraph":21,"style":"plain","start":568.46,"end":576.58},{"text":"什么同一个妈我哪见过这种场面直接就是大脑宕机事后又觉得嘴笨为什么没说点什么她因此也一","paragraph":22,"style":"plain","start":577.06,"end":588.3},{"text":"口一个小朋友的叫我有些开心也有些懊恼虽然看着这关系更亲近了但女生好像都喜欢比自己成熟","paragraph":22,"style":"plain","start":588.38,"end":597.0},{"text":"的男生她明显只把我当个弟弟但我也没有什么办法年龄和阅历的差距也不是一时半会儿能弥补的","paragraph":22,"style":"plain","start":597.0,"end":605.36},{"text":"就只好顺其自然学姐也是一个比较宅的人","paragraph":22,"style":"plain","start":605.36,"end":609.8},{"text":"放假后偶尔和朋友出去逛一圈平时就和我一样在家里避暑我除了打游戏以外还喜欢画画主要是喜","paragraph":23,"style":"plain","start":610.5,"end":619.38},{"text":"欢ACG相关的东西课余的时间瞎玩一玩可能是画技太烂了她看到我画板上的风景就问我这画的","paragraph":23,"style":"plain","start":619.38,"end":629.02},{"text":"是哪儿我就一脸无语的指着指阳台外我像是那种会出门采景的人吗她两边对比着看了一眼一边笑","paragraph":23,"style":"plain","start":629.02,"end":639.64},{"text":"一边说还挺像的然后突然想起来还没带我去学校逛过","paragraph":23,"style":"plain","start":639.64,"end":644.8},{"text":"就问我现在想不想去我以为她都忘干净了没想到还能记起来所以就稍微收拾了一下顶着外面30","paragraph":24,"style":"plain","start":645.22,"end":653.62},{"text":"度的高温和她跑到的学校放假也没几天学校里面还有一些人她就乱七八糟的介绍了一堆地方我也","paragraph":24,"style":"plain","start":653.62,"end":662.26},{"text":"没怎么记住不过有件事特别有趣我们瞎逛的时候遇到了她那个不太对付的室友我是完全没看出来","paragraph":24,"style":"plain","start":662.26,"end":670.7},{"text":"她俩之间有什么矛盾两个人有说有笑得闹了半天","paragraph":24,"style":"plain","start":670.7,"end":674.56},{"text":"可能这就是女孩子的友谊吧学姐没有明说和我之间的关系","paragraph":25,"style":"plain","start":675.2,"end":679.96},{"text":"那个室友就一脸笑意的打量我好像看穿了什么一样分别以后学姐跟我说这人喜欢的男生喜欢学姐","paragraph":26,"style":"plain","start":682.06,"end":690.38},{"text":"所以她在寝室里总是阴阳怪气的现在以为我是学姐的男朋友态度才缓和了一些估计也会传到那个","paragraph":26,"style":"plain","start":691.02,"end":699.2},{"text":"男生的耳朵里吧我心想，","paragraph":26,"style":"plain","start":699.2,"end":701.58},{"text":"果然有人的地方就有江湖。","paragraph":26,"style":"plain","start":702.08,"end":703.76},{"text":"但紧接着又想到，那他们误会我们的关系了吗？","paragraph":27,"style":"plain","start":704.6,"end":707.94},{"text":"学姐又是一副老流氓的样子说，那你努力一下，变成事实。","paragraph":27,"style":"plain","start":708.513,"end":713.98},{"text":"我又是一阵无语，真搞不明白，她到底是有心还是开玩笑？","paragraph":27,"style":"plain","start":714.82,"end":719.16},{"text":"总之我们就在学校里逛了半天，还去食堂品鉴了一下阿姨的手艺。","paragraph":27,"style":"plain","start":720.26,"end":724.5},{"text":"出门的时候已经是下午了，吃完饭就到了傍晚。","paragraph":28,"style":"plain","start":725.22,"end":728.48},{"text":"数条细长的碎云一缕一缕的缠绕在坠落的红日上余晖不断的蔓延，","paragraph":28,"style":"plain","start":729.19,"end":735.44},{"text":"渐变成墨蓝的天色我们两个走在回家的路上学姐拍了拍自己的肚子说吃多了，","paragraph":28,"style":"plain","start":736.12,"end":743.72},{"text":"我瞥了一眼完全看不出来有什么变化就顺口说了一句小度小度而已学姐也很懂啊又拍了一下肚子","paragraph":28,"style":"plain","start":744.0,"end":753.48},{"text":"回答道我在两个人就相视嘿嘿一笑","paragraph":28,"style":"plain","start":753.48,"end":757.68},{"text":"那一刻暧昧的氛围真的特别美好","paragraph":29,"style":"plain","start":758.08,"end":760.54},{"text":"我们一路上聊着天从各自的喜好到生活中的趣事我喜欢的她也能欣赏她憧憬的也是我能理解的了","paragraph":30,"style":"plain","start":763.16,"end":773.84},{"text":"解的越多越觉得面前的姑娘就越是动人也许是从那以后吧我感觉自己的恋爱脑愈发严重玩游戏都","paragraph":30,"style":"plain","start":773.84,"end":783.8},{"text":"觉得索然无味总是会想在墙的另一边学姐在干什么甚至晚上熬夜的变少了就希望白天的时候能和","paragraph":30,"style":"plain","start":783.8,"end":791.92},{"text":"她多一些交流当我一个母胎solo","paragraph":30,"style":"plain","start":791.97,"end":794.9},{"text":"我是真搞不懂她的态度我也不知道我自己A上去会有什么后果所以就强迫自己做点事情分散一下","paragraph":31,"style":"plain","start":794.9,"end":802.64},{"text":"注意力正巧高中的时候几个同学约我去短期旅游我也就答应了临走前我试探了一下学姐的反应她","paragraph":31,"style":"plain","start":802.64,"end":813.12},{"text":"好像完全不在乎说终于可以享受一下美好的独居生活了说实话听她这么讲我心里还是有点失落的","paragraph":31,"style":"plain","start":813.12,"end":821.88},{"text":"所以第二天一早我没打招呼就出发了","paragraph":31,"style":"plain","start":822.44,"end":825.16},{"text":"因为我们这里是海边城市所以就去了云南那边风景很好高山古镇蛮有人文气息的但不知道为什么","paragraph":32,"style":"plain","start":826.08,"end":835.34},{"text":"总觉得开心不起来好像缺少了一个情绪出口直到晚上的时候学姐那边发了微信我才终于明白这种","paragraph":32,"style":"plain","start":835.78,"end":844.9},{"text":"感受的源头原来和喜欢的人分享眼前的一切才是旅行中最开心的事情学姐之前也来过云南跟我讲","paragraph":32,"style":"plain","start":844.9,"end":855.4},{"text":"着什么景点有雷什么地方必去","paragraph":32,"style":"plain","start":855.4,"end":857.8},{"text":"然后还有点埋怨我的不辞而别说云南旁边就是缅北你小心你的腰子我躺在床上直接气笑了就毁了","paragraph":33,"style":"plain","start":858.92,"end":869.12},{"text":"个你怎么这么担心我的腰子呀然后她直接一套打拳的表情包刷屏第二天我还是照常的逛吃逛吃有","paragraph":33,"style":"plain","start":869.12,"end":879.22},{"text":"事没事和学姐闲聊几句到晚上的时候学姐给我打了电话说想听我白天旅游的经历当时我也没发现","paragraph":33,"style":"plain","start":879.22,"end":888.34},{"text":"有什么异常旅游回来就看到学姐蜷坐在沙发上","paragraph":33,"style":"plain","start":888.34,"end":892.9},{"text":"一副精神衰弱的样子我才知道那两天晚上门口有人徘徊不过这事倒是个乌龙我就问了一下对门的","paragraph":34,"style":"plain","start":893.46,"end":903.1},{"text":"晚上加班连续两天没带钥匙家里的小孩也跑出去补习所以只好在门口等着但学姐第一时间想到我","paragraph":34,"style":"plain","start":903.1,"end":912.1},{"text":"我还是挺开心的就当时看她红着眼睛楚楚可怜的发泄着内心的害怕一瞬间有一种被需要的感觉至","paragraph":34,"style":"plain","start":912.1,"end":921.98},{"text":"少在她的心里我也算是可以依靠的男生总而言之","paragraph":34,"style":"plain","start":921.98,"end":927.34},{"text":"旅游回来以后我们的关系变得更加要好不光晚上会一起吃饭白天没事的时候也会一起出门看个电","paragraph":35,"style":"plain","start":927.34,"end":935.9},{"text":"影什么的","paragraph":35,"style":"plain","start":935.9,"end":936.54},{"text":"我记得那段时间封神很火我俩看完以后就在家里整天商言商语就连我吃饭说一嘴好吃她都要接一","paragraph":36,"style":"plain","start":938.72,"end":948.68},{"text":"句您那么爱你的儿子怎么连她的味道都尝不出来呢我一口饭差点没噎死一边笑一边说差不多得了","paragraph":36,"style":"plain","start":948.68,"end":961.08},{"text":"我犯的又不是死罪就在这样的日常当中八月慢慢的过去了大半学姐的假期最终还是没有回家嘛所","paragraph":36,"style":"plain","start":961.08,"end":973.38},{"text":"以剩下的日子打算回家看看","paragraph":36,"style":"plain","start":973.38,"end":975.42},{"text":"临走的前两天我们去了趟海边其实像我这种在海边城市长大的对沙滩啊 大海啊已经是祛魅的心","paragraph":37,"style":"plain","start":976.52,"end":985.64},{"text":"态了平时也没有什么想法但夏天如果不去一次的话就感觉不太完整学姐还让我带上了画板说你可","paragraph":37,"style":"plain","start":985.64,"end":996.02},{"text":"画点阳台以外的东西吧我们就拎着零食带着画板和凳子选了个阴凉的地方坐下我在一边画画她就","paragraph":37,"style":"plain","start":996.02,"end":1005.7},{"text":"在一边狂吃吃饱了就拿着拍立得喀嚓喀嚓的到处乱拍","paragraph":37,"style":"plain","start":1005.7,"end":1010.72},{"text":"还在无意间拍了一张合照丑的我不忍直视那阵子不是全国都有台风吗总是下雨嘛去的时候还是晴","paragraph":38,"style":"plain","start":1011.18,"end":1020.68},{"text":"天画到一半就开始乌云密布狂风大作幸好我那个包防水不然忙活半天都白画了但我俩不防水猝不","paragraph":38,"style":"plain","start":1020.68,"end":1032.01},{"text":"及防的就被浇成了落汤鸡学姐的脸上黏着发丝水珠也顺着脖子没入了已经湿透的衣服里我就非礼","paragraph":38,"style":"plain","start":1032.305,"end":1042.6},{"text":"勿视非礼勿视假装四处看着风景这场雨来得快去得也快","paragraph":38,"style":"plain","start":1042.713,"end":1048.14},{"text":"没一会儿太阳就出来了画画是不能继续了反正已经湿透了嘛我俩就索性跑到海里发疯一圈折腾下","paragraph":39,"style":"plain","start":1048.86,"end":1057.78},{"text":"来就到了傍晚我们玩累了坐在沙滩上休息天边是无数次两人一起看过的落日我看着她染红的侧脸","paragraph":39,"style":"plain","start":1057.78,"end":1068.2},{"text":"欲言又止最后只说了句回家吗她站起来拍了拍屁股上的沙子嗯 回家","paragraph":39,"style":"plain","start":1068.44,"end":1076.52},{"text":"晚上的时候，我久违的熬了个夜，继续白天没有画完的画作，","paragraph":40,"style":"plain","start":1077.74,"end":1082.4},{"text":"因为我想在学姐离开的时候送给她，但失去了参照物，我只能凭着记忆去努力还原，","paragraph":40,"style":"plain","start":1083.08,"end":1090.04},{"text":"而我记得的也只有落日和海边的姑娘。","paragraph":40,"style":"plain","start":1090.72,"end":1094.46},{"text":"因为很久没有熬夜了嘛，所以第二天我睡过了。","paragraph":41,"style":"plain","start":1095.56,"end":1099.52},{"text":"醒来的时候发现学姐已经走了。","paragraph":41,"style":"plain","start":1100.0,"end":1102.16},{"text":"我看了眼时间，应该还来得及。","paragraph":41,"style":"plain","start":1103.14,"end":1105.28},{"text":"于是就着急忙慌的装好画赶往车站。","paragraph":41,"style":"plain","start":1106.12,"end":1108.76},{"text":"在路上发微信让她等我一下。","paragraph":41,"style":"plain","start":1109.98,"end":1111.94},{"text":"学姐那边说着不着急。","paragraph":42,"style":"plain","start":1112.9,"end":1114.16},{"text":"但等我见到她的时候，检票时间就剩五分钟了。","paragraph":42,"style":"plain","start":1114.96,"end":1118.42},{"text":"也来不及多说什么，我就直接把画筒塞给了她。","paragraph":42,"style":"plain","start":1119.38,"end":1122.56},{"text":"虽然开学后还能再见，但我望着检票口，它逐渐消失的身影还是有点失落。","paragraph":43,"style":"plain","start":1124.98,"end":1131.18},{"text":"回到了有些安静的家里，我居然有一点不太适应。","paragraph":43,"style":"plain","start":1132.14,"end":1136.17},{"text":"短短两个月的时间，就好像无限拉长一般，感觉过了很久。","paragraph":43,"style":"plain","start":1136.76,"end":1141.74},{"text":"我打开学姐的微信，看着聊天框，也不知道该说些什么。","paragraph":44,"style":"plain","start":1142.88,"end":1147.1},{"text":"但这时，她那边却发了消息，是一张画，上面画着一个女生日落时分坐在海边的样子。","paragraph":44,"style":"plain","start":1147.86,"end":1155.44},{"text":"我刚想回点什么，她那边又发过了一张照片，紧接着还有一句话，是我最想听到的那五个字。","paragraph":44,"style":"plain","start":1156.08,"end":1164.72},{"text":"我知道她发现了我的私心，点开了那张照片，那是我在画中很角落的地方写下了一段寄语，","paragraph":45,"style":"plain","start":1165.92,"end":1174.18},{"text":"送给我最喜欢的人。","paragraph":45,"style":"plain","start":1174.54,"end":1176.34},{"text":"怎么了迷湖宝宝还不睡觉啊已经很晚了给你讲个睡前故事就乖乖的睡好不好那你闭上眼睛小熊抱","paragraph":46,"style":"plain","start":1180.12,"end":1195.56},{"text":"好了","paragraph":46,"style":"plain","start":1195.56,"end":1196.0},{"text":"今天想一个小熊骑士的故事每一个小熊都是一个骑士她会在你睡着的时候，","paragraph":47,"style":"plain","start":1198.14,"end":1208.2},{"text":"打跑捣乱的恶龙偷偷告诉你，我也是你的骑士。","paragraph":47,"style":"plain","start":1208.9,"end":1214.0},{"text":"所以晚安，迷湖宝宝，做个好梦，记得准时哦！","paragraph":47,"style":"plain","start":1215.16,"end":1220.46}]},{"id":"triangle-drama","title":"三角狗血","category":"story","sequence":6,"duration":787.461224,"audio":"triangle-drama.mp3","palette":["#485f52","#726451"],"cues":[{"text":"故事故事要从我原来的初中开始说起。","paragraph":0,"style":"plain","start":2.98,"end":5.14},{"text":"我因为成绩很好，所以初二时，就被确认保送到了现在的高中。","paragraph":0,"style":"plain","start":5.98,"end":11.16},{"text":"一同来的还有我初中的好兄弟，老王。","paragraph":0,"style":"plain","start":12.06,"end":15.24},{"text":"他学习被我差点，在三等班，而小小，就是他当时的同桌。","paragraph":0,"style":"plain","start":16.38,"end":21.58},{"text":"出于人类社交的本能嘛，上了新学校也没啥朋友。","paragraph":1,"style":"plain","start":22.96,"end":26.44},{"text":"于是我和老王还有原来的几个同学就经常在一起打球聊天啥的青春期的男生凑在一起那话题自然","paragraph":1,"style":"plain","start":27.1,"end":36.2},{"text":"也少不了班级里好看的女生老王就整天说他那个同桌怎么样怎么样每次都跟我们汇报他追求的进","paragraph":1,"style":"plain","start":36.2,"end":44.46},{"text":"度所以老话说的好啊财不露白 富不露相他整天没完没了的说他自然会有人好奇 也有人嫉妒","paragraph":1,"style":"plain","start":44.46,"end":53.96},{"text":"我当时是属于好奇的那个却想看看这个女生到底长啥样然后时间就来到分班考试的前期我们几个","paragraph":2,"style":"plain","start":54.7,"end":64.7},{"text":"聚餐的时候老王带来一个女生介绍说这就是小小然后隆重地宣布俩人正式的在一起了那是我第一","paragraph":2,"style":"plain","start":64.7,"end":75.18},{"text":"次见到小小本人之前一直听老王说她多好看多漂亮现在一看那确实是其实他也不是漂不漂亮的问","paragraph":2,"style":"plain","start":75.18,"end":85.67},{"text":"题他嘴边叼着一根棒棒糖戴着圆圆的眼镜白白瘦瘦的","paragraph":2,"style":"plain","start":85.67,"end":91.36},{"text":"穿着宽大的校服就是那种很有初恋感的长相小小的性格比较内敛跟我们几个也说不上几句话我看","paragraph":3,"style":"plain","start":92.0,"end":102.96},{"text":"他的时候正巧他还在看我四目相对的一瞬间两人又同时移开了视线我的好奇也迅速变成了嫉妒但","paragraph":3,"style":"plain","start":102.96,"end":113.28},{"text":"也没什么别的想法就觉得这姑娘是不是有点眼瞎到底是怎么看上老王的总之呢我还是很为朋友感","paragraph":3,"style":"plain","start":113.28,"end":123.08},{"text":"到高兴的后来我还送了老王两盒酸奶算是恭喜","paragraph":3,"style":"plain","start":123.08,"end":127.26},{"text":"其实没过几天就到了分班考试我仗着初中的学习好天天上课睡大觉成绩考得很差但因为我又是保","paragraph":4,"style":"plain","start":128.6,"end":138.38},{"text":"送嘛所以也没有给我降到三等班去而小小那边学习一直很努力就从三等班升到了二等班也就变成","paragraph":4,"style":"plain","start":138.38,"end":147.58},{"text":"了我的同班同学不过因为她比较内向我也有着避嫌的想法所以我俩也从来没有主动说过什么话最","paragraph":4,"style":"plain","start":147.58,"end":157.62},{"text":"多就是充当一下老王的传话筒或者给她带个东西什么的","paragraph":4,"style":"plain","start":157.62,"end":162.14},{"text":"我那时候真没什么特殊的想法就是觉得她有涵养很努力仅此而已，","paragraph":5,"style":"plain","start":162.78,"end":168.9},{"text":"也甚至朋友妻不可欺的道理转折点发生在有天打球的时候老王不小心受伤了说是手腕扭到了学校","paragraph":5,"style":"plain","start":169.42,"end":179.94},{"text":"的医务室也处理不了需要去医院看一下老王就想让小小陪他但那时候还正在上课小小不想撒谎也","paragraph":5,"style":"plain","start":179.94,"end":189.62},{"text":"没什么正当的理由总不能跟老师请假说要陪男朋友去看病吧","paragraph":5,"style":"plain","start":189.62,"end":194.34},{"text":"但老王那边就执意要求小小陪她甚至因自残的方式威胁小小没有办法只好硬着头皮跟班主任撒谎","paragraph":6,"style":"plain","start":195.32,"end":204.68},{"text":"请了假自从那以后他们之间就经常发生矛盾后来没过多久就分手了他们的关系差不多持续了有小","paragraph":6,"style":"plain","start":204.68,"end":214.72},{"text":"半年的时间后来小小跟我说老王的占有欲太强了总是要求他做这做那的而小小呢也是一个很犟的","paragraph":6,"style":"plain","start":214.72,"end":224.51},{"text":"人所以这半年两人也没少闹矛盾","paragraph":6,"style":"plain","start":224.51,"end":227.72},{"text":"分手的时候我们几个隔着老远在那围观小小的话说得很绝说她已经不喜欢老王了本来就不多的好","paragraph":7,"style":"plain","start":228.58,"end":237.8},{"text":"感早在这段时间中消耗殆尽高一差不多就这样结束了我和小小之间还是一直没有联系因为有老王","paragraph":7,"style":"plain","start":237.8,"end":248.46},{"text":"这层关系我们两人都觉得有些尴尬吧所以在班里也从不讲话有天是有过生日我们就一帮人出去聚","paragraph":7,"style":"plain","start":248.46,"end":257.4},{"text":"餐喝了点小酒然后就开始玩那个真心话大冒险","paragraph":7,"style":"plain","start":257.5,"end":261.88},{"text":"因为大冒险要给班级里的女生打电话我就选了真心话","paragraph":8,"style":"plain","start":262.76,"end":267.12},{"text":"问题也非常老套就是我觉得班里哪个女生最好看我想了一圈有说不上谁她们不耐烦地催我必须说","paragraph":9,"style":"plain","start":269.32,"end":277.92},{"text":"一个我在脑子里检索了一遍最后也只剩下了一个小小","paragraph":9,"style":"plain","start":277.92,"end":282.98},{"text":"一群人就跟那儿起哄说我对人家有意思然后下一个输了的傻逼还给小小的闺蜜打了电话顺嘴就把","paragraph":10,"style":"plain","start":285.52,"end":295.88},{"text":"我给卖了出去电话里具体说的啥我不知道反正小小那边肯定听到了然后没一会儿小小那边就发来","paragraph":10,"style":"plain","start":295.88,"end":305.39},{"text":"了好友申请我就跟她解释说在玩酒桌游戏他问我你选择大冒险吗？","paragraph":10,"style":"plain","start":305.39,"end":311.76},{"text":"我半天没吱声，然后回复到我选择真心话。","paragraph":11,"style":"plain","start":312.42,"end":316.22},{"text":"反正就这样，我俩开始了有一搭没一搭地聊得起来，可能是酒精的作用。","paragraph":11,"style":"plain","start":317.36,"end":322.62},{"text":"再加上刚才那句真心话，我们之间的氛围就变得有些微妙。","paragraph":11,"style":"plain","start":323.38,"end":328.0},{"text":"我那时候还在心里暗示自己，说这就是客观的欣赏，以及正常朋友的闲聊，","paragraph":12,"style":"plain","start":328.84,"end":334.86},{"text":"没有什么特殊的含义。","paragraph":12,"style":"plain","start":335.66,"end":336.88},{"text":"这样不远不近的关系持续了一阵子直到有一天我骑车回家的时候腿受伤了当时伤得还挺严重的在","paragraph":12,"style":"plain","start":338.18,"end":346.96},{"text":"医院里躺了几天没想到请假的当天晚上小小那边就在QQ上问候我知道我受伤没办法上学那几天","paragraph":12,"style":"plain","start":346.96,"end":357.76},{"text":"他都会把上课的内容整理成笔记发给我","paragraph":12,"style":"plain","start":357.76,"end":360.9},{"text":"然后分享学校的事情陪我聊天关切地问我恢复的怎么样甚至我也不知道他从哪儿打听到的地址还","paragraph":13,"style":"plain","start":361.68,"end":370.08},{"text":"和几个同学一起在家里看我然后就诞生了我能记一辈子的名场面那天他来 老王正好也在虽然还","paragraph":13,"style":"plain","start":370.08,"end":379.98},{"text":"有其他几个人随从但老王看到小小的时候脸一下就绿了他们说是老师让他们来送课堂笔记的然后","paragraph":13,"style":"plain","start":379.98,"end":389.58},{"text":"那几个同学不知道他俩之间的关系","paragraph":13,"style":"plain","start":389.58,"end":391.86},{"text":"就起哄补充到小小是主动自愿的我瞥了一眼，老王的脸色更难看了。","paragraph":14,"style":"plain","start":391.86,"end":399.68},{"text":"我连忙支吾说，嗨，他，嗯，他是学习委员嘛，正常。","paragraph":14,"style":"plain","start":400.18,"end":405.76},{"text":"气氛开始变得诡异起来，要不是我当时腿脚不方便，高低得用脚趾，抠出一个迪士尼城堡。","paragraph":14,"style":"plain","start":406.88,"end":413.52},{"text":"小小他们送完笔记，没一会就走了，老王又呆了一会，一副欲言又止的样子，","paragraph":15,"style":"plain","start":415.02,"end":420.5},{"text":"但最后还是什么都没说。","paragraph":15,"style":"plain","start":421.04,"end":422.82},{"text":"那段时间因为老王 我总是躲着小小但找老王 他又躲着我 想跟他解释都找不到人说实话 我","paragraph":15,"style":"plain","start":424.16,"end":433.26},{"text":"夹在中间真的很难受这明明我啥也没干 可搞得好像我做错了也所以伤好了以后 我又出去旅游","paragraph":15,"style":"plain","start":433.32,"end":442.76},{"text":"了两天","paragraph":15,"style":"plain","start":442.76,"end":443.44},{"text":"看着祖国的大好山河 深感情情爱爱的破事儿不值一提再加上我对警察、","paragraph":16,"style":"plain","start":443.86,"end":451.62},{"text":"军人这些职业从小就非常向往所以下决心以后一定要上警校老王这边没联系了小小那边我也不说","paragraph":16,"style":"plain","start":451.94,"end":461.88},{"text":"话要说对人家一点好感都没有吧那肯定不是","paragraph":16,"style":"plain","start":461.88,"end":465.6},{"text":"但这剪不断理还乱的关系我只要一想到就有一个头两个大所以刚从两边都离远点","paragraph":17,"style":"plain","start":467.66,"end":474.94},{"text":"然后还记得那个给小小闺蜜打电话的室友吧他俩拉扯了一个学期下半年终于混到一起了又因为他","paragraph":18,"style":"plain","start":479.96,"end":489.26},{"text":"俩的关系我们两个宿舍的人就总在一起玩我因为躲着小小就很不合群同行的哥们就劝道说你一没","paragraph":18,"style":"plain","start":489.26,"end":499.48},{"text":"偷二没抢三没挖墙脚你愧疚矫情个什么劲再说他还分手了对吧我一想也是 想着那就顺其自然吧","paragraph":18,"style":"plain","start":499.48,"end":510.48},{"text":"所以两伙人下次聚餐的时候 我也跟去了","paragraph":18,"style":"plain","start":510.96,"end":514.24},{"text":"小小看了我还挺惊讶的 但好像有点生气了后来唱歌的时候 我为了道歉就凑到他旁边塞给他一","paragraph":19,"style":"plain","start":515.18,"end":524.22},{"text":"个东西那是我旅游的时候买的纪念品手链后来我才发现这东西哪个景区都有但是小小却一直带着","paragraph":19,"style":"plain","start":524.22,"end":533.42},{"text":"他也不看着我，","paragraph":19,"style":"plain","start":534.6,"end":535.74},{"text":"就气鼓鼓地说怎么不躲着我了？","paragraph":19,"style":"plain","start":535.94,"end":538.56},{"text":"我有点尴尬的回答什么呀？","paragraph":20,"style":"plain","start":539.24,"end":541.56},{"text":"我躲你了吗？","paragraph":20,"style":"plain","start":541.88,"end":543.56},{"text":"小小玩着手机半天没说话然后从包里拿着一副拼图说是原本恭喜我腿伤康复的但是一直没机会送","paragraph":20,"style":"plain","start":544.7,"end":553.44},{"text":"我就这样我俩算是又恢复的联系下班级里的接触也越来越多关系也越来越微妙我中午不爱吃饭他","paragraph":20,"style":"plain","start":553.44,"end":566.52},{"text":"就会在我的抽屉里偷偷塞了牛奶和零食然后他学习已经比我好了我有啥不会的他也会耐心的教我","paragraph":20,"style":"plain","start":566.52,"end":575.04},{"text":"我和小小虽然暧昧可两人都没有表示过什么就这样一直拖拖拉拉到了高三因为小小户籍的缘故高","paragraph":21,"style":"plain","start":575.74,"end":585.12},{"text":"考他要回老家那边我那时候犹犹豫豫的可能还是因为小小是是兄弟的前女友吧所以最后也没有说","paragraph":21,"style":"plain","start":585.12,"end":593.84},{"text":"回来就我喜欢你临走的时候小小把她那个校服外套送给我了就是我第一次见到她她穿的那件上面","paragraph":21,"style":"plain","start":593.84,"end":603.46},{"text":"还残留着她独特的香味她有些要用的笔记","paragraph":21,"style":"plain","start":603.46,"end":607.4},{"text":"我也一同要了过来算是一种留念因为上了大学我真不知道还能不能见到她高考我发挥得还可以结","paragraph":22,"style":"plain","start":607.4,"end":618.02},{"text":"束后走了提前批然后出发没几天就去做了体测和政审面试好在我也都顺利通过了我第一时间就把","paragraph":22,"style":"plain","start":618.02,"end":628.12},{"text":"这个喜讯告诉了小小她以为我感到高兴但却因为填报志愿和父母闹了矛盾那一整个暑假都留在她","paragraph":22,"style":"plain","start":628.12,"end":636.88},{"text":"妈工作的城市没有回了","paragraph":22,"style":"plain","start":636.88,"end":639.46},{"text":"我俩还没感受到爱情的甜就先吃到了异地的苦每天就整得在手机上聊天临近开学的时候 我终于","paragraph":23,"style":"plain","start":639.82,"end":648.76},{"text":"忍不住了正巧 他妈工作的是个沿海城市我当作旅游 脑袋一热就跑过去了小小来接着我 还在","paragraph":23,"style":"plain","start":648.76,"end":659.92},{"text":"我开的酒店陪我睡了一觉可是纯睡觉啊 不要乱想舟车劳顿的我有点累 我们就眯了几个小时到","paragraph":23,"style":"plain","start":659.92,"end":668.84},{"text":"了傍晚 他陪我去吃海鲜","paragraph":23,"style":"plain","start":668.84,"end":670.72},{"text":"我第一次知道还可以带着食材去饭店里吃加工费很便宜，","paragraph":24,"style":"plain","start":671.22,"end":675.92},{"text":"还能省下不少钱小小滔滔不绝地跟我说着他在这边的生活像个老炮儿的，","paragraph":24,"style":"plain","start":676.12,"end":682.92},{"text":"完全没有了以前那样子吃完饭，我们就去了海边我觉得东海和南海的区别在于前者适合看，","paragraph":24,"style":"plain","start":683.06,"end":692.02},{"text":"后者适合玩所以我们就光着脚在沙滩上散步晚上海边出来的风会带着一些咸湿味","paragraph":24,"style":"plain","start":692.38,"end":701.2},{"text":"以及挂在海平面上的月亮都是我未曾见过的包括现在这个活泼热情的小小她说在没人认识的城市","paragraph":25,"style":"plain","start":701.92,"end":710.78},{"text":"里就好像换了一个身份可以肆无忌惮地表达自己我说我还在呢她笑着说你不一样我当然明白她的","paragraph":25,"style":"plain","start":710.78,"end":720.84},{"text":"意思看着这个陌生的城市以及眼前熟悉的人就像过去高中三年一样我们也该重新开始新的篇章了","paragraph":25,"style":"plain","start":720.84,"end":730.18},{"text":"于是我牵起了小小的手，终于说出了那句埋藏在心里的话，我们确认了关系，","paragraph":26,"style":"plain","start":730.86,"end":737.26},{"text":"但没两天我就要回家，然后一想到开学又要异地，心里就更加难过。","paragraph":26,"style":"plain","start":738.14,"end":744.82},{"text":"然后就在我去大学报到的当天，小小就发了一条消息，让我在车站别走，然后没过多久，","paragraph":26,"style":"plain","start":745.68,"end":753.5},{"text":"我就看到远处跑到一个熟悉的身影。","paragraph":26,"style":"plain","start":754.02,"end":756.94},{"text":"我一脸惊讶地看着她她笑嘻嘻地解释说填报志愿的时候她偷偷瞒着父母改成我在的城市我激动 ","paragraph":27,"style":"plain","start":758.08,"end":768.3},{"text":"开心 幸福万分但就在这个时候我的余光又扫到一个熟悉的身影那时染了一头黄毛正在看着我们","paragraph":27,"style":"plain","start":769.06,"end":779.467},{"text":"的老王","paragraph":27,"style":"plain","start":779.467,"end":780.16},{"text":"故事讲完了小迷湖公主 做个好梦","paragraph":28,"style":"plain","start":782.64,"end":785.46}]},{"id":"want-and-get","title":"想要 得到","category":"story","sequence":7,"duration":1524.244898,"audio":"want-and-get.mp3","palette":["#516153","#6d5f54"],"cues":[{"text":"我是个很懒散的人。","paragraph":0,"style":"plain","start":1.58,"end":2.88},{"text":"自从小时候喊着友情啊，羁绊啊什么的，冲向几个人打架。","paragraph":0,"style":"plain","start":3.76,"end":8.6},{"text":"但就完全打不过。","paragraph":0,"style":"plain","start":9.28,"end":10.42},{"text":"我就深刻的明白了，客观事实是不会以主观意志发生改变的。","paragraph":0,"style":"plain","start":11.26,"end":16.36},{"text":"通俗点说，就是碰壁了，知道疼了。","paragraph":0,"style":"plain","start":16.78,"end":20.76},{"text":"高我一头的男生，我确实是打不过。","paragraph":1,"style":"plain","start":21.44,"end":23.88},{"text":"所以后来遇到什么事儿，我都会量力而行。","paragraph":1,"style":"plain","start":25.08,"end":27.9},{"text":"也不再觉得有什么东西值得自己拼的命也要去争取早早地就养成了躺平性格的我人生虽然没有什","paragraph":1,"style":"plain","start":28.56,"end":37.78},{"text":"么波澜壮阔但也算是平稳落地毕业后我没有像那些同学一样去大城市打拼直接就在三线老家开始","paragraph":1,"style":"plain","start":37.78,"end":47.3},{"text":"的躺平生活工作一般赚得也不多但在小城市没那么多消费","paragraph":1,"style":"plain","start":47.3,"end":53.76},{"text":"我的工资也能养活自己但工作了两三年，","paragraph":2,"style":"plain","start":54.32,"end":58.8},{"text":"感情上还是一平如洗高中的时候有个喜欢的女生但出于不打扰对方和不麻烦自己的原则整整暗恋","paragraph":2,"style":"plain","start":59.16,"end":68.6},{"text":"了人家三年后来大家都毕业了，","paragraph":2,"style":"plain","start":68.6,"end":71.56},{"text":"也没啥联系了大学时期也接触过一些女生但都没啥感觉，","paragraph":2,"style":"plain","start":71.7,"end":77.6},{"text":"也没发展下去的欲望所以就一直单身了我以为这种寡淡的生活会一直持续下去","paragraph":2,"style":"plain","start":77.9,"end":85.5},{"text":"没想到，却在夏天，开始的时候发生了转机","paragraph":3,"style":"plain","start":86.22,"end":91.02},{"text":"因为工作没啥盼头，我就搞了份副业本以为随便赚点外快，但效果出奇得不错后来干脆辞职，","paragraph":4,"style":"plain","start":94.26,"end":103.16},{"text":"就专心搞副业了楼下商场的咖啡书店，就成了我的办公地点暑假到了嘛，","paragraph":4,"style":"plain","start":103.4,"end":110.66},{"text":"店里就多了很多学生一堆堆人男男女的一待就是半天放在桌上的作业也不见动半天下来感情倒是","paragraph":4,"style":"plain","start":110.96,"end":121.26},{"text":"升温了不少然后有天店里来了一个气质特好的女生虽然戴着帽子看不见长相","paragraph":4,"style":"plain","start":121.26,"end":128.54},{"text":"但那个身材不对应该说身段绝了那些小男生哪见过这个她","paragraph":5,"style":"plain","start":129.06,"end":136.24},{"text":"对着身边的女朋友眼睛就一个劲地偷瞄我也在看还没等看出过所以然就听见一对小情侣吵架的声","paragraph":6,"style":"plain","start":139.58,"end":148.86},{"text":"音好像是发现男生偷瞄的眼神吃醋了两个人就吵着离开了书店其他女生似乎也感受到了危险的气","paragraph":6,"style":"plain","start":148.86,"end":158.38},{"text":"息也陆续拉着身边的男生走了那女生抬起了头 也在看戏","paragraph":6,"style":"plain","start":158.38,"end":164.2},{"text":"我收回目光的时候，正好和她帽子下的眼睛，四目相对虽然样子变得不少，","paragraph":7,"style":"plain","start":167.18,"end":173.96},{"text":"但我还是一眼就认出了，她是我那高中的小同桌两人都有些吃惊的看着对方，","paragraph":7,"style":"plain","start":174.56,"end":181.16},{"text":"我疑惑的指了指她表示肯定点了点头，然后就起身，向我走了过来","paragraph":7,"style":"plain","start":181.76,"end":187.56},{"text":"我心里有种过去和现在割裂的感觉仿佛大学前后的自己不是同一个人所以面对她的时候我一时之","paragraph":8,"style":"plain","start":190.24,"end":200.02},{"text":"间也不知道该说什么她倒是很热情直接坐在了我的对面还一下就叫出了我的名字多年没见吧两个","paragraph":8,"style":"plain","start":200.02,"end":210.8},{"text":"人自然而然的就了解了各自的变化她性格还是那样一整个热情开朗的样子同桌的时候就整天拉着","paragraph":8,"style":"plain","start":210.8,"end":220.86},{"text":"我家长里短的吃瓜干啥都要凑个热闹","paragraph":8,"style":"plain","start":220.86,"end":224.26},{"text":"所以那时候我就整天叫她瓜姐瓜姐外观上倒是变得不少尤其是身材上我记得当时她穿了一双小凉","paragraph":9,"style":"plain","start":224.88,"end":235.02},{"text":"鞋搭配一条比较能显身材的连衣裙披一个小外套凑近了感受就更明显了要不是同桌了那么久估计","paragraph":9,"style":"plain","start":235.02,"end":245.28},{"text":"我也认不出来不过细想也对那时候整天穿着宽大的校服能看出什么就有鬼了我有点好奇她怎么在","paragraph":9,"style":"plain","start":245.28,"end":255.62},{"text":"老家这边因为之前在同学群里有人说她在外地工作","paragraph":9,"style":"plain","start":255.62,"end":260.42},{"text":"她说是工作烦了就回来散散心我也说了一下自己的境况瓜姐听了撇了撇嘴吐槽我还是一副性冷淡","paragraph":10,"style":"plain","start":261.66,"end":271.1},{"text":"的样子然后不由分说的跟我讲了半天其他同学都传闻傻的我不是一个很喜欢八卦的人对别人的生","paragraph":10,"style":"plain","start":271.1,"end":280.31},{"text":"活也不是很感兴趣但看她那副样子好像回到了高中同桌的时候也就耐着性子听着她说","paragraph":10,"style":"plain","start":280.31,"end":288.44},{"text":"聊到下午快傍晚的时候我打算在商场里吃了个饭她说了半天别人的事自己的一点没漏我就问了一","paragraph":11,"style":"plain","start":290.98,"end":299.9},{"text":"嘴她有些害羞地说上班给领导打了气的工作丢了大夏天的一懒的在找就跑回老家避暑来了说完眼","paragraph":11,"style":"plain","start":300.196,"end":311.18},{"text":"睛一转在对面俯下身子问我你现在工作挺自由的吧她那衣服的领口本来就不高身子一低就更明显","paragraph":11,"style":"plain","start":311.18,"end":320.74},{"text":"了我知道她这话是什么意思但实际上现在反而更忙了","paragraph":11,"style":"plain","start":320.74,"end":326.14},{"text":"所有的工作都需要自己一个人完成所以瞄了最后一眼，递上手机上的二维码说嗯，更忙了，","paragraph":12,"style":"plain","start":326.54,"end":334.84},{"text":"事也更多了她拿着手机加了微信，也自然坐直了身体然后笑嘻嘻地说时间嘛，挤一挤，","paragraph":12,"style":"plain","start":334.84,"end":344.39},{"text":"总会有的在那之后，我们就在微信上有一句没一句的闲聊瓜姐高中毕业后，","paragraph":12,"style":"plain","start":344.6,"end":352.06},{"text":"一直在外地上学和工作小城虽然不大，但也有些变化她这阵子就到处闲逛","paragraph":12,"style":"plain","start":352.5,"end":359.34},{"text":"看到什么新东西都会分享给我就这样差不多过了一周吧有天早上她有些兴奋地说找到一家很好吃","paragraph":13,"style":"plain","start":360.14,"end":369.66},{"text":"的店问我去不去我躺在床上看着她的微信犹豫了半天还是让她发来了定位然后到了地方才发现那","paragraph":13,"style":"plain","start":369.66,"end":380.12},{"text":"家店是原来学校门口的小吃开的卖的东西很杂烤的，","paragraph":13,"style":"plain","start":380.12,"end":385.44},{"text":"拌的，卤的，啥都有比较有特色就是大家需要自烤的小土豆当时我们放学了都会围在烤炉面前","paragraph":13,"style":"plain","start":385.68,"end":395.74},{"text":"吃几串小土豆再回家但也不知道是长大了还是她家里变味了反正感觉和原来的味道差了不少她倒","paragraph":14,"style":"plain","start":395.74,"end":405.7},{"text":"是吃得津津有味小脸都被炉子烤得通红我就吐槽大说大夏天的出来吃这个你也不怕中暑瓜姐一串","paragraph":14,"style":"plain","start":405.7,"end":416.64},{"text":"接一串的路边吃边说你知道什么叫年少吃不饱之物终将困其一生吗我被她逗乐了这小嘴儿真是一","paragraph":14,"style":"plain","start":416.64,"end":426.34},{"text":"套一套的不过也确实上学的时候钱不多也吃不到尽兴","paragraph":14,"style":"plain","start":426.34,"end":432.14},{"text":"可能长大了吧也没那么喜欢吃了吃完饭她又要我陪着逛逛说很多东西都没拿回来要买点夏天穿的","paragraph":15,"style":"plain","start":432.82,"end":442.38},{"text":"衣服我以为她工作那边都了结了才回来的没想到房子还在租着她说公司那边是结束了但是有很多","paragraph":15,"style":"plain","start":442.38,"end":451.9},{"text":"客户之类的还有后续的内容需要跟进另外积累的人脉都在那边她就是在老家休息休息总归还是要","paragraph":15,"style":"plain","start":451.9,"end":462.16},{"text":"回去了","paragraph":15,"style":"plain","start":462.16,"end":462.64},{"text":"我有点好奇她到底是做什么的她说你看姐这口才你觉得呢我回答，难道是精通人性的女讲师啊？","paragraph":16,"style":"plain","start":465.1,"end":474.86},{"text":"她翻了个白眼说，我是干市场的。","paragraph":16,"style":"plain","start":475.48,"end":478.3},{"text":"我做出一副恍然大悟的样子，哦，销售呗。","paragraph":16,"style":"plain","start":479.16,"end":482.64},{"text":"她懒得继续跟我贫嘴，转移到情感话题上。","paragraph":17,"style":"plain","start":483.72,"end":486.78},{"text":"带着戏谑的语气说，你知道咱们那个学习委员结婚了吗？","paragraph":17,"style":"plain","start":487.54,"end":491.5},{"text":"学习委员，就是当初我暗恋的女生。","paragraph":17,"style":"plain","start":493.18,"end":495.86},{"text":"瓜姐跟我同桌了两三年我那边小心思自然都被她猜了个七七八八她以为说这个事能刺痛到我但其","paragraph":17,"style":"plain","start":496.68,"end":505.96},{"text":"实我老早就知道了甚至当时听到的时候也没有太多感觉很多事情长大再看其实就不会有太多触动","paragraph":17,"style":"plain","start":505.96,"end":514.42},{"text":"了","paragraph":17,"style":"plain","start":514.42,"end":514.62},{"text":"好像那是上辈子的事一样那个商场距离的不远不近刚吃完饭我们就没坐车一路上散步过去了路上","paragraph":18,"style":"plain","start":515.58,"end":526.18},{"text":"的太阳晒得吓人地面上都弥漫着一股扭曲的热气她的小背心已经被汗湿了一大片外套也系在了腰","paragraph":18,"style":"plain","start":526.18,"end":535.8},{"text":"上但还是一副精力充沛的样子现刚才的话题没有效果她就凑过了好奇的问你就放下了 有喜欢的","paragraph":18,"style":"plain","start":535.8,"end":545.61},{"text":"人呢我都要晒冒烟了准备好记得回答我要是有喜欢的人","paragraph":18,"style":"plain","start":545.61,"end":551.72},{"text":"还大热天地陪你出来逛啊她装作一副委屈巴巴般的样子说懂了，","paragraph":19,"style":"plain","start":551.72,"end":557.98},{"text":"我是你池塘里的鱼说完好像想到了什么？","paragraph":19,"style":"plain","start":557.98,"end":561.64},{"text":"眼睛一亮，紧接着又问哎，你想不想去水上乐园我看了眼头上的太阳想了一下这天气玩玩水，","paragraph":19,"style":"plain","start":562.2,"end":572.1},{"text":"好像是挺舒服的就不自觉的点了点头看见我答应，她可开心了喜笑颜开着我，","paragraph":19,"style":"plain","start":572.44,"end":580.6},{"text":"就往上场跑这下又出了一身汗进了商场才感觉整个人活了过来","paragraph":19,"style":"plain","start":580.9,"end":587.4},{"text":"就好像晒干的咸鱼终于遇到水一样我说空调是人类最伟大的发明应该没人会反对吧瓜姐倒是绝对","paragraph":20,"style":"plain","start":587.92,"end":598.0},{"text":"有点冷还穿上她现在腰上的小外套然后我一个女朋友都没有正经谈过的直男根本就不懂女生的穿","paragraph":20,"style":"plain","start":598.0,"end":606.3},{"text":"搭嘛反正就只能跟着她乱过不过她也不需要我出意见，","paragraph":20,"style":"plain","start":606.3,"end":611.7},{"text":"就按照自己的喜好挑，甚至还给我买了条泳裤，说是陪她逛街赏的。","paragraph":20,"style":"plain","start":611.98,"end":618.28},{"text":"正好去水上乐园可以穿，我就没拒绝，也不用回家翻箱倒柜地找了，但还是把钱A给了她。","paragraph":21,"style":"plain","start":619.0,"end":627.12},{"text":"去水上乐园的事儿，我们约在了第二天，她挑衣服花了不少时间，又在商场里光着光那的，","paragraph":21,"style":"plain","start":627.98,"end":635.36},{"text":"这一天就这么过去了。","paragraph":21,"style":"plain","start":635.84,"end":637.38},{"text":"我原本规律和平淡的生活有些被打乱晚上的时候就一直在赶白天留下的进度她那边还在手机上没","paragraph":22,"style":"plain","start":638.4,"end":646.88},{"text":"完没了的给我发着白天拍的黑照我又没忍住跟她互怼起来我的工作也没赶成多少第二天我们就约","paragraph":22,"style":"plain","start":646.88,"end":656.56},{"text":"在水上乐园界面但我在门口等到了中午都没见到瓜姐的声音微信上也没个动静我有点奇怪 有点","paragraph":22,"style":"plain","start":656.56,"end":666.52},{"text":"生气就一个人生活惯了嘛对别人的耐心不是很多","paragraph":22,"style":"plain","start":666.52,"end":670.88},{"text":"所以也懒得打字问就直接一个电话呼了过去第一遍没通第二遍过了好一会儿才有人接我刚想发作","paragraph":23,"style":"plain","start":671.58,"end":680.56},{"text":"说点什么去听她那边刚醒有点虚弱的声音在跟我道歉说对不起 对不起自己睡过了 没看时间我","paragraph":23,"style":"plain","start":680.56,"end":691.54},{"text":"听她好像身体不是很舒服所以还是压下了心里的情绪问她怎么了她说不知道就是感觉很热很困身","paragraph":23,"style":"plain","start":691.54,"end":701.44},{"text":"体很重估计是去不了水上的缘了","paragraph":23,"style":"plain","start":701.44,"end":704.64},{"text":"我心想还真让我给说着了昨天那么热的天对着小烤炉烤了那么久接着又在太阳下面爆晒进了商场","paragraph":24,"style":"plain","start":705.26,"end":714.94},{"text":"空调温度那么低这一准是众属外加热感冒了我说你先休息吧水上了源，","paragraph":24,"style":"plain","start":714.94,"end":722.6},{"text":"以后再去，不着急，夏天还有好久呢听得出来它是真难受，","paragraph":24,"style":"plain","start":722.78,"end":728.84},{"text":"完全没得前两天的样子诺基基的硬了一声，就躺下休息了我呢，只能掉掉的收拾东西回家","paragraph":24,"style":"plain","start":729.28,"end":736.88},{"text":"继续在书店完成原本堆在明天的工作","paragraph":25,"style":"plain","start":737.5,"end":740.8},{"text":"忙得半晚的时候，瓜姐那边发消息说行了然后又发了一张挂针的手不特写我问她，","paragraph":26,"style":"plain","start":743.38,"end":750.41},{"text":"你在哪个医院？","paragraph":26,"style":"plain","start":750.68,"end":751.5},{"text":"她又反问我说，要来看我吗？","paragraph":26,"style":"plain","start":752.13,"end":754.72},{"text":"这么关心我？","paragraph":26,"style":"plain","start":755.26,"end":755.96},{"text":"我说，你这是应该没事的，那我就不去了。","paragraph":26,"style":"plain","start":756.98,"end":759.66},{"text":"她联盟否认到，别呀，我这难受着呢。","paragraph":27,"style":"plain","start":761.0,"end":763.84},{"text":"你给我带个合乐呗。","paragraph":27,"style":"plain","start":764.4,"end":765.42},{"text":"听句话，她还是一个人去的。","paragraph":27,"style":"plain","start":766.58,"end":768.6},{"text":"不过也对。","paragraph":27,"style":"plain","start":769.24,"end":769.76},{"text":"这个时间，她爸妈还没下班呢。","paragraph":27,"style":"plain","start":770.56,"end":772.56},{"text":"看她一个人孤孤伶伶的，我就去了。","paragraph":27,"style":"plain","start":773.28,"end":775.64},{"text":"但是没给她带合乐。","paragraph":27,"style":"plain","start":776.24,"end":777.22},{"text":"瓜姐看我两手空空 只问我可乐呢？","paragraph":28,"style":"plain","start":778.32,"end":781.4},{"text":"可乐呢？","paragraph":28,"style":"plain","start":781.62,"end":782.08},{"text":"我说你喝不了 我给你接点热水吧她做出撒波的样子说不嘛 我就要喝可乐你给我买可乐 买可","paragraph":28,"style":"plain","start":782.82,"end":790.92},{"text":"乐我就问旁边打针的护士说伤风感冒啥的 能喝可乐吗人家说最好不要我说你看嘛 人家不让你","paragraph":28,"style":"plain","start":790.92,"end":802.06},{"text":"不好 再去我到水深的原是吧她撇着嘴不知声了旁边的护士倒是开笑了说但是心情好有利于病情","paragraph":28,"style":"plain","start":802.06,"end":812.46},{"text":"恢复","paragraph":28,"style":"plain","start":812.46,"end":812.82},{"text":"我摆了护士一眼您干嘛多这一句呢然后瓜姐那边又在可乐可乐地吵着着我没办法还是给她买了瓶","paragraph":29,"style":"plain","start":813.34,"end":822.64},{"text":"常温呢但她也没喝几口感冒的时候嘴里干涩其实喝可乐会更痛苦后来她就一直在喝热水了所以你","paragraph":29,"style":"plain","start":822.64,"end":833.12},{"text":"看感冒了多喝热水并不是一句废话快结束的时候瓜姐的爸妈下班来接她我有点尴尬她看样子也没","paragraph":29,"style":"plain","start":833.12,"end":843.54},{"text":"事了我就打了招呼开溜瓜姐在微信上调侃我说","paragraph":29,"style":"plain","start":843.54,"end":847.76},{"text":"怎么了 见父母紧张啊我说你真是病好了又能讨人嫌了她那边倒是认真的对我表达了一下感谢为","paragraph":30,"style":"plain","start":848.34,"end":858.68},{"text":"今天的放鸽子道了个歉说病好了，","paragraph":30,"style":"plain","start":858.68,"end":861.56},{"text":"也请我吃饭我以为瓜姐就是小感冒打一针就差不多了但到了晚上，","paragraph":30,"style":"plain","start":861.88,"end":868.2},{"text":"她又开始发烧所以那两天她都在吊针水上乐园虽然也就一直去不了我每天工作完就在她这里溜的","paragraph":30,"style":"plain","start":868.54,"end":878.26},{"text":"一圈给她端个茶倒个水沙的有天输液室的人不多","paragraph":30,"style":"plain","start":878.26,"end":883.28},{"text":"我给她换药的时候她突然来了句以前我就觉得你是个很可靠的男生我举着她的盐水愣了一下不知","paragraph":31,"style":"plain","start":883.28,"end":892.753},{"text":"道该怎么回就开玩笑的说你是真的病了连我都觉得好了","paragraph":31,"style":"plain","start":892.753,"end":898.44},{"text":"她倒是正面回应说我一直觉得你挺好的上学的时候就觉得这下我是真不知道该怎么回了也不懂她","paragraph":32,"style":"plain","start":901.16,"end":909.63},{"text":"是什么意思正巧她爸妈过来这差也就过去了但回家以后我脑子里却总是浮现她靠在椅子上吊针的","paragraph":32,"style":"plain","start":909.66,"end":919.62},{"text":"画面跟她以往不同就柔柔弱弱的带着点病态的美感最重要的是那张没完没了的嘴生病的时候也能","paragraph":32,"style":"plain","start":919.62,"end":931.38},{"text":"消停一点不知道你懂不懂就那种回忆一个人","paragraph":32,"style":"plain","start":931.38,"end":936.38},{"text":"想着想着笑出声的情况实际上她一点没变还是高中时的样子只不过那时候我看见的全是另外一个","paragraph":33,"style":"plain","start":936.78,"end":946.12},{"text":"女生我甩出脑子里这些七七八八的想法现在想这些没什么用而且我俩就不是一个世界的人她早晚","paragraph":33,"style":"plain","start":946.12,"end":956.0},{"text":"也要回到自己的生活经过一周的折磨瓜姐的感冒算是好的差不多了最后两天她就吵吵着要求水上","paragraph":33,"style":"plain","start":956.0,"end":965.4},{"text":"乐园我担心她没有彻底康复玩个水再复发了","paragraph":33,"style":"plain","start":965.767,"end":969.94},{"text":"所以就拖着没答应直到后来她整天跑到书店打扰我工作高中毕业的暑假我去过一次水上乐园不过","paragraph":34,"style":"plain","start":970.32,"end":980.16},{"text":"是跟死党一起去的虽然玩得很开心但两个男的都受了点遗憾吧就看着其他男生旁边身着泳衣的女","paragraph":34,"style":"plain","start":980.16,"end":990.4},{"text":"伴还是有点羡慕的或许是老天对我的补偿我知道瓜姐的身材不错但没想到能这么好她从更衣室出","paragraph":34,"style":"plain","start":990.4,"end":1000.32},{"text":"来外面一堆男生都在侧目","paragraph":34,"style":"plain","start":1000.32,"end":1002.54},{"text":"我走在她旁边发现来往的人事先都有一无一地看向这边甚至还有女生在看我实在有点受不了了就","paragraph":35,"style":"plain","start":1004.6,"end":1014.12},{"text":"让她穿上手里拿的那个半透明的防晒衣她明显也有点害羞但一边穿还一边调侃我说这么快就受不","paragraph":35,"style":"plain","start":1014.12,"end":1024.91},{"text":"了了我说你就拿这个考验干部然后没忍住又瞟了一眼不得不说啊白色是有点显胖我们第一个玩的","paragraph":35,"style":"plain","start":1024.91,"end":1036.59},{"text":"是那种比较温和的水滑梯差不多也就两三层楼的高度","paragraph":35,"style":"plain","start":1036.59,"end":1041.14},{"text":"都是一些小孩子在排队不过上面有个大桶一直在蓄水过段时间就会倾泻而下我俩吃了个满的从头","paragraph":36,"style":"plain","start":1041.68,"end":1051.34},{"text":"淋到脚一瞬间透心凉人都清醒了大夏天的确是没什么比 这更 消暑了她头发很长黏在脸上像个","paragraph":36,"style":"plain","start":1051.34,"end":1062.84},{"text":"贞子似的我就笑着帮她整理头发然后在睁开眼睛的时候正好跟我四目相对长长的睫毛上还带着水","paragraph":36,"style":"plain","start":1062.9,"end":1071.36},{"text":"珠脸上也带着红晕在阳光下似个晶莹剔透的水晶包","paragraph":36,"style":"plain","start":1071.36,"end":1076.66},{"text":"之后瓜姐也学乖了把头发扎了起来那水上乐园是个环状结构绕一圈正好可以把所有的项目都玩一","paragraph":37,"style":"plain","start":1077.52,"end":1086.8},{"text":"遍只不过排队的人有点多中间是个很大的泳池不同时段就会有官方搞的活动我们又玩了几个比较","paragraph":37,"style":"plain","start":1086.8,"end":1096.3},{"text":"温和的项目然后不想排队嘛就一直在原子里逛吃逛吃的躺在沙滩椅上吃刨冰的时候她问我高中毕","paragraph":37,"style":"plain","start":1096.3,"end":1106.28},{"text":"业那次集会来玩你怎么没到呢我正在想起来","paragraph":37,"style":"plain","start":1106.28,"end":1110.5},{"text":"当时我死党在水上乐园就是因为我打出门旅游了没赶上回了以后自己补的她知道以后说了一声可","paragraph":38,"style":"plain","start":1110.9,"end":1119.46},{"text":"惜我说可惜什么她吃完最后一口刨冰回答说可惜你没看到我当时的泳衣那她说这个我可就来劲了","paragraph":38,"style":"plain","start":1119.46,"end":1130.46},{"text":"又追问了一句同学聚会你还敢穿着花呢她狡黠一笑回答说猜起过你以前的事我不按计较但眼前的","paragraph":38,"style":"plain","start":1130.46,"end":1142.2},{"text":"东西可是货真价实的而且还是我一个人独享","paragraph":38,"style":"plain","start":1142.2,"end":1145.8},{"text":"所以就顺嘴说了句现在的也挺好看她听了以后就蹦蹦跶跶的跑去排队了我以为她胆子比较大但没","paragraph":39,"style":"plain","start":1146.6,"end":1157.26},{"text":"想到第一个稍微刺激的项目就吓得嗷嗷叫","paragraph":39,"style":"plain","start":1157.26,"end":1160.26},{"text":"那其实就是个双人版的激流勇进只不过坡道很陡有些瞬间我都感觉自己在飞然后中间有一段像冲","paragraph":40,"style":"plain","start":1162.56,"end":1171.64},{"text":"水马桶一样的漩涡区我俩好死不死地卡在了一个水流很小的地方瓜姐都快气哭了，","paragraph":40,"style":"plain","start":1171.64,"end":1179.32},{"text":"我有点急但看她这副样子又有点好笑那一刻我才理解什么叫吊桥效应就心跳加速，","paragraph":40,"style":"plain","start":1179.62,"end":1188.64},{"text":"真的会让人觉得身边那个人很特别我们就这样对视了快一分钟","paragraph":40,"style":"plain","start":1188.84,"end":1194.64},{"text":"最后想办法试着往水流中心靠才有惊无险地被马桶给冲走了上岸以后 我问她还玩吗她带着哭腔","paragraph":41,"style":"plain","start":1195.36,"end":1205.273},{"text":"说不玩了不玩了正好中间的大水池在搞活动我俩就去凑热闹具体就是那次泼水节一样的活动不过","paragraph":41,"style":"plain","start":1205.36,"end":1215.42},{"text":"是游客们拿着锅碗瓢盆对抗官方救火车一样的喷水枪看着水流很散但冲击力还挺大而且车里的水","paragraph":41,"style":"plain","start":1215.42,"end":1224.8},{"text":"特别凉游客们根本还不了手但好处就是","paragraph":41,"style":"plain","start":1224.8,"end":1229.0},{"text":"女生们都会尖叫着躲在男生的身后瓜姐倒是直接钻到我怀里我低头看了一眼就然后不知道是哪个","paragraph":42,"style":"plain","start":1229.0,"end":1239.32},{"text":"老哥跑去把水车的闸给拉了一众游客得到了反击的机会一人一瓢差点没把工作的小哥给淹死总之","paragraph":42,"style":"plain","start":1239.32,"end":1249.42},{"text":"一天下来玩得真的很开心那天的天气也特别好傍晚离开的时候还有日落和红霞换了衣服我开着老","paragraph":42,"style":"plain","start":1249.42,"end":1259.78},{"text":"爸的小破车送瓜姐回家水上乐园的位置很偏","paragraph":42,"style":"plain","start":1259.78,"end":1263.48},{"text":"这时候全是回家的路上就有点堵她玩了一天有点累就在后排睡觉我百无聊赖地的玩的手机然后突","paragraph":43,"style":"plain","start":1264.08,"end":1273.9},{"text":"发奇想的给死党发了个消息说我跟瓜姐去水上乐园了死党那边还没有反应过来是谁我说就我那高","paragraph":43,"style":"plain","start":1273.9,"end":1282.905},{"text":"中同桌她那边发了个啊好奇我俩是怎么勾搭到一起的我也懒得解释就说正好碰到的然后问她有没","paragraph":43,"style":"plain","start":1283.01,"end":1293.207},{"text":"有其他人去水上乐园的照片因为我还是有点好奇","paragraph":43,"style":"plain","start":1293.207,"end":1297.46},{"text":"死党吐槽那一句在水上乐园偶遇是吧然后说她没有但可以帮我问问接着没一会儿还真发来了照片","paragraph":44,"style":"plain","start":1298.28,"end":1307.44},{"text":"那是一张合照一个个面庞略带着青涩头上身上还都是湿的去的人挺多，","paragraph":44,"style":"plain","start":1307.44,"end":1315.0},{"text":"但我还是一眼，就找到了瓜姐的身影。","paragraph":44,"style":"plain","start":1315.38,"end":1318.26},{"text":"倒也不是她很亮眼，或者真穿了什么炸裂的泳衣，恰恰相反，","paragraph":45,"style":"plain","start":1319.1,"end":1323.98},{"text":"她穿的就是今天的那件白色连体衣。","paragraph":45,"style":"plain","start":1324.76,"end":1327.68},{"text":"我回头看了一眼还在睡觉的瓜姐，她整个人躺在座位上，头发还有点湿湿的，","paragraph":46,"style":"plain","start":1330.1,"end":1336.16},{"text":"像一只柔软的小猫。","paragraph":46,"style":"plain","start":1336.72,"end":1337.88},{"text":"这半个月的时间，我想起了很多以前的事，","paragraph":46,"style":"plain","start":1338.82,"end":1341.6},{"text":"但看到照片我才肯定自己好像真的错过了什么这时候瓜姐也醒了脑袋凑过来问我在干啥然后看到","paragraph":46,"style":"plain","start":1342.18,"end":1351.88},{"text":"手机上的照片笑骂到你小子哪儿搞来的没想到七八年前的泳衣我现在还能穿吧我说是你一点都没","paragraph":46,"style":"plain","start":1351.88,"end":1361.38},{"text":"变","paragraph":46,"style":"plain","start":1361.38,"end":1361.66},{"text":"不知道她听没听懂话里的意思只回了一句那是姐永远18岁后半程瓜姐就钻到前排来陪我落日的","paragraph":47,"style":"plain","start":1362.56,"end":1373.1},{"text":"余晖撒进车里正好穿过她微湿的头发音乐里裘海正唱着爱只是爱伟大的爱到头来也只是爱她就一","paragraph":47,"style":"plain","start":1373.233,"end":1384.44},{"text":"直在旁边跟着唱到了她家楼下天已经黑了一路上话也说尽了瓜姐就下车回家我没有着急走心情有","paragraph":47,"style":"plain","start":1384.44,"end":1396.2},{"text":"点复杂的躺在座上休息然后没一会儿她又回来了","paragraph":47,"style":"plain","start":1396.2,"end":1401.16},{"text":"在外面敲打着车窗我以为是她忘带了什么东西但随着车窗缓缓落下她就探过身子说了句你想不想","paragraph":48,"style":"plain","start":1401.88,"end":1411.9},{"text":"谈个恋爱我愣了一下然后点个点头她说你不怕异地吗我说我现在工作挺自由的她又问那你喜欢我","paragraph":48,"style":"plain","start":1411.9,"end":1424.36},{"text":"吗我说不知道算不算喜欢但跟你在一起我很开心高中的时候就很开心她喜笑颜开说那就够了刚要","paragraph":48,"style":"plain","start":1424.36,"end":1437.34},{"text":"走我伸手拉住了她本想耍个帅的但是磕到了她的脑袋","paragraph":48,"style":"plain","start":1437.34,"end":1442.34},{"text":"她一气之下打开车门坐在我的身上两人亲了很久但没干什么坏事主要是那个车也不防窥在外面可","paragraph":49,"style":"plain","start":1443.28,"end":1453.36},{"text":"以看得一清二楚后来我们在老家又待了一个多月吧每天我在书店工作她也在旁边准备回去的工作","paragraph":49,"style":"plain","start":1453.36,"end":1462.94},{"text":"然后时不时的念我两下嘴里念念有词的说姐想要，","paragraph":49,"style":"plain","start":1463.56,"end":1469.0},{"text":"姐得到走之前我跟爸妈说了一句他们很惊讶 但也没反对只是让我先把车窗的防窥膜卸了","paragraph":49,"style":"plain","start":1469.32,"end":1479.56},{"text":"他们觉得有点暗临走前，瓜姐跟我确认了一下说你真的要跟我去啊？","paragraph":50,"style":"plain","start":1480.06,"end":1487.24},{"text":"不要为我勉强自己哦我拿过她的行李箱放在了还贴着防窥膜的车上回答说也该轮到我向你靠近了","paragraph":50,"style":"plain","start":1487.74,"end":1499.52},{"text":"小猪小猪人呼呼遇到困难咕噜噜咕噜噜是什么意思呀就是睡觉的意思呀晚安宝宝嗯嘛","paragraph":51,"style":"plain","start":1504.82,"end":1522.22}]},{"id":"tangled-couple","title":"“拧巴”的小情侣","category":"story","sequence":8,"duration":1197.531429,"audio":"tangled-couple.mp3","palette":["#465a4f","#7b6952"],"cues":[{"text":"我自己的故事还没修改完，所以今天讲的还是别人的故事。","paragraph":0,"style":"plain","start":1.66,"end":6.48},{"text":"你觉得情侣吵架什么最重要？","paragraph":0,"style":"plain","start":8.0,"end":10.38},{"text":"对我来说可能输赢最重要。","paragraph":0,"style":"plain","start":11.44,"end":13.62},{"text":"就是喜欢归喜欢，爱你归爱你。","paragraph":0,"style":"plain","start":14.82,"end":17.48},{"text":"但这场架老子必须得赢。","paragraph":0,"style":"plain","start":18.1,"end":20.28},{"text":"我觉得人的骨子里是有点贱。","paragraph":1,"style":"plain","start":21.5,"end":24.1},{"text":"一个人的时候觉得孤单，想着如果有对象啊，就要对她怎么怎么好，","paragraph":1,"style":"plain","start":24.78,"end":30.02},{"text":"要和她成为令人羡慕的情侣，要让她感受到无与伦比的幸福。","paragraph":1,"style":"plain","start":31.0,"end":35.86},{"text":"可当两个人真的在一块的时候，幻想接触到现实，那真是一碰就碎。","paragraph":1,"style":"plain","start":37.66,"end":43.6},{"text":"别说什么幸福开心令人羡慕了，两个人吵起来，甚至都有掐死对方的冲动。","paragraph":1,"style":"plain","start":44.54,"end":50.22},{"text":"这可能无关于今晚的锅谁来刷 明天的衣服谁来洗有时候就是单纯不爽对方的态度 一次两次可","paragraph":2,"style":"plain","start":53.64,"end":62.41},{"text":"以忍总是触霉头 就免不得让人火大所以看着面前气鼓鼓的女友 我就在心里疯狂的质问自己不","paragraph":2,"style":"plain","start":62.41,"end":72.1},{"text":"谈这个恋爱 我是不是能死 是游戏不好玩还是一个人的生活太简单了 非要给自己上点强度可","paragraph":2,"style":"plain","start":72.1,"end":81.7},{"text":"能她也这么想的","paragraph":2,"style":"plain","start":81.7,"end":82.82},{"text":"所以两个人从晚上10点一直吵到了凌晨3点最后谁也不服谁分手就变成了唯一的收场方式正常","paragraph":3,"style":"plain","start":83.38,"end":93.2},{"text":"来说这种情况就要一拍两散各奔东西了但我们刚同居的房子还没到一个月年付的两居室房东那边","paragraph":3,"style":"plain","start":93.2,"end":103.42},{"text":"肯定不能退能退也不知道扣多少钱对我们这种刚工作两三年的北漂来说真不是说扔就能扔的而且","paragraph":3,"style":"plain","start":103.42,"end":112.8},{"text":"布置新家傻的也是一笔不小的开销","paragraph":3,"style":"plain","start":112.8,"end":115.42},{"text":"所以我们原本同居的关系从分手那天开始就变成了合租的室友事后我也想明白了这也不是谁对谁","paragraph":4,"style":"plain","start":116.64,"end":126.0},{"text":"错的问题归根结底原因还是两个人的性格不太合适所以那天晚上的觉我睡得特别香你至于睁眼就","paragraph":4,"style":"plain","start":126.0,"end":135.7},{"text":"到了十点多已经不是迟到而是旷工的程度了然后我拿起手机的第一眼就看到了她的转账消息因为","paragraph":4,"style":"plain","start":135.7,"end":145.56},{"text":"之前的房租我出的比较多嘛她就把多出来的补齐了","paragraph":4,"style":"plain","start":145.56,"end":149.7},{"text":"我理所当然的点了收款转头又把她送的PS5Switch啊一些杂七杂八的东西算了一下然后","paragraph":5,"style":"plain","start":150.36,"end":158.92},{"text":"给它转过去她没收说我也送了很多东西虽然分手了但这都是关系中的自愿赠予我说那房租也算自","paragraph":5,"style":"plain","start":158.92,"end":168.833},{"text":"愿呢她说刚住了不到一个月以后就不再关系内了我心想你算得还挺清楚也没继续跟她争气什么走","paragraph":5,"style":"plain","start":168.947,"end":179.88},{"text":"在上班的路上反正上午也旷工了我也不急","paragraph":5,"style":"plain","start":179.88,"end":183.4},{"text":"恢复单身的感觉就像一面吹蓝的风充满了自由的气息所长见我神采奕奕的还问我有什么好事我满","paragraph":6,"style":"plain","start":184.1,"end":194.34},{"text":"脸高兴地回答，","paragraph":6,"style":"plain","start":194.34,"end":195.14},{"text":"分手了。","paragraph":6,"style":"plain","start":195.72,"end":196.3},{"text":"所长以为我是在苦中作乐，还帮我跟人事那边说了一声，旷工的半天也给我划掉了，好家伙，","paragraph":6,"style":"plain","start":197.26,"end":205.26},{"text":"我更开心了。","paragraph":6,"style":"plain","start":205.7,"end":206.54},{"text":"晚上约着朋友们出来喝酒，聊天，打游戏，没人查岗的感觉，别提我多爽了。","paragraph":7,"style":"plain","start":207.7,"end":213.62},{"text":"我没跟他们说分手的事，但我能出来这么潇洒，他们估计也都猜到了。","paragraph":7,"style":"plain","start":214.58,"end":219.88},{"text":"什么也没问，就陪我散心来着。","paragraph":7,"style":"plain","start":220.72,"end":223.04},{"text":"玩完到家的时候已经是凌晨一点，我以为她已经睡着了，但两个房间看了一圈，发现都没人，","paragraph":8,"style":"plain","start":224.16,"end":231.52},{"text":"我心想，你玩得比我还野啊。","paragraph":8,"style":"plain","start":232.34,"end":234.68},{"text":"拿着手机看了一下朋友圈，她发了一张喝酒的照片，虽然我有点担心，但已经分手了，","paragraph":9,"style":"plain","start":237.2,"end":244.38},{"text":"也没啥身份问人家，我就在主卧收拾自己的东西。","paragraph":9,"style":"plain","start":244.8,"end":248.96},{"text":"其实我们租下这个两居室最开始就是打算一人一个房间的毕竟大家都是成年人嘛都有自己睡觉的","paragraph":9,"style":"plain","start":249.9,"end":257.94},{"text":"习惯也都想保留一份自己的空间但同居以后那次卧就变成了杂物间什么睡眠质量差不习惯旁边有","paragraph":9,"style":"plain","start":257.94,"end":267.82},{"text":"人","paragraph":9,"style":"plain","start":267.82,"end":268.0},{"text":"全都抛到了脑后甚至睡得比单身的时候还香因为我们的生活真是太规律了规律到老子都有点撑不","paragraph":10,"style":"plain","start":268.0,"end":278.9},{"text":"住了那一整晚她都没有回来第二天是周末中午才见她慢悠悠地走进门放假门也没啥事干就想做点","paragraph":10,"style":"plain","start":278.9,"end":289.68},{"text":"好吃的在手机上搜教程什么的一不小心就滑到了一些穿衣自由的视频她回屋的时候正好瞄到一眼","paragraph":10,"style":"plain","start":289.68,"end":299.34},{"text":"上来就是一句哼 又在看擦边呢","paragraph":10,"style":"plain","start":300.1,"end":303.7},{"text":"我心里这个气呀什么叫又啊老子跟你在一起快一年了首页刷到也从来没有关注点过再说咱们不是","paragraph":11,"style":"plain","start":304.72,"end":313.88},{"text":"已经分手了吗所以反嘴就怼了回去你管我呢她还来进呢说你别放洋屁昨天晚上干什么去了我也来","paragraph":11,"style":"plain","start":313.88,"end":325.9},{"text":"进了反正说不是你一整晚没回来吗说实话啊两个人在一起，","paragraph":11,"style":"plain","start":325.9,"end":332.9},{"text":"我从来没有不信任过她因为我一直觉得一个人想出轨是看不住的这种事情只能靠自觉","paragraph":11,"style":"plain","start":333.44,"end":341.54},{"text":"真没这个自觉，","paragraph":12,"style":"plain","start":342.04,"end":343.18},{"text":"那也没必要在一起了而实际上我们在一起的时候也没有出现过什么原则性的问题只不过很多时候","paragraph":12,"style":"plain","start":343.44,"end":352.2},{"text":"她安全感的满足都需要我牺牲一些东西来提供这个确实让我很难受刚开始还能忍着点后来就算我","paragraph":12,"style":"plain","start":352.51,"end":362.84},{"text":"信任她也要反击过来呛回去没别的就是想让她明白这种感受但她每次又会把我这种行为理解成为","paragraph":12,"style":"plain","start":362.84,"end":373.14},{"text":"不爱了因为她理解中的爱是不讲道理","paragraph":12,"style":"plain","start":373.14,"end":376.98},{"text":"没有理由是我受了委屈也要第一时间哄她的偏爱眼看我们又要吵起来家里养的那只金渐层就突然","paragraph":13,"style":"plain","start":376.98,"end":386.88},{"text":"开始了跑酷然后就飘了一股子屎臭味这是她的猫习惯每次拉完屎都要欢脱地跑一圈这时候我才发","paragraph":13,"style":"plain","start":386.88,"end":397.44},{"text":"现昨晚我们两个不在家都没人给她铲屎猫砂盆里的屎尿堆积成山我捏着鼻子处理完猫砂盆前女友","paragraph":13,"style":"plain","start":397.44,"end":407.92},{"text":"也回到了房间也算避免了一场大战","paragraph":13,"style":"plain","start":407.92,"end":410.9},{"text":"我奖励一般地给金渐层开了个猫条然后就去厨房做饭了饭菜做好以后她闻着味又出来然后一看锅","paragraph":14,"style":"plain","start":413.24,"end":422.28},{"text":"里空空如也以为我只做了一人份又气鼓鼓的回去我心里一阵暗爽然后就刷到了她官宣分手的朋友","paragraph":14,"style":"plain","start":422.28,"end":431.56},{"text":"圈说感谢小姐妹在分手的时候陪自己彻夜长谈配文里还有几张他们昨晚居家的合照我太了解她了","paragraph":14,"style":"plain","start":431.56,"end":441.62},{"text":"第一张喝酒的照片是在刺激我","paragraph":14,"style":"plain","start":441.62,"end":443.94},{"text":"第二章看我做饭没带她的，又在讨好我。","paragraph":15,"style":"plain","start":444.5,"end":447.38},{"text":"我又好奇又好笑。","paragraph":15,"style":"plain","start":448.18,"end":449.32},{"text":"但怎么说呢？","paragraph":15,"style":"plain","start":450.12,"end":450.88},{"text":"直到她昨晚一直和朋友在一起，我也算松了一口气。","paragraph":15,"style":"plain","start":451.6,"end":455.14},{"text":"然后我也发了个朋友圈，配文说，哎，饭菜做多了，只能放冰箱里，晚上吃剩饭了。","paragraph":15,"style":"plain","start":456.12,"end":463.84},{"text":"然后昨晚也没怎么休息好，就躺在客厅的沙发上睡着了，一觉就睡到了傍晚。","paragraph":16,"style":"plain","start":465.32,"end":471.12},{"text":"起床后，我发现冰箱里的饭菜已经没了，只剩下厨房洗好的碗筷。","paragraph":16,"style":"plain","start":472.9,"end":478.427},{"text":"我没忍住的笑出了声，饿了会吃饭，整个还不傻。","paragraph":16,"style":"plain","start":478.8,"end":483.06},{"text":"我家的厨房是朝西的，此时日落时分的阳光就充斥了整个房间，也同样照在了冰箱贴上。","paragraph":17,"style":"plain","start":484.28,"end":492.46},{"text":"上面有我们第一次做饭，第一次旅游，第一次拍大头贴的照片。","paragraph":17,"style":"plain","start":493.88,"end":499.56},{"text":"平时瞟一眼看一眼现在分手了再看到别人有一番滋味都说吵架的时候不要忘记对方曾经的好但我","paragraph":17,"style":"plain","start":500.72,"end":510.76},{"text":"还是觉得一码归一码那昨天吃的饭也没耽误我今天拉的屎对吧以爱为名都不讲道理说不好听的","paragraph":17,"style":"plain","start":510.76,"end":520.44},{"text":"那不就是PUA吗而且我也没有忘记她曾经的好一点都没有甚至现在再我还能说出我们认识的经","paragraph":18,"style":"plain","start":520.44,"end":529.62},{"text":"过说起来你可能不信我们是拼车认识的因为上班连续两次拼到一起就加了微信简单聊了几句发现","paragraph":18,"style":"plain","start":529.62,"end":541.16},{"text":"我们住的和工作的地方都不远所以就约好下雨阴天什么的打车AA正好那段时间北京连续下雨我","paragraph":18,"style":"plain","start":541.16,"end":550.3},{"text":"们也就一起坐了四五天的车车上有说有笑的","paragraph":18,"style":"plain","start":550.3,"end":554.3},{"text":"就产生了好感甚至那几天我都会祈祷阴天下雨这样就有理由找她了可有夜阑卧听淡盘风雨来能留","paragraph":19,"style":"plain","start":554.3,"end":567.36},{"text":"你在此的味道后来她跟我说那一周的时间她也在每天盯着天气预报然后变着花样的换衣服甚至上","paragraph":19,"style":"plain","start":567.36,"end":577.58},{"text":"车前还会故意淋点雨提升一下氛围感我这才惊觉她那身打湿的衣裳和楚楚动人的感觉是从哪来的","paragraph":19,"style":"plain","start":577.58,"end":586.52},{"text":"聊得多了就开始约出来玩嘛然后差不多两个月吧","paragraph":19,"style":"plain","start":587.78,"end":592.36},{"text":"我们就顺利确认了关系也算是一见钟情的双向奔赴正因为互相都很喜欢工作地点也比较一致所以","paragraph":20,"style":"plain","start":592.36,"end":602.98},{"text":"后来才决定同居其实同居之前我们的家也没少吵只不过没住在一起还有一定的缓冲空间那么问题","paragraph":20,"style":"plain","start":602.98,"end":613.7},{"text":"就来了同居到底给情侣带来了什么好像只有更多的争吵以及日渐虚弱的身体我从冰箱贴上回过神","paragraph":20,"style":"plain","start":613.7,"end":625.42},{"text":"的时候太阳已经落山了夏天的夕阳也不是盖的","paragraph":20,"style":"plain","start":625.42,"end":629.74},{"text":"这一会儿结果我晒出了一身汗然后我写了个早出来去到客厅打游戏没一会儿前女友也去洗澡了出","paragraph":21,"style":"plain","start":630.26,"end":639.62},{"text":"来的时候穿戴整齐看样子还没忘记我们已经分手了只不过她头发很长吹了个半干衣服也打湿了不","paragraph":21,"style":"plain","start":639.62,"end":649.92},{"text":"少一瞬间还有种初遇时候的感觉我这人怕热她不在的时候都会把空调开得很低所以这会儿客厅还","paragraph":21,"style":"plain","start":649.92,"end":660.6},{"text":"不到二十度我看了眼的半干的头发","paragraph":21,"style":"plain","start":660.6,"end":663.58},{"text":"想了想还是把温度调高了这真不是我想和好还是那句话，","paragraph":22,"style":"plain","start":663.58,"end":670.2},{"text":"一码归一码就算是普通室友我也会照顾一下对方的感受更何况是她了我觉得分个手还不至于让自","paragraph":22,"style":"plain","start":670.54,"end":679.46},{"text":"己变得面目可憎而且我俩也没什么原则性的问题她坐在那里看电视转头笑了一下刚想说点什么我","paragraph":22,"style":"plain","start":679.46,"end":690.0},{"text":"翻那个白眼抢先道打住，","paragraph":22,"style":"plain","start":690.0,"end":692.26},{"text":"没想和你和好啊她笑容凝固在脸上撇了撇嘴说我自作多情","paragraph":22,"style":"plain","start":692.7,"end":698.74},{"text":"然后又小声的嘀咕一句小心眼对对对 我就是小心眼因为每次和好都是不清不楚的然后反复在同","paragraph":23,"style":"plain","start":700.0,"end":710.86},{"text":"样的问题里消耗彼此的情绪她看了两集综艺就回房间了我以为她要睡觉就下意识地带上耳机降低","paragraph":23,"style":"plain","start":710.86,"end":720.06},{"text":"了音量那天我发挥的还不错用吕大将军多次拯救队友耳机里还传了一声声的义父于是呢，","paragraph":23,"style":"plain","start":720.06,"end":730.22},{"text":"我就奖励了自己的两把迦娜","paragraph":23,"style":"plain","start":730.48,"end":731.8},{"text":"然后我们叠加态的父子的关系又发生了变化那两个不孝子孙倒反天罡虽然对他们的义父出言不逊","paragraph":24,"style":"plain","start":733.46,"end":742.24},{"text":"但父爱如山嘛，","paragraph":24,"style":"plain","start":742.74,"end":744.04},{"text":"我也不跟他们计较那真是一幅父慈子孝的美好画面后来那段时间，","paragraph":24,"style":"plain","start":744.32,"end":750.88},{"text":"我就一直睡沙发因为第一天分手的晚上我发现次卧没有空调当初签合同的时候也没有想到有一天","paragraph":24,"style":"plain","start":751.3,"end":760.08},{"text":"会分房睡","paragraph":24,"style":"plain","start":760.08,"end":760.74},{"text":"前女友可能是看我可怜一周过去了有天提议说可以互换房间她不怕热我美好记得拒绝了她不怕个","paragraph":25,"style":"plain","start":763.7,"end":773.68},{"text":"屁她是那种湿热体质有时候开始空调坐在那不动她都能汗流浃背但我也觉得这样不是办法于是就","paragraph":25,"style":"plain","start":773.68,"end":784.2},{"text":"厚着脸皮跟房东说了突然多出了一笔开销房东那边肯定不愿意嘛但她也知道这算是服务范围内的","paragraph":25,"style":"plain","start":784.26,"end":792.86},{"text":"最后还是答应了空调上门安装了前一天","paragraph":25,"style":"plain","start":793.26,"end":796.92},{"text":"前女友不知道怎么了合租正常的交流也不说了板着个脸好像是欠了500万似的我看到那副样子","paragraph":26,"style":"plain","start":797.26,"end":806.28},{"text":"脑袋一阵发昏在一起的时候就喜欢生闷气有情绪也不说就让我自己猜现在分手了我更懒得搭理她","paragraph":26,"style":"plain","start":806.28,"end":815.895},{"text":"了该去吃该喝喝到点蒙头就睡然后半夜迷迷糊糊的时候就看到沙发前坐着一个黑咕隆咚的身影吓","paragraph":26,"style":"plain","start":816.0,"end":825.84},{"text":"得我头皮发麻仔细一看才发现是前女友我说你干嘛呢","paragraph":26,"style":"plain","start":825.84,"end":832.1},{"text":"她伸着脑袋钻到我的手臂下面委屈巴巴的说你真的要跟我分开呀我说我们不是已经分开了吗？","paragraph":27,"style":"plain","start":832.82,"end":842.14},{"text":"她只穿了个睡衣又坐直了身体像是在展示自己的魅力一样说你不会找到比我更好的呢？","paragraph":27,"style":"plain","start":843.16,"end":851.32},{"text":"天地良心啊我从来没有拿她和任何人对比过也没有否认过她的价值相信很多人都会有这样的感觉","paragraph":28,"style":"plain","start":853.02,"end":862.08},{"text":"就是刚分手的时候甚至都不想和异性说话只是单纯享受宁静的生活但她每次吵架都觉得我外面有","paragraph":28,"style":"plain","start":862.74,"end":871.66},{"text":"人了是移情别恋了才不让着她才不委屈自己来偏爱她所以我就有点生气于是跟她说你到底哪来这","paragraph":28,"style":"plain","start":871.66,"end":881.79},{"text":"么多的假想敌呢她言之凿凿地反问我","paragraph":28,"style":"plain","start":881.79,"end":885.5},{"text":"你不是喜欢上别人才跟我分手的我真是气笑了情绪有些激动地把手机甩给她说我平时玩手机干嘛","paragraph":29,"style":"plain","start":886.04,"end":895.98},{"text":"的也不背着你出去玩也都是跟你在一起我怎么可能喜欢上别人呢？","paragraph":29,"style":"plain","start":895.98,"end":901.4},{"text":"她没说话了又搬出了经典的态度问题你干嘛那么大声呢？","paragraph":29,"style":"plain","start":902.52,"end":907.94},{"text":"我按着脑门只觉得血压比天还高最后整理了一下情绪认真的对她说宝啊我没有喜欢上别人也没有","paragraph":30,"style":"plain","start":908.8,"end":919.48},{"text":"不爱你了但我真的没有那么多的情绪可以消耗我不想有那么多的猜疑也不想有那么多的试探这样","paragraph":30,"style":"plain","start":919.48,"end":928.92},{"text":"真的很累她听到我说没有不爱你的时候眼角里闪过一丝笑意但还是在跟我对着干那喜欢一个人肯","paragraph":30,"style":"plain","start":928.92,"end":939.94},{"text":"定会有些小情绪啊我刚降下去的血压蹭了一下又上来了","paragraph":30,"style":"plain","start":939.94,"end":945.36},{"text":"你这都哪里喝的毒鸡汤啊不是两个人咋就不能情绪稳定的在一起呢","paragraph":31,"style":"plain","start":946.56,"end":952.56},{"text":"她被我说的有些急了 开始人身攻击你一个男生怎么那么难哄啊 我没再跟她争执什么倒头便在","paragraph":32,"style":"plain","start":954.92,"end":964.6},{"text":"沙发 接着睡了 她也气呼呼的回房间","paragraph":32,"style":"plain","start":964.6,"end":968.66},{"text":"然后第二天下班回来 我出奇地发现她已经叫师傅安装好的空调 还顺手帮我收拾一下安装留下","paragraph":33,"style":"plain","start":974.18,"end":982.447},{"text":"的灰尘我有些警惕的跟她说了声谢谢观察了半天她没有什么别的情况才安心回到房间睡了半个月","paragraph":33,"style":"plain","start":982.54,"end":992.62},{"text":"的沙发我终于能正经地在床铺上睡一下了但也不知道为啥在沙发上一躺就着躺在床上却睡不着了","paragraph":33,"style":"plain","start":992.62,"end":1001.52},{"text":"然后我就在那玩手机嘛看了一堆乱七八糟的东西","paragraph":33,"style":"plain","start":1001.88,"end":1005.4},{"text":"自律了半个多月更睡不着了没办法我寻思都能睡着又拿着枕头躺回了沙发刚有点睡意的时候我就","paragraph":34,"style":"plain","start":1006.26,"end":1016.84},{"text":"听到她的脚步声然后就感觉沙发上又挤上了一个人我本来就有点难受沙发就这么大点的地方现在","paragraph":34,"style":"plain","start":1016.84,"end":1026.98},{"text":"两个人贴在一起互相之间的身体又散发着空调地降不下来的温度我那时候才明白为什么有句老话","paragraph":34,"style":"plain","start":1026.98,"end":1036.32},{"text":"叫床头吵架 床尾和恢复理智的我在心里大喊 上当了","paragraph":34,"style":"plain","start":1036.32,"end":1043.92},{"text":"她在一旁问我在想什么但实际上进入贤者模式的我 什么都想不了她竟然没有说话 怯生生地说","paragraph":35,"style":"plain","start":1044.74,"end":1054.02},{"text":"以后我不让你这么累了我当然能理解她为了修复这段关系做出的努力所以我也没有在说什么就伸","paragraph":35,"style":"plain","start":1054.56,"end":1064.12},{"text":"出手 慢慢抱住了她吵架分手半个多月的时间她硬是一声没哭一滴眼泪也没掉但在我抱着她的时","paragraph":35,"style":"plain","start":1064.12,"end":1073.6},{"text":"候却在我怀里委屈巴巴的哭了","paragraph":35,"style":"plain","start":1073.6,"end":1076.76},{"text":"然后说了一句直戳我心窝的话不会有人比我更爱你了这话你带着三分道歉三分挽留以及三分自白","paragraph":36,"style":"plain","start":1077.5,"end":1087.92},{"text":"剩下的91分全都是喜欢我自认为不是一个缺爱的人但你知道一个女孩子泪眼婆娑地讲出这句话","paragraph":36,"style":"plain","start":1088.5,"end":1097.5},{"text":"的时候杀伤力有多大吗？","paragraph":36,"style":"plain","start":1097.5,"end":1099.54},{"text":"所以我抱着她，","paragraph":37,"style":"plain","start":1100.38,"end":1101.4},{"text":"也认真的对她说虽然我们之间有争吵也有这辈子可能都无法达成的共识但无论如何，","paragraph":37,"style":"plain","start":1101.98,"end":1109.94},{"text":"我也不会让你这份爱意落空了她好像达到目的一样，破涕为笑问我，那我们和好了？","paragraph":37,"style":"plain","start":1110.28,"end":1118.84},{"text":"我看到那副可爱的样子也忍不住笑得起来摸着她在脑袋回答道我们天下第一好","paragraph":38,"style":"plain","start":1120.24,"end":1128.22},{"text":"后来我们还是经常吵架次卧的空调也没有白装我三天两头就要去避避风头甚至房子快到期了那两","paragraph":39,"style":"plain","start":1130.88,"end":1139.88},{"text":"天我们还大吵了一下就在两个人吵得不可开交的时候房东那边突然发两个消息说 马上一年了你","paragraph":39,"style":"plain","start":1139.88,"end":1150.14},{"text":"们还续租吗？","paragraph":39,"style":"plain","start":1150.14,"end":1151.14},{"text":"我和她看着消息，面面相觑互相瞪了一眼然后又在手机上默默地续租了我们的房子","paragraph":40,"style":"plain","start":1152.12,"end":1162.0},{"text":"喜欢你才会想黏着你吗？","paragraph":41,"style":"plain","start":1165.22,"end":1167.62},{"text":"不行，那你抱紧了把世界上最喜欢你的宝宝抓走哼，今天有点想你其实不止有点，","paragraph":41,"style":"plain","start":1168.5,"end":1178.8},{"text":"其实也不止今天，在没见面的日子里对你的喜欢，真是与日俱增啊。","paragraph":41,"style":"plain","start":1179.52,"end":1188.48},{"text":"宝宝呀，我真的好喜欢你呀。","paragraph":42,"style":"plain","start":1189.56,"end":1192.42}]},{"id":"open-book","title":"这算开卷考试了吧，都不用猜了","category":"story","sequence":9,"duration":896.914286,"audio":"open-book.mp3","palette":["#485f52","#726451"],"cues":[{"text":"有时候回想起来，人与人之间的靠近，其实根本没有什么大张旗鼓的预谋。","paragraph":0,"style":"plain","start":3.08,"end":9.48},{"text":"往往都是从一些细碎的缝隙开始的。","paragraph":0,"style":"plain","start":10.42,"end":13.28},{"text":"有可能是一杯带着水汽的冰水，一场不知不觉走到底的夜路，","paragraph":0,"style":"plain","start":14.18,"end":19.44},{"text":"或者一句在神志不清时脱口而出的玩笑。","paragraph":0,"style":"plain","start":20.16,"end":24.4},{"text":"我记得那是我毕业后的第三年当时我刚换到一家不算很大的公司带一个十个人的小团队负责公司","paragraph":1,"style":"plain","start":25.58,"end":35.16},{"text":"的新媒体和产品运营的工作那阵子我整个人的状态都很消沉因为刚跟前任分手不到一年心里的那","paragraph":1,"style":"plain","start":35.16,"end":44.42},{"text":"道坎其实还没有完全过去在公司里我基本上是一副冷面孔除了交代工作平时很少跟人闲聊加上身","paragraph":1,"style":"plain","start":44.42,"end":55.1},{"text":"上背的业务压力很大每天坐在工位上连轴转","paragraph":1,"style":"plain","start":55.1,"end":58.82},{"text":"我也总是催着大家拼命的赶产出导致不少人私下里都有点怵我觉得我严肃冷淡有种生人勿近的气","paragraph":2,"style":"plain","start":59.66,"end":68.76},{"text":"质","paragraph":2,"style":"plain","start":68.76,"end":69.04},{"text":"我记得那时7月份那会儿长沙的天气非常热热得像个大蒸笼太阳毒辣地面都在冒着热气面试那天","paragraph":3,"style":"plain","start":71.24,"end":82.9},{"text":"来了一个叫抱抱的姑娘她有着南方人标准的小个子特征长相属于那种很清纯的学生妹的脸庞乖巧","paragraph":3,"style":"plain","start":82.9,"end":92.54},{"text":"的面容垂着齐肩的头发面试的过程她在我对面坐着聊了一会儿给我的感觉是整个人很聪明但却透","paragraph":3,"style":"plain","start":92.54,"end":103.56},{"text":"着一股特别难得的实诚","paragraph":3,"style":"plain","start":103.56,"end":105.26},{"text":"既有刚出校门的那种干净的学生气却有着难得的清醒和透彻虽然过去他的工作做的是财务来到这","paragraph":4,"style":"plain","start":106.38,"end":117.24},{"text":"里算是想转行可基于他面试良好的表现我还是给他发了offer入职之后他的工作上手很快也","paragraph":4,"style":"plain","start":117.24,"end":127.66},{"text":"有推的也很顺那阵子长沙的天气很热嘛但每天我都会在最热的时候回到宫位都会发现桌面上放着","paragraph":4,"style":"plain","start":127.66,"end":137.9},{"text":"一杯冰冰的小甜水有时候是冰杨梅汁有时候是柠檬水","paragraph":4,"style":"plain","start":137.9,"end":143.82},{"text":"或者一些清爽的冰凉甜汤塑料杯的外头还会凝着一层新鲜的水珠顺着杯壁淌在桌垫上摸上去特别","paragraph":5,"style":"plain","start":144.38,"end":154.86},{"text":"冰凉起初我以为是阿谦干的这小子平时给我捅了娄子就喜欢贿赂我给他擦屁股阿谦这个名字的由","paragraph":5,"style":"plain","start":154.86,"end":165.32},{"text":"来是因为他长得很像薛之谦团队里平时就属大最活跃整天跟在我的屁股后面老大长老大短的叫着","paragraph":5,"style":"plain","start":165.32,"end":173.76},{"text":"连着喝了几天我实在是没忍住","paragraph":5,"style":"plain","start":174.54,"end":177.44},{"text":"这小子究竟给我惹了多大的祸我就把他叫过来问你小子怎么回事天天掏腰包给我买喝的又捅了什","paragraph":6,"style":"plain","start":177.9,"end":186.45},{"text":"么楼子阿谦被我问得一脸发懵然后连忙摆手老大你搞错了吧我连自己喝奶茶都舍不得听听点那个","paragraph":6,"style":"plain","start":186.45,"end":196.34},{"text":"不是我干的我说那是谁干的他多嘟多嘴嘴了嘴团队里心来的抱抱是她买的","paragraph":6,"style":"plain","start":196.34,"end":206.02},{"text":"听到这个回复我心里其实还有点纳闷心想难道是刚入职正变着法子给领导示好搞好关系我也没太","paragraph":7,"style":"plain","start":208.24,"end":217.76},{"text":"放在心上毕竟平时大家都是公事公办无功不受禄我就在微信上找他准备把这几天的饮料钱给他A","paragraph":7,"style":"plain","start":217.76,"end":226.66},{"text":"了谁知道他回了一句没关系的这都是我点外卖为了凑单随便选的别客气好家伙原来我喝了几天的","paragraph":7,"style":"plain","start":226.66,"end":236.98},{"text":"小饮料全都是凑单减运费的我就回了他一句","paragraph":7,"style":"plain","start":236.98,"end":242.06},{"text":"合着我就是个帮你凑起送费的工具人呗那我以后每天都要心安理得享受你的凑单特权了话虽然这","paragraph":8,"style":"plain","start":242.52,"end":251.8},{"text":"么说，","paragraph":8,"style":"plain","start":251.8,"end":252.12},{"text":"但是其实心里也明白哪有这么巧，天天点外卖，都刚好差一杯小甜水凑单的这姑娘聪明，","paragraph":8,"style":"plain","start":252.34,"end":260.14},{"text":"水上找了个让你挑不出毛病，","paragraph":8,"style":"plain","start":260.7,"end":262.4},{"text":"谁也不尴尬的借口台阶给的倒是顺理成章日子就这么到了9月份我们团队十个人里，","paragraph":8,"style":"plain","start":262.7,"end":271.92},{"text":"除了阿谦和抱抱两个是湖南本地人","paragraph":8,"style":"plain","start":272.32,"end":274.5},{"text":"其余基本上都是外地过来的平时大家也没有太多私交但因为阿谦这个人爱张罗我和他还有抱抱三","paragraph":9,"style":"plain","start":274.9,"end":284.24},{"text":"个人偶尔也会在周五加班后一起吃个便饭真正让我感觉到他对我不一样的是在九月的某一个周五","paragraph":9,"style":"plain","start":284.24,"end":293.7},{"text":"那天又是高强度的加班工作完以后三个人都饿得不行阿谦就提议去湘江边的一家泰国菜餐厅吃点","paragraph":9,"style":"plain","start":295.4,"end":304.0},{"text":"东西临江的位置能吹到一点晚风整个人都放松了不少","paragraph":9,"style":"plain","start":304.0,"end":309.72},{"text":"也就是在那顿饭的桌上我突然发现这个女生身上有一种特别懂人心的感觉她很懂你的需求有时甚","paragraph":10,"style":"plain","start":310.54,"end":320.52},{"text":"至不需要你开口那种照顾人的分寸感拿捏得特别好而且聊天的时候无论聊到什么她都特别能接话","paragraph":10,"style":"plain","start":320.52,"end":329.32},{"text":"完全不会让你的话掉在地上我从小是家里最小的孩子一直是在家人的关怀里长大的所以对别人传","paragraph":10,"style":"plain","start":330.1,"end":339.22},{"text":"递过来的善意会特别敏锐那谁是客套","paragraph":10,"style":"plain","start":339.22,"end":342.58},{"text":"谁是真的体恤你 理解你一搭眼就能感觉到那一刻真的有想到一种被妥帖对待的舒服感从那个饭","paragraph":11,"style":"plain","start":343.02,"end":354.16},{"text":"以后我对他的好感也慢慢上来了我们当时明面上是朝九晚七但因为手头上的工作压力比较大基本","paragraph":11,"style":"plain","start":354.16,"end":364.36},{"text":"上每天晚上都得加班到十点多一周满打满算也就休一天但即使累成这样每天晚上下班回到各自的","paragraph":11,"style":"plain","start":364.36,"end":374.0},{"text":"住处我们还是会在微信上聊到深夜","paragraph":11,"style":"plain","start":374.0,"end":377.2},{"text":"一开始只是就着白天的工作聊几句后来越聊越开天南地北的车会一切吐槽公司里奇奇怪怪的制度","paragraph":12,"style":"plain","start":378.12,"end":387.16},{"text":"吐槽老板 吐槽某些同事聊完工作又会聊生活然后各自追的剧，","paragraph":12,"style":"plain","start":387.56,"end":394.593},{"text":"喜欢的明星也就是在那段时候我发现我们俩平时的性格爱好竟然能契合到这种地步","paragraph":12,"style":"plain","start":394.86,"end":402.38},{"text":"白天在工位上，","paragraph":13,"style":"plain","start":404.5,"end":405.72},{"text":"他是下属我是每天催进度的领导到了深夜的屏幕两端那些绷了一整天的疲惫反而会在跟他的一言","paragraph":13,"style":"plain","start":406.06,"end":415.14},{"text":"一语里全都消解掉了我记得那段时间优酷刚上线了一部刑侦剧叫《白夜追凶》我平时对这种悬疑","paragraph":13,"style":"plain","start":415.14,"end":425.6},{"text":"破案类的题材本来就很入迷一看就彻底刹不住车连着几天我几乎天天熬了个小通宵第二天再拖着","paragraph":13,"style":"plain","start":425.6,"end":435.5},{"text":"特别疲惫的身体去公司上班","paragraph":13,"style":"plain","start":435.5,"end":437.46},{"text":"白天手头暂时没事的时候我就直接趴在工位上补觉","paragraph":14,"style":"plain","start":438.26,"end":441.78},{"text":"到了晚上手机微信提示音响了宝宝发消息过来问我你为什么每天都这么累呢白天在工位上那副样","paragraph":15,"style":"plain","start":444.4,"end":453.54},{"text":"子让大家看着还以为公司要把你怎么着了我当时刚回到住处脑子还昏昏沉沉的顺手就回了实话没","paragraph":15,"style":"plain","start":453.54,"end":463.8},{"text":"办法晚上老在家里打游戏看剧不过你可得给我保密","paragraph":15,"style":"plain","start":463.8,"end":468.12},{"text":"屏幕内的头立刻就回了一串哭笑的表情紧接着问什么就这么好看我说是白夜追凶他又问，","paragraph":16,"style":"plain","start":470.5,"end":479.2},{"text":"那你是喜欢这种类型的剧还是有哪个喜欢的明星可以采取我说都有吧潘粤明那会的演技也确实好","paragraph":16,"style":"plain","start":479.5,"end":487.9},{"text":"我也比较吃这种剧情微信那端安静了大概有半分钟接着屏幕上冷不丁地弹出来一条那你平时有喜","paragraph":16,"style":"plain","start":487.9,"end":497.9},{"text":"欢的女明星吗或者说现实里有喜欢什么风格的女性吗","paragraph":16,"style":"plain","start":497.9,"end":502.88},{"text":"看到这行字我握着手机的手微微一紧敏锐地感觉到这里头好像有点试探的味道到了这个份上我干","paragraph":17,"style":"plain","start":504.0,"end":513.44},{"text":"脆也不再绕弯子顺水推舟的直奔主题女明星倒还好要说现实里的女性那你算一个吧发完这句话屏","paragraph":17,"style":"plain","start":513.44,"end":525.06},{"text":"幕那头显然被打了一个猝不及防对话框顶部的对方正在输入闪烁了好几下最后再慢吞吞的回过来","paragraph":17,"style":"plain","start":525.06,"end":533.54},{"text":"几个字","paragraph":17,"style":"plain","start":533.54,"end":534.02},{"text":"我看着她那副慌张的样子故意反击回去那妳呢？","paragraph":18,"style":"plain","start":536.36,"end":540.86},{"text":"她憋出来一句我喜欢郭德纲我差点没在床头笑喷趁势就继续问她那现实里的男生呢？","paragraph":18,"style":"plain","start":542.06,"end":550.78},{"text":"现实里也是郭德纲因为我现实里见过她这姑娘摆明了是在那拿郭德纲当挡箭牌故意嘴硬看着对话","paragraph":18,"style":"plain","start":551.6,"end":561.39},{"text":"框里他又慌忙又忸怩的回覆那一瞬间我心里的情绪开始上头不想再隔着屏幕绕圈子只想把那层窗","paragraph":18,"style":"plain","start":561.485,"end":571.7},{"text":"户纸彻底捅破","paragraph":18,"style":"plain","start":571.7,"end":572.96},{"text":"我收起开玩笑的语气很认真地敲过去一段话如果我喜欢你我们能尝试相处一下吗消息发过去他大","paragraph":19,"style":"plain","start":573.76,"end":584.36},{"text":"概是被打蒙了未经那头开始噼里啪啦发过来一大堆退缩的话比如，","paragraph":19,"style":"plain","start":584.36,"end":591.62},{"text":"不是，","paragraph":19,"style":"plain","start":591.62,"end":592.02},{"text":"其实我还没有做好准备可能对你有点好感但完全没有想到那一步而且在同一个团队我们这种上下","paragraph":19,"style":"plain","start":592.42,"end":600.94},{"text":"级的关系传出这些会不会影响工作太快了吧你看我才刚来多久","paragraph":19,"style":"plain","start":600.94,"end":606.8},{"text":"人呐，","paragraph":20,"style":"plain","start":608.54,"end":609.28},{"text":"在慌乱的时候总喜欢找一堆大道理往后缩我不想看这些真相背后的借口直接发过去依据愿意还是","paragraph":20,"style":"plain","start":609.58,"end":618.62},{"text":"不愿意回过两个字或者三个字对话框一下安静了屏幕那头停顿了漫长的半分钟最后跳出了很轻巧","paragraph":20,"style":"plain","start":618.62,"end":629.66},{"text":"却无比清晰了两个字愿意那天晚上别提心里我多高兴了确认关系以后才发现很多之前藏在暗处的","paragraph":20,"style":"plain","start":629.66,"end":641.98},{"text":"秘密才一点点被揭开有一天下班我们没坐地铁","paragraph":20,"style":"plain","start":641.98,"end":647.38},{"text":"一路溜达着走回去从公司到我家里大概要七站地铁的距离真靠两条腿走其实是一段很漫长的路但","paragraph":21,"style":"plain","start":647.98,"end":657.407},{"text":"那天晚上谁也没觉得累就顺着江风慢慢走走在那条路上他侧过头来看着我也跟我坦白的最初的心","paragraph":21,"style":"plain","start":657.753,"end":667.62},{"text":"思他说你知道吗面试那天第一眼看见你的时候他的心其实跳得很厉害我笑了笑问他，","paragraph":21,"style":"plain","start":667.62,"end":676.54},{"text":"为什么会心跳？","paragraph":21,"style":"plain","start":677.02,"end":677.86},{"text":"你有什么心脑血管疾病吗？","paragraph":21,"style":"plain","start":678.72,"end":680.24},{"text":"他说，你别扯淡，就是觉得你身上有一种很强烈的性张力身材、声音、长相都透着一种很粗犷、","paragraph":22,"style":"plain","start":681.16,"end":691.0},{"text":"很原始的感觉就是第一眼在生理上有很强的吸引力","paragraph":22,"style":"plain","start":691.34,"end":695.42},{"text":"我继续逗他，我说那你后来天天给我买甜水，难道全是图这些？","paragraph":23,"style":"plain","start":697.38,"end":703.08},{"text":"他笑了笑身体上的吸引肯定是有的但真的想尝试接触还是后来发现你这个人靠谱真实让人觉得踏","paragraph":23,"style":"plain","start":703.5,"end":713.793},{"text":"实紧接着她又交代的另外一件事他平时不酗酒但是很喜欢喝小酒尤其是偏爱那种有甜味的鸡尾酒","paragraph":23,"style":"plain","start":714.367,"end":723.8},{"text":"精酿特调其实骨子里还是喜欢喝甜味的小甜水我记得有一天","paragraph":23,"style":"plain","start":724.047,"end":731.14},{"text":"他突然在微信上问我有没有空因为当时大家的关系还没有那么熟一个女孩子冷不丁单独问你有没","paragraph":24,"style":"plain","start":731.14,"end":739.133},{"text":"有空我心里其实挺慌的不知道该怎么接又试探着问了句怎么了他说出来喝个小酒吗和阿谦一起我","paragraph":24,"style":"plain","start":739.133,"end":751.02},{"text":"一听有旁人在觉得多个人在场也并不尴尬就答应了结果等我到了清吧推开门卡座就他一个人根本","paragraph":24,"style":"plain","start":751.02,"end":760.98},{"text":"没看到那小子后来我才知道他压根就没叫阿谦","paragraph":24,"style":"plain","start":760.98,"end":765.02},{"text":"纯粹是拿他当个幌子怕单独约我不肯出来那天晚上我们从九点多一直聊到深夜十二点多喝完之后","paragraph":25,"style":"plain","start":765.52,"end":774.98},{"text":"时间太晚了我就问他都这么晚了你回家也没有问题啊他晃着酒杯低声说了句回家的话爸妈现在可","paragraph":25,"style":"plain","start":774.98,"end":785.38},{"text":"能已经睡了我当时也没有往别处想还一本正经地觉得那就别吵着老人家特规矩地叫了车送他回家","paragraph":25,"style":"plain","start":785.38,"end":795.14},{"text":"直到走在七站路的那个晚上他在咬牙切齿地跟我翻旧帐","paragraph":25,"style":"plain","start":796.22,"end":800.56},{"text":"你知不知道你那天有多迟钝我话都说到那个份上了其实当天根本就没准备回去甚至连换洗的衣服","paragraph":26,"style":"plain","start":801.32,"end":809.5},{"text":"都在包里带好了你要是再野蛮一点完全可以带我走听完我真的哭笑不得后面在一起之后我才慢慢","paragraph":26,"style":"plain","start":809.5,"end":819.42},{"text":"了解她其实也有很强的厌男倾向对大多数的异性天然带着很重的防卫心也不是那种非常随便的女","paragraph":26,"style":"plain","start":819.42,"end":828.1},{"text":"生可偏偏就是这样一个满身防卫的人","paragraph":26,"style":"plain","start":828.1,"end":831.38},{"text":"却能够打着胆子和执念以步步的靠近我后来到了国庆长假她偷偷跟家里撒了个谎说自己去外地见","paragraph":27,"style":"plain","start":831.94,"end":841.4},{"text":"朋友然后拖着行李箱在我的单身公寓里住了整整7天就这样两个原本都把心防筑得很高的人就这","paragraph":27,"style":"plain","start":841.4,"end":852.03},{"text":"么慢慢缱绻地把彼此装进了自己的生活里现在回头来看故事好像很戏剧但在一起的日子里全都是","paragraph":27,"style":"plain","start":852.03,"end":863.5},{"text":"最实在的细节可惜啊那个时候我们都没有想到过","paragraph":27,"style":"plain","start":863.5,"end":868.96},{"text":"这种类似入室抢劫般的爱情终究还是没能逃过七年之痒","paragraph":28,"style":"plain","start":869.42,"end":873.86},{"text":"报告《迷湖宝宝》今日份的工作上午有点想你下午持续想你应该受到了天气的影响晚上准备了超","paragraph":29,"style":"plain","start":876.48,"end":888.8},{"text":"级想你我决定一会儿去梦里见你晚安啊 迷湖宝宝","paragraph":29,"style":"plain","start":888.8,"end":895.0}]},{"id":"brightest-star","title":"你是天上最亮的那颗星！","category":"story","sequence":10,"duration":957.204898,"audio":"brightest-star.mp3","palette":["#516153","#6d5f54"],"cues":[{"text":"我一直觉得人与人之间的关系都是安排好的。","paragraph":0,"style":"plain","start":2.44,"end":6.88},{"text":"有些人无论你怎么努力跟她就是有缘无分。","paragraph":0,"style":"plain","start":7.62,"end":11.48},{"text":"而有些人无论你们经历了多少曲折却总是能够相逢。","paragraph":0,"style":"plain","start":12.3,"end":17.4},{"text":"所以我这人一直挺随缘的以至于大学毕业都还没有谈过一次恋爱由于我妈是计算机老师我从小就","paragraph":0,"style":"plain","start":18.6,"end":29.48},{"text":"对这方面挺感性趣所以大学报的软件工程实际工作本来想找个互联网公司但大四那阵子行业环境","paragraph":0,"style":"plain","start":29.48,"end":38.78},{"text":"收紧","paragraph":0,"style":"plain","start":38.78,"end":39.16},{"text":"我觉得互联网这块把握不住就凑热闹的面试了一家汽车软件的公司可能是我之前为了竞赛学过单","paragraph":1,"style":"plain","start":39.94,"end":49.08},{"text":"片机编程的缘故吧竟然在一众面试者当中入职了实习报到那天还有个新人是个穿着白色长裙的女","paragraph":1,"style":"plain","start":49.08,"end":59.36},{"text":"生我俩等HR的时候就简单地聊了两句她是英国名校研究生毕业来做项目管理管的是硬件生产方","paragraph":1,"style":"plain","start":59.36,"end":69.56},{"text":"向跟我软件开发这边基本上没什么交集","paragraph":1,"style":"plain","start":69.56,"end":73.32},{"text":"我也认为这只是一次普通的闲聊实习过程中我的表现不错所以顺利转正了然后在应届生的欢迎会","paragraph":2,"style":"plain","start":74.5,"end":84.58},{"text":"上我又看到了那个女生她也都拿到了转正名额两人之间有过一面之缘吗很自然的聊得起来也加上","paragraph":2,"style":"plain","start":84.58,"end":94.82},{"text":"了微信她的头像是个杰尼龟又比我大所以就叫她姐姐吧后续应届生要在工厂体验一下生产环境姐","paragraph":2,"style":"plain","start":94.82,"end":106.84},{"text":"姐和我家都比较远所以都住在了附近的宾馆","paragraph":2,"style":"plain","start":106.84,"end":110.3},{"text":"两个人也算是组上了队那一周的时间里反正就一起吃喝玩乐啥的相处当中走得越来越近甚至玩闹","paragraph":3,"style":"plain","start":111.04,"end":120.5},{"text":"当中会有一些肢体接触比如我抓娃娃比较厉害100个硬币能抓十多个她就开心地拽着我的手臂","paragraph":3,"style":"plain","start":120.56,"end":129.92},{"text":"贴在她的胸前","paragraph":3,"style":"plain","start":129.92,"end":131.36},{"text":"对于从来没谈过恋爱的我哪能受得了这个对姐姐的好感也是一天比一天多我以为她对我也有意思","paragraph":4,"style":"plain","start":134.68,"end":144.78},{"text":"脑袋一热就决定为爱冲锋于是就在她国庆和爸妈旅游的途中在微信上跟人表白了姐姐拒绝的很干","paragraph":4,"style":"plain","start":145.38,"end":156.78},{"text":"脆说她大学的时候谈过一段恋爱但爱情带给她的只有痛苦和内耗所以只想维持现在这样的关系并","paragraph":4,"style":"plain","start":156.78,"end":165.96},{"text":"不想经营一段感情虽然被拒了但我当时脑子发热","paragraph":4,"style":"plain","start":165.96,"end":170.8},{"text":"全然忘记了随缘的法则总觉得人家愿意维持现在这样那就还有机会于是又猛追了一段时间当我追","paragraph":5,"style":"plain","start":171.14,"end":181.42},{"text":"她就跑她跑我还要追姐姐最后还是给出了明确的拒绝说对我的付出感到的只有内疚我也终于明白","paragraph":5,"style":"plain","start":181.62,"end":191.9},{"text":"人家是真不喜欢自己就渐渐地和她断了联系正巧那段时间赶上组织架构调整说白了就是人手不够","paragraph":5,"style":"plain","start":191.9,"end":203.32},{"text":"我们子公司要去跟母公司那边帮忙","paragraph":5,"style":"plain","start":203.88,"end":206.86},{"text":"我见不到姐姐了也算物理上的戒断了话虽如此我整个人还是挺失意的那句话怎么说来着一次主动","paragraph":6,"style":"plain","start":207.24,"end":219.7},{"text":"换来了一生的内向虽然有点夸张但那段时间我却是整天都心不在焉的对什么都很抗拒像个三进洞","paragraph":6,"style":"plain","start":219.7,"end":230.96},{"text":"里的叔叔一样母公司那边也有一套软件开发的班子还有一系列的俱乐部活动负责人是我实习期认","paragraph":6,"style":"plain","start":230.96,"end":240.72},{"text":"识的老哥关系挺好，","paragraph":6,"style":"plain","start":240.72,"end":242.84},{"text":"她比较摆烂","paragraph":6,"style":"plain","start":243.48,"end":244.28},{"text":"每次活动饮品都统一点个杨枝甘露啥的成员们怨声载道的有天她有事，","paragraph":7,"style":"plain","start":244.74,"end":251.66},{"text":"就把这吃力不讨好的活儿交给我我在群组里给她们打了个招呼有个女生说想喝点别的我性格也比","paragraph":7,"style":"plain","start":252.18,"end":262.02},{"text":"较摆烂而且经过姐姐的事也没啥心思社交说了一下报销额度既然那个女生跟成员们去统计饮品了","paragraph":7,"style":"plain","start":262.02,"end":271.48},{"text":"我们两个也因此加上了微信饮品比较多嘛那个女生自己拿不过来","paragraph":7,"style":"plain","start":272.26,"end":279.18},{"text":"我作为负责人就跑去跟她一起拿在公司门口见到本人一米六左右穿着小制服戴着胸牌长相挺清秀","paragraph":8,"style":"plain","start":279.18,"end":289.86},{"text":"的回来的时候活动还没开始正巧赶上晚饭的时间我们两个就一起去食堂吃饭然后被部门里一堆已","paragraph":8,"style":"plain","start":289.86,"end":300.14},{"text":"婚的老鸟看见了就跟那旁敲侧击的八卦我刚认识人家女生，","paragraph":8,"style":"plain","start":300.14,"end":305.44},{"text":"感觉有点尴尬她倒不是很在意，还跟那嘀咕饭菜的口味清淡","paragraph":8,"style":"plain","start":305.64,"end":310.84},{"text":"后来我才知道她是湖南人，口重，特别能吃辣所以，","paragraph":9,"style":"plain","start":311.72,"end":316.64},{"text":"就叫她小辣椒吧原本以为两个人之间不会有太多交集但后续的工作中，","paragraph":9,"style":"plain","start":316.913,"end":324.02},{"text":"变成了一个项目的同事是要经常一起沟通项目上的问题久而久之就熟悉了不过我当时倒没啥歪心","paragraph":9,"style":"plain","start":324.36,"end":333.12},{"text":"思甚至还在难过之前被拒的事情","paragraph":9,"style":"plain","start":333.12,"end":336.76},{"text":"有时候人的情绪得不到安慰就想寄托在其他的东西上正巧那阵子我搬出来自己住了所以就在家里","paragraph":10,"style":"plain","start":339.48,"end":348.36},{"text":"养了一只小猫养之前虽然了解过一些常识但毕竟是第一次，","paragraph":10,"style":"plain","start":348.36,"end":354.38},{"text":"还是被猫贩子坑了买了的小猫，","paragraph":10,"style":"plain","start":354.8,"end":357.98},{"text":"有猫瘟和疱疹就是常说的星期猫医生说不一定能救的活就算可以救活，","paragraph":10,"style":"plain","start":358.36,"end":366.18},{"text":"也要花不少钱足够我再买好几只了但我怎么忍心这小生命就这样夭折","paragraph":10,"style":"plain","start":366.42,"end":372.76},{"text":"还是坚持进行了治疗第三天我在加班的时候医生发来消息说小猫的状态很不好可能熬不过今晚我","paragraph":11,"style":"plain","start":373.0,"end":383.7},{"text":"看到立马就六神无主了小辣椒敏锐的发现我不对劲就问我怎么了其实被坑这事吧我自认为挺丢人","paragraph":11,"style":"plain","start":383.7,"end":392.04},{"text":"的但不知道为啥还是一五一十的跟她说了她听完就开始收拾东西说好陪我去见小猫最后一面然后","paragraph":11,"style":"plain","start":392.04,"end":401.84},{"text":"不等我拒绝就已经打好了去宠物医院的车","paragraph":11,"style":"plain","start":401.84,"end":404.76},{"text":"一路上我都心事重重她安慰的话，我也是左耳进右耳出到了医院，看见有出气没进气的小猫，","paragraph":12,"style":"plain","start":405.68,"end":413.8},{"text":"我更崩溃了只好咬着牙，抬着头，不要眼泪流出来她就在旁边静静地陪着我，没有说话","paragraph":12,"style":"plain","start":414.14,"end":422.94},{"text":"医生说差不多就是今晚的事，熬过去就能活临走时，小辣椒突然跟我说她眼神好坚毅啊，","paragraph":13,"style":"plain","start":425.38,"end":434.1},{"text":"感觉一定能活下来的我也看见小猫的眼睛虽然已经很虚弱了但她还是很努力的在睁开双眼看着我","paragraph":13,"style":"plain","start":434.58,"end":444.06},{"text":"们和这个还没有体验过的世界因为加班嘛又去了宠物医院时间已经很晚了所以我就打车送小辣椒","paragraph":13,"style":"plain","start":444.06,"end":453.24},{"text":"回家一路上她又在安慰我尽量让我好受一点","paragraph":13,"style":"plain","start":453.24,"end":457.62},{"text":"她下车以后司机突然问了一句还没在一起吧我说我们就是同事司机嘿嘿一笑说，","paragraph":14,"style":"plain","start":458.94,"end":467.16},{"text":"人家小姑娘好像对你有意思。","paragraph":14,"style":"plain","start":467.7,"end":469.66},{"text":"我也没有接话。","paragraph":14,"style":"plain","start":470.76,"end":471.72},{"text":"那天晚上我没怎么睡觉，一方面医院那边会随时给我发小猫的状态。","paragraph":14,"style":"plain","start":472.64,"end":478.22},{"text":"我就怕一睁眼看到不好的消息。","paragraph":15,"style":"plain","start":478.96,"end":481.08},{"text":"另一方面小辣椒热情又温柔的样子，也一直在我的脑海里挥之不去。","paragraph":15,"style":"plain","start":481.92,"end":487.12},{"text":"万幸的是，小猫成功挺过来了后续经过治疗，","paragraph":15,"style":"plain","start":488.4,"end":492.48},{"text":"也顺利的出了院还是小辣椒跟我一起去接了她事情都在向好的方向发展这件事以后，","paragraph":15,"style":"plain","start":492.76,"end":501.62},{"text":"我和小辣椒的关系就愈发亲近节假日会一起出去玩时不时她还会来我家看看小猫会不会后空翻什","paragraph":15,"style":"plain","start":502.0,"end":511.07},{"text":"么的","paragraph":15,"style":"plain","start":511.07,"end":511.76},{"text":"她乐此不疲的想把我改造成一个能吃辣的人每次出去玩，吃的要么是川菜，","paragraph":16,"style":"plain","start":512.44,"end":518.68},{"text":"要么是湘菜甚至还送我一堆那种爆辣的小零食先不说我一个江浙沪长大的能不能吃的惯反正上厕","paragraph":16,"style":"plain","start":519.2,"end":528.5},{"text":"所是没少遭罪我们公司是提倡内部解决的同时那些老鸟嗅到恋爱的酸臭味也在有意无意的撮合我","paragraph":16,"style":"plain","start":528.5,"end":539.44},{"text":"俩经过上次那事以后，","paragraph":16,"style":"plain","start":539.44,"end":542.06},{"text":"我心里确实有点忐忑担心自己又是一厢情愿","paragraph":16,"style":"plain","start":542.6,"end":546.84},{"text":"就想着还是先随缘吧随后那段时间又经历了一次组织架构的调整我们部门有些成员离职加上我的","paragraph":17,"style":"plain","start":547.38,"end":558.2},{"text":"工作能力得到了领导的认可就开始分配我一些独立的项目工作变忙我和小辣椒相处的时间就变少","paragraph":17,"style":"plain","start":558.2,"end":566.72},{"text":"一起出去玩的时间就更少有时候我周末也要来公司赶项目进度基本上就在公司见见面，","paragraph":17,"style":"plain","start":567.26,"end":575.14},{"text":"其他时间就只在微信上聊聊天","paragraph":17,"style":"plain","start":575.72,"end":578.28},{"text":"有天难得下班比较早，我们两个久违地一起吃了顿晚饭吃饭的时候，她冷不丁地问了一句，","paragraph":18,"style":"plain","start":579.46,"end":586.9},{"text":"你有没有谈恋爱的想法我一时间愣住了，看着面前略显羞涩和期待的姑娘最后还是回她说，","paragraph":18,"style":"plain","start":587.56,"end":596.9},{"text":"这也不是我想谈就能谈的事儿小辣椒却一脸正经地问我说你知不知道人类是从什么时候开始进化","paragraph":18,"style":"plain","start":597.8,"end":606.28},{"text":"的我不懂她为什么突然问这个摇个摇头她说","paragraph":18,"style":"plain","start":606.28,"end":611.66},{"text":"是从第一只猴子抬头仰望星空的那一刻我其实也看过2001太空漫游但没想到她会说这个答案","paragraph":19,"style":"plain","start":612.44,"end":622.8},{"text":"小辣椒平时挺感性的以至于我差点忘了她也是个理科生很巧的是那天晚上的夜空很清晰我们就没","paragraph":19,"style":"plain","start":623.36,"end":633.99},{"text":"有坐车回家一路上都仰着脑袋给对方说着自己都不太清楚的星星我们的关系虽然没有更进一步但","paragraph":19,"style":"plain","start":633.99,"end":644.38},{"text":"保持在目前的阶段感觉也挺好我也在逐渐地打开自己","paragraph":19,"style":"plain","start":644.38,"end":649.2},{"text":"而让我们真正下定决心的是后面发生的一件事不出意外的公司再次迎来了组织架构调整子公司那","paragraph":20,"style":"plain","start":649.84,"end":660.22},{"text":"边又来了一批人比较俗套的是这批人当中却有我当初认识的姐姐虽然不在一个部门但难免会低头","paragraph":20,"style":"plain","start":660.22,"end":671.14},{"text":"不见抬头见两个人都很尴尬甚至连招呼都没打过但当初跟我一起调聊的同事却嘴欠的把这个事儿","paragraph":20,"style":"plain","start":671.14,"end":680.06},{"text":"给说漏了小辣椒知道以后她没什么太大的反应","paragraph":20,"style":"plain","start":680.06,"end":683.86},{"text":"甚至还跑到我面前主动问这事我寻思也不是什么见不得人的事，就跟她说了。","paragraph":21,"style":"plain","start":684.34,"end":690.56},{"text":"她听了就有一个劲地笑话，说我都被人家钓成翘嘴了，然后又有一脸坏笑的问我说，","paragraph":21,"style":"plain","start":691.21,"end":697.76},{"text":"你想不想让她也难受一下。","paragraph":21,"style":"plain","start":698.46,"end":699.9},{"text":"我隐约感觉到她想干什么，就说，你别搞，我们这件事早就完了。","paragraph":22,"style":"plain","start":700.94,"end":706.06},{"text":"但她还是一脸坏笑的说，瞧好吧你。","paragraph":22,"style":"plain","start":707.2,"end":710.08},{"text":"然后第二天在食堂吃饭的时候，她就拉着我在姐姐能看到的地方，","paragraph":22,"style":"plain","start":711.4,"end":715.9},{"text":"故意搞得跟小情侣似的又是给我打饭又是给我夹菜啥的姐姐看没看到我不知道旁边的同事都看在","paragraph":22,"style":"plain","start":716.3,"end":725.72},{"text":"眼里搞得我浑身不自在但看着小辣椒在那忙前忙后的心里还是暖暖的","paragraph":22,"style":"plain","start":725.72,"end":732.46},{"text":"像是午后的阳光洒在身上的感觉那一刻我才明白一个人真的喜欢你是什么样子的其实这就是一个","paragraph":23,"style":"plain","start":732.96,"end":743.48},{"text":"小插曲没什么三方对峙的修罗场只不过姐姐好像没吃两口就走了之后还是像陌生人一样没有任何","paragraph":23,"style":"plain","start":743.48,"end":753.04},{"text":"交集我和小辣椒的关系倒是越来越好天气逐渐暖和工作节奏也恢复了正常我们两个就像之前一样","paragraph":23,"style":"plain","start":753.04,"end":764.42},{"text":"经常出去玩有天放假我们两个一起出来爬山踏青","paragraph":23,"style":"plain","start":764.76,"end":769.24},{"text":"整天坐在电脑前吗没微一点运动量刚开始还能用脚走到后来就手脚并用的往上爬看它有点虚脱的","paragraph":24,"style":"plain","start":769.8,"end":781.44},{"text":"样子我就有点后悔自己爬山的决定小辣椒就表示没有关系说既然来爬山就要有点爬山的觉悟那天","paragraph":24,"style":"plain","start":781.44,"end":791.34},{"text":"是中午出来的爬到山顶的时候天已经很黑了风很大山下的城市的夜景被压缩成一片遂冷的光斑和","paragraph":24,"style":"plain","start":791.34,"end":801.92},{"text":"山顶漆黑的环境形成鲜明的对比","paragraph":24,"style":"plain","start":801.92,"end":804.56},{"text":"如同在一万年前的史前世界遥望未来一样我们两个并排坐着闲聊的时候说到个姐姐的事小辣椒还","paragraph":25,"style":"plain","start":805.32,"end":815.18},{"text":"挺得意的跟我邀功说姐姐肯定难受坏的我转头看了她一眼就觉得对我来说已经不重要了身旁这个","paragraph":25,"style":"plain","start":815.18,"end":824.66},{"text":"热情又有点辛辣的姑娘才是最重要的所以我画风一转，","paragraph":25,"style":"plain","start":824.66,"end":829.98},{"text":"对她说，那全公司都把我们当成情侣了，怎么办？","paragraph":25,"style":"plain","start":830.38,"end":834.92},{"text":"她先是一愣，然后一改之前的样子，有点不好意思地反问我，那你说怎么办呢？","paragraph":26,"style":"plain","start":836.28,"end":843.5},{"text":"我说，同事跟我打了个赌，如果咱俩能在一起，她就把显示器吃了。","paragraph":26,"style":"plain","start":844.32,"end":849.92},{"text":"她扑哧一下笑了，说，她就是骗吃骗喝，然后又转头认真地问我，那你想赢吗？","paragraph":26,"style":"plain","start":850.29,"end":858.94},{"text":"我深吸了一口气，回答道，赢不赢无所谓，我只知道我喜欢你。","paragraph":27,"style":"plain","start":860.1,"end":866.16},{"text":"他没有跟我回答，而是抬起头看着闪烁的群星说，天上还有那么多星星呢。","paragraph":27,"style":"plain","start":867.24,"end":873.88},{"text":"我也跟着抬起头，没有灯光的污染，","paragraph":27,"style":"plain","start":874.96,"end":877.96},{"text":"深淋的星星比城市里看到的还要清晰甚至还有许久没有见过的银河但看了一眼我又把目光落回到","paragraph":27,"style":"plain","start":878.26,"end":889.24},{"text":"她身上以字一句的说但我已经找到了自己最爱的那一颗","paragraph":27,"style":"plain","start":889.24,"end":895.8},{"text":"后来我也问过小辣椒说你会不会觉得我是别人不要的她白了我一眼说我一个大男人在矫情什么但","paragraph":28,"style":"plain","start":897.24,"end":908.1},{"text":"紧接着又抱着我回答道喜欢你的人只会觉得你是最宝贵的","paragraph":28,"style":"plain","start":908.1,"end":916.5},{"text":"俗话说得好宝宝喊的好招财又进宝宝宝喊得溜健康又长寿喜欢一个人呢就要一直喊她宝宝一直喊","paragraph":29,"style":"plain","start":923.26,"end":937.5},{"text":"到，","paragraph":29,"style":"plain","start":937.94,"end":938.0},{"text":" 她是你的宝宝为止。","paragraph":29,"style":"plain","start":938.38,"end":939.86},{"text":"宝宝早安，宝宝晚安，好的宝宝，是的宝宝，听你的宝宝，迷湖宝宝，迷湖宝宝。","paragraph":29,"style":"plain","start":940.78,"end":950.74},{"text":"呵呵，晚安啦，迷湖宝宝，做个好梦？","paragraph":30,"style":"plain","start":951.18,"end":955.1}]},{"id":"sweet-duo","title":"甜蜜双排","category":"story","sequence":11,"duration":1172.819592,"audio":"sweet-duo.mp3","palette":["#465a4f","#7b6952"],"cues":[{"text":"我觉得玩游戏这事儿就要怎么开心怎么来。","paragraph":0,"style":"plain","start":2.48,"end":5.9},{"text":"就像著名主播五五开说的，玩游戏一定要笑。","paragraph":0,"style":"plain","start":6.82,"end":10.98},{"text":"有些人玩游戏喜欢挑战难度，有些人喜欢慢慢经营。","paragraph":0,"style":"plain","start":12.72,"end":17.46},{"text":"对我来说，混就是最开心的游戏方式。","paragraph":0,"style":"plain","start":18.34,"end":21.6},{"text":"这事儿应该跟我小时候的财务状况有关系那时候没钱玩游戏只能站在后面看人玩所以到了现在我","paragraph":1,"style":"plain","start":23.2,"end":32.04},{"text":"也喜欢玩个瑶、","paragraph":1,"style":"plain","start":32.04,"end":33.47},{"text":"猫咪之类的角色多少有点参与感就行当然混也是讲究方式方法的想赢游戏就得知道这一局的大哥","paragraph":1,"style":"plain","start":33.82,"end":43.24},{"text":"是谁所以每当我抛下AD跟人跑的时候总会收到一系列的问候所以每局当我想混的时候进游戏的","paragraph":1,"style":"plain","start":43.24,"end":53.64},{"text":"第一件事就是屏蔽队友","paragraph":1,"style":"plain","start":53.64,"end":55.58},{"text":"我跟她就是在这种情况下认识的最开始我真以为她是个男生主要是她玩个猴子ID还叫熊猫在燃","paragraph":2,"style":"plain","start":56.42,"end":65.5},{"text":"烧我的小脑容量有限实在想不到什么女生会起这样的名字后来她说自己也有同样的困惑一个大老","paragraph":2,"style":"plain","start":65.58,"end":75.7},{"text":"爷们怎么会叫爱因斯坦我就故意恶心地说嘤嘤嘤不可爱吗她说你滚你是真不要脸总之那局她的猴","paragraph":2,"style":"plain","start":75.7,"end":87.24},{"text":"子有我的瑶加持狂砍16个人头那个时候","paragraph":2,"style":"plain","start":87.24,"end":91.28},{"text":"我还是把她当男生嘛就故意用女生的语气说话结束游戏我直接就是一通狂舔啊 你好厉害能不能","paragraph":3,"style":"plain","start":91.28,"end":100.78},{"text":"带我一个呀句末还带着那种可爱的颜文字果然没一会儿就收到了组队邀请然后进去一看除了她还","paragraph":3,"style":"plain","start":100.78,"end":112.03},{"text":"有三个人全是女生我当时还心想哥们儿你可真行随手就整了四个妹子","paragraph":3,"style":"plain","start":112.03,"end":119.4},{"text":"然后就理所当然的输了没办法一局游戏里除了她全是混子真是赢不了一点后来就一直输但熊猫哥","paragraph":4,"style":"plain","start":121.6,"end":131.62},{"text":"的战绩还是很好的我怕自己的身份暴露就没开麦她也没开就打打自杀的其他三个女生一直输怨气","paragraph":4,"style":"plain","start":131.62,"end":142.34},{"text":"很大就在语音里互相甩锅吵起来了我本身就是乐子人在旁边听着嘎嘎笑太有意思了有时候还不过","paragraph":4,"style":"plain","start":142.34,"end":152.7},{"text":"拱火说两句哎呀 她不就是吃个蓝吗","paragraph":4,"style":"plain","start":152.7,"end":156.02},{"text":"哎呀 她不就是吃个红吗这三人越来越气后来就都走了只剩下我和熊猫哥双排虽然之前一直输啊","paragraph":5,"style":"plain","start":156.56,"end":166.68},{"text":"但她明显不是我这个钻石分段的一个人还在嘎嘎乱杀我一问大号好家伙荣耀王者跟他们钻石都是","paragraph":5,"style":"plain","start":166.68,"end":176.6},{"text":"混上来的后来就一直跟熊猫哥双排嘛我发现她脾气很好是真的好你有什么失误她都不说自己死了","paragraph":5,"style":"plain","start":176.6,"end":187.36},{"text":"也不给你上压力即使输了","paragraph":5,"style":"plain","start":187.36,"end":189.66},{"text":"我跟她的游戏体验也非常nice所以那段时间每次熊猫哥在线我都会抓她玩就算她在对局里我","paragraph":6,"style":"plain","start":189.76,"end":198.81},{"text":"也要等她结束这一来二去的我俩就变成了固定队友说起来那个时候我还有点愧疚我以为她是男的","paragraph":6,"style":"plain","start":198.81,"end":208.52},{"text":"嘛然后我以女号就感觉挡住了很多的桃花我倒没有故意骗人她没问我也没必要特意说是吧直到后","paragraph":6,"style":"plain","start":208.52,"end":218.88},{"text":"来有一次她状态差队友就一个劲的在语音里哔哔","paragraph":6,"style":"plain","start":218.88,"end":222.76},{"text":"我这人就是朋友被骂比骂我还难受再加上我也想表达自己是男生的身份就直接一个激情开麦大喷","paragraph":7,"style":"plain","start":223.56,"end":231.58},{"text":"四方没想到对面还有高手老子一喷三遗憾落败不过那局游戏倒是赢了对局一出来熊猫哥就给我发","paragraph":7,"style":"plain","start":231.58,"end":242.0},{"text":"消息玩了这么久才知道你是男的我以为她要弃我而去，","paragraph":7,"style":"plain","start":242.0,"end":247.26},{"text":"就回复她说，兄弟，你不会要丢下我吧？","paragraph":7,"style":"plain","start":247.78,"end":250.92},{"text":"她文字中带着点调笑的语气回答，不能，我还需要你帮我骂人呢？","paragraph":8,"style":"plain","start":251.88,"end":256.48},{"text":"我发了个努力的表情，行，以后看我操作。","paragraph":8,"style":"plain","start":257.26,"end":260.42},{"text":"那天以后，我们就开麦交流了。","paragraph":8,"style":"plain","start":261.38,"end":263.46},{"text":"感觉和她的关系变亲近了很多，平时都是我找她玩，现在她也会来找我玩。","paragraph":8,"style":"plain","start":264.32,"end":270.5},{"text":"但她始终没有开麦说过话，我也没有多想，","paragraph":9,"style":"plain","start":271.16,"end":273.92},{"text":"想着可能就是不方便呗小时候的玩伴基本都搁扁东西了所以我其实还挺喜欢在游戏里交朋友的对","paragraph":9,"style":"plain","start":274.52,"end":284.26},{"text":"局中玩带来的我基本都会邀请下一把但林子大了什么鸟都有在互联网上能一起相处的也没几个所","paragraph":9,"style":"plain","start":284.31,"end":293.26},{"text":"以我和熊猫哥就加上了微信","paragraph":9,"style":"plain","start":293.26,"end":295.2},{"text":"第一眼我就看到了一个醒目的粉色小人头像顶着个可爱的小猫我心想 哥们儿你玩得挺变态逛了","paragraph":10,"style":"plain","start":297.52,"end":306.68},{"text":"一下朋友圈 倒啥也没发现三天可见啥也没有紧接着 熊猫哥那边发来消息女玩的游戏挺多呀她","paragraph":10,"style":"plain","start":306.68,"end":316.84},{"text":"这么一说 我就知道她也翻我朋友圈了鄙人不才 也没什么别的爱好工作两三年 女朋友一个没","paragraph":10,"style":"plain","start":316.84,"end":324.86},{"text":"谈就攒钱买设备玩游戏了所以我就回覆她说","paragraph":10,"style":"plain","start":325.18,"end":329.46},{"text":"兄弟有空来旅游 保你玩到爽她也顺嘴问我在那我说北京她调侃闹呼还是个正红旗我发了个哭笑","paragraph":11,"style":"plain","start":329.86,"end":340.34},{"text":"的表情哪儿啊就是个苦逼的北漂打工人在那之后我们就开始在微信上交流了但也仅限游戏方面比","paragraph":11,"style":"plain","start":340.34,"end":350.49},{"text":"如分析一下新出的英雄分享一些整活的游戏视频啥的熊猫哥也玩过很多游戏聊很多东西也没啥障","paragraph":11,"style":"plain","start":350.49,"end":359.38},{"text":"碍大概过去两三个月吧疫情反反复复的好转了一些","paragraph":11,"style":"plain","start":359.38,"end":364.46},{"text":"公司要开展南方的销售市场我那段时间就总需要出差跑下游的销售渠道所以连好几天都抽不出时","paragraph":12,"style":"plain","start":365.14,"end":373.55},{"text":"间来玩游戏每天都很累还要和我那个小领导睡同一个房间更没有办法玩游戏了熊猫哥有天就在微","paragraph":12,"style":"plain","start":373.55,"end":383.54},{"text":"信上找到我问我这些日子怎么没上线我看着旁边鼾声震天的小领导心里一阵苦水哎 别提了 受","paragraph":12,"style":"plain","start":383.54,"end":393.12},{"text":"刑了她发了一个问号我就大概说了一下情况","paragraph":12,"style":"plain","start":393.12,"end":397.42},{"text":"然后熊猫哥说她就在我出差的城市周末有时间的话可以面基一下我当时没多想什么就有点诧异两","paragraph":13,"style":"plain","start":397.88,"end":407.66},{"text":"男的有啥可面的我又不是来旅游的但也没推辞到了周末的时候我晃晃悠悠的来到了约定地点在商","paragraph":13,"style":"plain","start":407.66,"end":417.5},{"text":"场转了一圈也没看到其他等人的男生这时候向我走来一个戴着黑口罩 黑帽子浑身上下一身黑的","paragraph":13,"style":"plain","start":417.5,"end":426.26},{"text":"女生我隐约有种预感心想不会吧 不会吧","paragraph":13,"style":"plain","start":426.26,"end":431.94},{"text":"直到她也走到我面前跟我说了第一句话请出示你的绿码我愣在原地 半天说不出话最后掏出了手","paragraph":14,"style":"plain","start":432.58,"end":442.28},{"text":"机她看到绿码上的照片就有一个劲地笑说我拍得好丑我真是服了哥们出差的这几天造得跟鬼似的","paragraph":14,"style":"plain","start":442.28,"end":451.78},{"text":"而且根本没带像样的衣服穿着一身工作服差不多就是个楼盘销售的形象她现在我不说话又笑着说","paragraph":14,"style":"plain","start":451.78,"end":460.5},{"text":"没想到我是女生吗我还是没说话就点了点头她歪着脑袋","paragraph":14,"style":"plain","start":460.9,"end":467.32},{"text":"仔细瞧着我评价到你跟照片上不太一样啊我知道她言外之意是说我丑就镇定了一下骄傲地说什么","paragraph":15,"style":"plain","start":467.32,"end":478.1},{"text":"年代了男生就不能美颜一下吗她又笑了起来带着口罩虽然看不清具体的样子但露出的眼睛笑起来","paragraph":15,"style":"plain","start":478.1,"end":487.18},{"text":"还挺好看的我现在都记得那天吃的是椰子鸡因为后来我特别喜欢这道菜吃饭的时候她摘下了口罩","paragraph":15,"style":"plain","start":487.18,"end":496.22},{"text":"我也终于看清了她的样子不知道该怎么描述","paragraph":15,"style":"plain","start":496.62,"end":500.36},{"text":"就是那种很水乡的长相一看就知道是南方人我虽然跟她认识也好几个月了但聊的基本都是游戏相","paragraph":16,"style":"plain","start":500.8,"end":511.06},{"text":"关的东西所以对她的了解不能说是没有只能说是没有一点原本我以为熊猫哥是个沉默寡言的酷盖","paragraph":16,"style":"plain","start":511.06,"end":519.5},{"text":"但没想到见面以后是个活泼爱笑的妹子所以我就更好奇她那个熊猫在人上的ID是有哪个脑子起","paragraph":16,"style":"plain","start":520.0,"end":528.21},{"text":"的她就学着我的话术说嘤嘤嘤不可爱吗我看着她回答","paragraph":16,"style":"plain","start":528.3,"end":535.1},{"text":"可爱呢她看着鸡爪嘿嘿一笑她比我小一岁好像是个画师平时打游戏看动漫也算是工作上的合理摸","paragraph":17,"style":"plain","start":535.5,"end":546.28},{"text":"鱼就这样维言台语本来有些陌生的感觉也慢慢变少熊猫哥概念化的形象也在我脑中逐渐清晰变成","paragraph":17,"style":"plain","start":546.34,"end":556.86},{"text":"了面前的姑娘吃完饭我们就到处瞎逛因为她其实不在这个城市生活只是离得不远高铁一个小时的","paragraph":17,"style":"plain","start":556.86,"end":566.16},{"text":"距离我知道后心里就挺开心的半开玩笑的问她","paragraph":17,"style":"plain","start":566.16,"end":570.32},{"text":"那你是特地来见我的呗她白了我一眼回答想得美我就是正好周末出来玩我打趣道傲娇已经退环境","paragraph":18,"style":"plain","start":570.98,"end":580.48},{"text":"了南方夏天又闷又热晚上也没有一丝凉意熊猫哥完全没有回家的意思还在我下榻的酒店开了个房","paragraph":18,"style":"plain","start":580.48,"end":590.7},{"text":"间说明天要跟我送行我那个小领导已经提前回北京了天气太热我们就点个外卖在酒店对付一口吃","paragraph":18,"style":"plain","start":590.7,"end":601.0},{"text":"完了她就在房间里跟我一起打游戏孤男寡女共处一室","paragraph":18,"style":"plain","start":601.0,"end":605.96},{"text":"空气里的味道都有点不对劲了以前我觉得玩游戏是最开心的事但她在我旁边怎么就不香了呢难怪","paragraph":19,"style":"plain","start":606.4,"end":616.12},{"text":"以前朋友谈恋爱了就不玩游戏了感情是有更好玩的东西我赶紧把这种想法驱逐出境滚出我的脑袋","paragraph":19,"style":"plain","start":616.12,"end":625.68},{"text":"谈恋爱怎么可能比游戏好玩不可能 绝对不可能我有些心不在焉 状态就很差熊猫哥倒是稳定发","paragraph":19,"style":"plain","start":626.2,"end":635.4},{"text":"挥然后我脑子里闪过一个想法旁敲侧击的问","paragraph":19,"style":"plain","start":635.4,"end":639.9},{"text":"你游戏打得这么好男朋友会不会自卑呀我没有男朋友她回答得干净利落然后又反问我那你打得这","paragraph":20,"style":"plain","start":640.42,"end":649.72},{"text":"么差女朋友会不会嫌弃你我在游戏里打了个问号然后说怎么还人身攻击呢那你有女朋友吗她有些","paragraph":20,"style":"plain","start":649.72,"end":659.5},{"text":"认真地问没有我也认真的回答","paragraph":20,"style":"plain","start":659.57,"end":662.66},{"text":"然后就是一段很长的沉默房间里只有游戏的声音就是那种又尴尬也有点心动的感觉我鼓起勇气进","paragraph":21,"style":"plain","start":664.5,"end":674.48},{"text":"一步试探你来见我前不怕我是个坏人吗她说你游戏都打不过我哎 我心里这个气呀有时候我真希","paragraph":21,"style":"plain","start":674.48,"end":684.73},{"text":"望自己是个坏人她没抬头 手上玩的游戏其实说我知道你不是所以才敢见你呢王者果然是王者我","paragraph":21,"style":"plain","start":684.73,"end":696.08},{"text":"是真的打不过我们后来又玩了一会时间不早了","paragraph":21,"style":"plain","start":696.08,"end":700.74},{"text":"就回房间休息一个人躺在床上我就开始了头脑风暴半天也睡不着最后就拿出手机把机票从中午改","paragraph":22,"style":"plain","start":700.74,"end":711.3},{"text":"到了晚上临走的时候她把我送到了机场还拥抱了一下南方真是太热了热的我都有点走不动到下了","paragraph":22,"style":"plain","start":711.3,"end":721.5},{"text":"飞机我就收到她问候的消息心里美滋滋的有种被人惦念的感觉这次见面后，","paragraph":22,"style":"plain","start":721.5,"end":729.38},{"text":"熊猫哥玩游戏也会开麦了。","paragraph":22,"style":"plain","start":729.76,"end":731.6},{"text":"微信上的话题也从游戏聊到的生活。","paragraph":23,"style":"plain","start":732.18,"end":735.44},{"text":"她有什么大大小小的事情都会跟我分享。","paragraph":23,"style":"plain","start":736.0,"end":738.72},{"text":"我每天最期待的时候也是加班后跟她一起的时间。","paragraph":23,"style":"plain","start":739.54,"end":743.12},{"text":"有时候也不玩游戏，就开着语音聊天，或者各自忙点手头上的事情。","paragraph":23,"style":"plain","start":744.16,"end":749.24},{"text":"这种说不清的关系一直持续到一场游戏，其实还挺俗套的。","paragraph":24,"style":"plain","start":750.42,"end":755.8},{"text":"打排位的时候，我们一般都开着队友的语音嘛。","paragraph":24,"style":"plain","start":756.56,"end":760.1},{"text":"有个男生就一直在搭讪熊猫哥。","paragraph":24,"style":"plain","start":760.8,"end":763.02},{"text":"我越听越气，越听越气，就跟她说，好好玩游戏，别瞎扯淡。","paragraph":24,"style":"plain","start":763.72,"end":768.94},{"text":"她一听还来劲了，就问我，她是你女朋友啊。","paragraph":25,"style":"plain","start":770.18,"end":773.46},{"text":"我在气头上，就理所当然地说了句，是。","paragraph":25,"style":"plain","start":774.34,"end":777.34},{"text":"然后这傻逼就说了句贼恶心的话，你有守门员还进球呢？","paragraph":25,"style":"plain","start":778.54,"end":782.52},{"text":"我更生气了就阴阳怪气地怼了回去咋的你就是没守住生出来的吧对方气急败坏破口大骂我就把语","paragraph":25,"style":"plain","start":783.14,"end":793.0},{"text":"音里关了倒不是不想骂回去主要是熊猫哥还在呢我想矜持点不然早就问候他全家了游戏出来","paragraph":25,"style":"plain","start":793.0,"end":802.26},{"text":"熊猫哥就一个劲地笑说我的嘴真的是毒完全没有反驳我的意思好像默认了我们之间的关系我听着","paragraph":26,"style":"plain","start":802.26,"end":811.38},{"text":"对面传来的笑声就一瞬间确定了自己的心意不出意外的话我这辈子应该都找不到这么合拍这么喜","paragraph":26,"style":"plain","start":811.38,"end":819.86},{"text":"欢的人了他见我半天没说话以为我还在生气问我怎么了我回过神马上跟他说没事然后转头就订了","paragraph":26,"style":"plain","start":819.86,"end":830.24},{"text":"周末的机票因为这么重要的事我想跟她当面说","paragraph":26,"style":"plain","start":830.24,"end":834.04},{"text":"周末我起了个大早倒不是因为我着急实在是早晨的机票便宜很多到了酒店又补了一觉因为晚上头","paragraph":27,"style":"plain","start":835.42,"end":844.4},{"text":"脑风暴根本没睡好睁开眼睛已经是下午三点钟了手机上一堆熊猫哥的消息我收拾了一下把头发梳","paragraph":27,"style":"plain","start":844.4,"end":854.76},{"text":"成了大人模样穿上了一身帅气衣服然后又在附近的花店搞了一束花折腾的一圈下来就到了傍晚之","paragraph":27,"style":"plain","start":854.76,"end":865.54},{"text":"前有送过熊猫哥礼物所以我知道她在大概的位置","paragraph":27,"style":"plain","start":865.54,"end":869.02},{"text":"然后就在小区门口发微信说快递到了想骗她出来过了一会儿熊猫哥回覆说自己不在家我想说那就","paragraph":28,"style":"plain","start":869.72,"end":879.56},{"text":"等你回来呗请接着她就发了一个定位我一看北京我一阵无语然后把自己的定位也发了过去她一阵","paragraph":28,"style":"plain","start":879.56,"end":890.2},{"text":"无语我问你去北京干嘛她说找你呀她又反问我我也回答说 找你呀某种程度上说 这也算是双向","paragraph":28,"style":"plain","start":890.2,"end":901.58},{"text":"的奔赴吧我在原地苦笑 然后撂下一句等我","paragraph":28,"style":"plain","start":901.64,"end":906.26},{"text":"又火急火燎的去赶飞机我就这样手里拿着鲜花 在所有乘客的注视下又飞回了北京等到落地的时","paragraph":29,"style":"plain","start":906.88,"end":915.493},{"text":"候 已经快凌晨12点了大兴机场的出口是真的远现在感觉就更远了我风风火火地赶到出口就看","paragraph":29,"style":"plain","start":915.493,"end":926.12},{"text":"到她拿着手机一边笑一边拍我我是怎么也想不到有一天她会在北京给我接机","paragraph":29,"style":"plain","start":926.12,"end":933.44},{"text":"不知道你有没有被人送过花虽然这是一件比较有仪式感的事但送的人是真的真的好尴尬尤其是出","paragraph":30,"style":"plain","start":935.3,"end":944.22},{"text":"口还有一堆人看着不过最后我还是把一路上小心翼翼保藏的鲜花送给她了我们随便聊聊两句什么","paragraph":30,"style":"plain","start":944.34,"end":953.72},{"text":"等多久了 吃没吃饭但都没问对方为什么会来因为答案既明显又尴尬然后她问我说回我的酒店还","paragraph":30,"style":"plain","start":953.72,"end":963.86},{"text":"去你家里虽然我们俩人的关系已经心照不宣了","paragraph":30,"style":"plain","start":963.86,"end":968.24},{"text":"但听到这样的话还是很上头我心里一咬牙一跺脚表面淡定地说去我家吧她就点点头 然后跟着我","paragraph":31,"style":"plain","start":968.74,"end":979.56},{"text":"网约中的地方还有一段距离机场人来人往的，","paragraph":31,"style":"plain","start":980.42,"end":984.42},{"text":"我下意识的伸出手，就很自然地牵到了她，她也拉着我的手。","paragraph":31,"style":"plain","start":984.72,"end":989.64},{"text":"我们一路上了叫好的网约车，在车里我们的手也没松开，青涩得像是回到的学生时代，","paragraph":32,"style":"plain","start":991.38,"end":998.68},{"text":"但又比那时多了一些成年人之间的情愫。","paragraph":32,"style":"plain","start":999.44,"end":1002.63},{"text":"我在郊区租了一个不大不小的一居室，虽然通勤不太方便，但好在住着舒服。","paragraph":32,"style":"plain","start":1003.26,"end":1008.9},{"text":"前两天刚打扫过卫生，所以家里也不算太乱。","paragraph":33,"style":"plain","start":1009.54,"end":1012.7},{"text":"熊猫哥说了，她想先洗个澡。","paragraph":33,"style":"plain","start":1013.31,"end":1015.5},{"text":"折腾的一天，身上太难受了，然后就拿着睡衣进了浴室。","paragraph":33,"style":"plain","start":1016.22,"end":1020.56},{"text":"我听着里面哗哗的洗澡声，反而有一种平静感。","paragraph":33,"style":"plain","start":1021.36,"end":1024.7},{"text":"她洗完我洗嘛，出来就看到她在玩我的游戏机。","paragraph":34,"style":"plain","start":1025.68,"end":1029.2},{"text":"我就坐到了她的旁边，拿起一个手柄，跟她一起玩，还能闻到她身上刚洗完澡的味道。","paragraph":34,"style":"plain","start":1030.0,"end":1036.56},{"text":"我真的很喜欢这样的氛围所以就看着屏幕说跟你这样待在一起感觉真好屏幕里她的角色停止了行","paragraph":34,"style":"plain","start":1037.42,"end":1046.9},{"text":"动然后我就感觉什么东西靠在我的手臂上转头发现她在看着我眼睛里映着着屏幕的余光对我说我","paragraph":34,"style":"plain","start":1046.9,"end":1057.4},{"text":"也是","paragraph":34,"style":"plain","start":1057.4,"end":1057.7},{"text":"我们离得太近了甚至能感觉到她温热的呼吸我忍不住低下头亲了她一下她惊讶了一秒然后把头埋","paragraph":35,"style":"plain","start":1058.68,"end":1070.28},{"text":"在我的肩膀上小声地说还说自己不是坏人我靠着她的脑袋心砰砰地乱跳手上还抓着手柄好像本能","paragraph":35,"style":"plain","start":1070.28,"end":1081.66},{"text":"的不愿打破这种平静一样我就在她耳边也有很小的声音说我喜欢你这之后的故事其实也没什么可","paragraph":35,"style":"plain","start":1081.66,"end":1092.48},{"text":"说的了我和她经历了一段时间的异地恋","paragraph":35,"style":"plain","start":1092.48,"end":1095.36},{"text":"最后选了个我们都喜欢的城市刚搬过去的时候还碰上了疫情最严重的时候我们俩人在家里封了好","paragraph":36,"style":"plain","start":1096.22,"end":1105.16},{"text":"几个月不过幸好我们都是比较宅的类型所以每天在家工作 玩游戏还挺开心的当然 我知道最该","paragraph":36,"style":"plain","start":1105.16,"end":1116.18},{"text":"关心的不是这个对此我只能说熊猫哥是一个大骗子本人跟ID一点关系都没有","paragraph":36,"style":"plain","start":1116.18,"end":1124.34},{"text":"宝宝你身上好香啊我可以靠你近一点吗","paragraph":37,"style":"plain","start":1132.1,"end":1136.28},{"text":"我凑近闻一下可以吗你用的什么香水啊真的好好闻啊我可以抱着你吗？","paragraph":38,"style":"plain","start":1139.2,"end":1148.5},{"text":"哇，你怎么比我白这么多呀？","paragraph":38,"style":"plain","start":1149.16,"end":1152.66},{"text":"我们都不是一个颜色，我们比一比吗？","paragraph":38,"style":"plain","start":1153.54,"end":1157.42},{"text":"你的手好小啊，听说女生的手都很软我可以牵一下你吗？","paragraph":38,"style":"plain","start":1158.96,"end":1167.2},{"text":"你真的好可爱啊，迷湖宝宝","paragraph":39,"style":"plain","start":1168.18,"end":1171.28}]},{"id":"sugar-in-dreams","title":"梦里有糖","category":"story","sequence":12,"duration":1256.829388,"audio":"sugar-in-dreams.mp3","palette":["#485f52","#726451"],"cues":[{"text":"人总是会对未知的事情充满期待。","paragraph":0,"style":"plain","start":1.8,"end":4.44},{"text":"尤其是当你为了她苦熬十多年。","paragraph":0,"style":"plain","start":5.36,"end":7.92},{"text":"所以刚上大学那会儿，看着大城市和落落的校区，以及天南海北汇集于此的同学们，","paragraph":0,"style":"plain","start":8.76,"end":16.42},{"text":"我真是跃跃欲试。","paragraph":0,"style":"plain","start":17.0,"end":18.568},{"text":"各种活动选修啥的能报的就报了心里也期待着能在美好的大学校园里邂逅一场不期而遇不约而同","paragraph":0,"style":"plain","start":18.86,"end":29.32},{"text":"的不谋而合的恋爱但很多东西等真的进入到生活中后慢慢也就祛魅了","paragraph":0,"style":"plain","start":29.32,"end":36.96},{"text":"一年的时间下来我只会吐槽两间课之间的教学楼距离太远寝室里又有哪个孙子都拿了我的卫生纸","paragraph":1,"style":"plain","start":37.44,"end":45.42},{"text":"最后还是返璞归真的过着上课、","paragraph":1,"style":"plain","start":46.68,"end":49.12},{"text":"吃饭、睡觉、","paragraph":1,"style":"plain","start":49.46,"end":50.78},{"text":"三点一线的校园生活我也明白了一个道理就是浓人会有浓人丰富的生活淡人也有淡人寡淡的日子","paragraph":1,"style":"plain","start":50.98,"end":61.44},{"text":"外放了一年连个走得近的女生都没有因为同学数个的话来说就是你不会真以为这么忙活就能谈上","paragraph":1,"style":"plain","start":61.96,"end":70.76},{"text":"恋爱吧","paragraph":1,"style":"plain","start":70.76,"end":71.2},{"text":"所以我又调回了省电模式不过大一实在是太凑热闹了以至于导员跟我也比较熟到了大二 有什么","paragraph":2,"style":"plain","start":72.46,"end":81.72},{"text":"事还会喊我","paragraph":2,"style":"plain","start":81.72,"end":82.96},{"text":"开学半个月的某一天我在导员办公室里瞅见一个拎着行李箱的女生听意思是家里有事现在才能报","paragraph":3,"style":"plain","start":84.9,"end":93.78},{"text":"到但她导员在忙 走不开因为是同系我那好事的导员就问了我一嘴妳有没有空我瞅了一眼那个女","paragraph":3,"style":"plain","start":93.78,"end":103.98},{"text":"生 个子不矮 长得很乖 白白净净的跟那些上了半个月的新生相比 那确实是一白遮百丑但我","paragraph":3,"style":"plain","start":103.98,"end":113.96},{"text":"现在人是省电模式 不行 我要拒绝","paragraph":3,"style":"plain","start":113.96,"end":117.14},{"text":"导员就说 你能有什么事 你带人家熟悉一下我没办法 就只能答应嘛然后先把人家带去了女寝","paragraph":4,"style":"plain","start":118.04,"end":127.21},{"text":" 首先要有一个落脚的地方人家放东西的时候我就在楼下傻呵呵地等着她都没让我多等半小时后","paragraph":4,"style":"plain","start":127.48,"end":137.62},{"text":"换了一身衣服就下来九月中旬的天气逐渐变得清凉她原本穿着裙子现在有换成的长裤套上了小衫","paragraph":4,"style":"plain","start":137.62,"end":147.54},{"text":"然后又带她了解了一下各种设施","paragraph":4,"style":"plain","start":148.64,"end":150.7},{"text":"重点介绍了我们的两个食堂正好赶上中午的饭点小姑娘说要请我吃饭谢谢我这个学长的帮忙但她","paragraph":5,"style":"plain","start":151.74,"end":161.34},{"text":"还没有饭卡吗最后还是哥们结了账然后她又说要加微信转过来我说加微信可以但十几块钱你就有","paragraph":5,"style":"plain","start":161.4,"end":170.57},{"text":"点瞧不起哥们了她笑了笑也没在坚持下午我还有课校区里基本都带她逛了一圈所以撂下一句有事","paragraph":5,"style":"plain","start":170.57,"end":180.82},{"text":"微信联系我就溜了这事也没怎么放在心上","paragraph":5,"style":"plain","start":180.82,"end":184.78},{"text":"因为我非常清楚有联系方式不代表真的会有联系这句话不然哥们早在大一就脱单了而且这一年下","paragraph":6,"style":"plain","start":185.3,"end":193.35},{"text":"来我发现那些脱单的兄弟一个个的过得不是很开心所以在谈恋爱什么的也没那么向往了我和小学","paragraph":6,"style":"plain","start":193.35,"end":202.74},{"text":"妹就算认识了嘛虽然后来线下也就在食堂见过两面但那段时间联系倒是没断我们两个每天都有一","paragraph":6,"style":"plain","start":202.74,"end":211.84},{"text":"句没一句的了着其实那天帮忙的时候，","paragraph":6,"style":"plain","start":211.84,"end":215.22},{"text":"她话挺少的。","paragraph":6,"style":"plain","start":215.46,"end":216.56},{"text":"这也是为什么我没有乱想，但在微信上，她话反而变多了。","paragraph":7,"style":"plain","start":217.22,"end":222.18},{"text":"刚入学，发现什么新鲜的东西，都会跟我说说。","paragraph":7,"style":"plain","start":223.0,"end":225.86},{"text":"我也会告诉她一些校园里约定俗成的潜规则。","paragraph":7,"style":"plain","start":226.4,"end":229.46},{"text":"比如，小情侣都在什么地方约会之类的，她也很喜欢听这样的八卦。","paragraph":7,"style":"plain","start":230.56,"end":234.9},{"text":"就这样，大概又过了一周吧。","paragraph":8,"style":"plain","start":235.78,"end":237.78},{"text":"我清楚的记得那天是迎新晚会。","paragraph":8,"style":"plain","start":238.34,"end":240.88},{"text":"我在寝室里打游戏的时候，手机一个劲地响。","paragraph":8,"style":"plain","start":241.78,"end":244.74},{"text":"首歌喵了一眼消息提醒，调侃地说了句，你还在这玩呢？","paragraph":8,"style":"plain","start":245.98,"end":250.8},{"text":"人家女生的消息都轰过来了。","paragraph":8,"style":"plain","start":251.42,"end":252.96},{"text":"我知道这是小学妹的消息。","paragraph":9,"style":"plain","start":254.06,"end":255.58},{"text":"她发微信，有个习惯，一件事会分出好几句来说，所以提示音听着，就有种急促的感觉。","paragraph":9,"style":"plain","start":256.46,"end":263.64},{"text":"我正好在游戏里也挂了，看那一眼手机，是迎新晚会相关的。","paragraph":9,"style":"plain","start":264.58,"end":269.36},{"text":"还有一张她在后台上的照片，说现场可热闹了。","paragraph":10,"style":"plain","start":269.98,"end":273.54},{"text":"我一下就来了兴趣，好奇地问她，你也要上台。","paragraph":10,"style":"plain","start":274.16,"end":277.88},{"text":"她说，是啊，被抓到，会点民族才艺，不上不行了。","paragraph":10,"style":"plain","start":278.37,"end":283.08},{"text":"然后一字一句地回覆说，你不准看。","paragraph":10,"style":"plain","start":283.9,"end":287.66},{"text":"我这逆反心理也上来了，更要去瞅瞅。","paragraph":11,"style":"plain","start":288.84,"end":291.54},{"text":"套了件衣服，就跑到那现场。","paragraph":11,"style":"plain","start":292.2,"end":294.16},{"text":"迎新晚会是在我们那个大操场上办的也不用椅子板那儿同学们就坐在草坪上欣赏节目我到的时候","paragraph":11,"style":"plain","start":294.72,"end":303.82},{"text":"就远远的听见了宅舞的音乐看见舞台上一个带着黑口罩的女生可能蹦的由于后来没怎么见面戴了","paragraph":11,"style":"plain","start":303.82,"end":315.1},{"text":"口罩第一时间还没认出来临近了才发现是小学妹她穿了一身比较日系的小衣服","paragraph":11,"style":"plain","start":315.1,"end":322.12},{"text":"好多人还举着手机在拍视频我也给她录下来了表演一结束我就把视频发过去接着调侃地说了句你","paragraph":12,"style":"plain","start":322.74,"end":332.94},{"text":"还是个二次元小学妹发那一个得意的表情说自己不仅是个二次元还是个老二次元当时我寻思她的","paragraph":12,"style":"plain","start":332.94,"end":342.18},{"text":"表演也看完了嘛其他节目也没什么兴趣所以她下台我就往寝室回了当走到一半的时候，","paragraph":12,"style":"plain","start":342.18,"end":350.74},{"text":"小学妹问我你在哪儿呢？","paragraph":12,"style":"plain","start":351.04,"end":353.3},{"text":"我怎么找不到你？","paragraph":12,"style":"plain","start":353.46,"end":354.32},{"text":"我没想到她会下台找我，不过哥们的反应还挺快就说看你跳得挺累的，","paragraph":13,"style":"plain","start":355.92,"end":362.7},{"text":"我去给你买瓶水超市和食堂在一个方向嘛她就让我别回来了，","paragraph":13,"style":"plain","start":362.88,"end":368.56},{"text":"说自己正好要去食堂吃饭于是我就在原地等她那条小路横穿一个绿化景观，","paragraph":13,"style":"plain","start":368.9,"end":376.52},{"text":"人很少远处迎新晚会的灯光和音乐还在背景里继续没一会儿同一个方向就出现了舞台上那个蹦跶","paragraph":13,"style":"plain","start":376.83,"end":386.26},{"text":"的身影她小跑过来的","paragraph":13,"style":"plain","start":386.36,"end":389.02},{"text":"再加上刚才的表演就出了不少汗身上散发的热气额头上还黏着一些细碎的发丝我说你要不要先回","paragraph":14,"style":"plain","start":389.02,"end":399.57},{"text":"去洗个澡啥的她闻了闻自己伸过了一条胳膊说也没有味道呀我也闻了一下却假装地皱着鼻子，","paragraph":14,"style":"plain","start":399.57,"end":408.84},{"text":"没有奇怪的味道啊，但也不是那种很简单的香味。","paragraph":14,"style":"plain","start":409.22,"end":412.64},{"text":"这好像不是鼻子闻到的，更像是大脑直接捕获的。","paragraph":15,"style":"plain","start":413.38,"end":417.92},{"text":"小学妹也知道我在逗她，嘴上恶狠狠地说，就不洗，熏死你。","paragraph":15,"style":"plain","start":419.0,"end":423.7},{"text":"经过一段时间的联系，两个人熟络了不少嘛，她也比第一次见面的时候活泼了很多。","paragraph":15,"style":"plain","start":425.02,"end":430.96},{"text":"我看着面前脸上带着细汗元气满满的女生心里第一次出现了某种异样的感觉我没继续跟她贫嘴两","paragraph":16,"style":"plain","start":431.9,"end":441.92},{"text":"人就一起往食堂超市那个方向走路上聊着刚才的表演之前的距离也若即若离的时不时手臂还会碰","paragraph":16,"style":"plain","start":441.92,"end":452.06},{"text":"在一起我给她买了瓶可乐她显摆地掏出饭卡因为是绿色的就说姐现在也是有绿卡的人了走我请你","paragraph":16,"style":"plain","start":452.06,"end":462.1},{"text":"去吃饭我看着她得意的样子也没有拒绝","paragraph":16,"style":"plain","start":462.1,"end":466.58},{"text":"吃饭的时候聊到她为什么会晚来半个月其实之前我就挺好奇的但一直没好意思问她吹着嘴冲着的","paragraph":17,"style":"plain","start":467.36,"end":476.32},{"text":"叹了口气似乎有很多难言之隐我心想这么复杂吗已经在脑补各种千奇百怪的狗血剧情了实际情况","paragraph":17,"style":"plain","start":476.413,"end":486.42},{"text":"是，","paragraph":17,"style":"plain","start":486.42,"end":486.8},{"text":"她爸妈要离婚，因为女儿高考，一直没离嘛。","paragraph":17,"style":"plain","start":487.22,"end":491.16},{"text":"小学妹临近开学才知道这事。","paragraph":18,"style":"plain","start":491.72,"end":493.52},{"text":"当时她爸妈已经去过民政局了，还在冷静期。","paragraph":18,"style":"plain","start":494.2,"end":497.56},{"text":"她就一直在劝和，但两人都是吃了秤砣铁了心。","paragraph":18,"style":"plain","start":498.46,"end":502.28},{"text":"她没办法，就只能用不上学的威胁，最后耽误了半个月的时间。","paragraph":18,"style":"plain","start":502.94,"end":507.82},{"text":"我问她，那她们现在和好了吗？","paragraph":19,"style":"plain","start":508.76,"end":511.28},{"text":"小学妹还是一副愁眉不展的样子，说，没有。","paragraph":19,"style":"plain","start":512.04,"end":515.52},{"text":"但他们为了让我来上学，答应我只是暂时分居。","paragraph":19,"style":"plain","start":516.4,"end":520.2},{"text":"我听了也不知道该说什么，就只能跟她比赛，说哥们从小也是单亲家庭，","paragraph":19,"style":"plain","start":521.78,"end":527.1},{"text":"好着逢年过节可以两头吃，爸妈那边各要一份。","paragraph":19,"style":"plain","start":527.76,"end":531.44},{"text":"她听了扑哧一下笑了，但接着又认真的问我，你不想他们和好吗？","paragraph":20,"style":"plain","start":532.66,"end":537.4},{"text":"我说可能时间太久了吧已经有点无法想像他们在一起的样子而且爸妈之间的事具体也只有他们自","paragraph":20,"style":"plain","start":538.48,"end":546.93},{"text":"己知道所以我也懒得多嘴小学妹听了就若有所思的看着我说跟你比感觉我还是个没长大的小孩我","paragraph":20,"style":"plain","start":546.93,"end":557.76},{"text":"不想再继续这种比较严肃的对话就岔开话题说我确实比你大呀她说未必哦 我上学晚","paragraph":20,"style":"plain","start":557.76,"end":565.52},{"text":"然后两个人一对年龄没想到还真他们是同岁好在哥们生日比较大不然就失去地位了那天之后我们","paragraph":21,"style":"plain","start":566.54,"end":576.4},{"text":"两个也算有了更多的了解聊天也从原本学校相关的扩展到了日常的各种事情偶尔和她一起玩玩游","paragraph":21,"style":"plain","start":576.4,"end":584.66},{"text":"戏或者在学校的体育场打个网球傻的迎新晚会结束以后每两天就到国庆了嘛我和小学妹都是外地","paragraph":21,"style":"plain","start":584.66,"end":594.72},{"text":"的聊天的时候就说各自的安排大家都没什么事","paragraph":21,"style":"plain","start":594.72,"end":599.26},{"text":"所以就约好了一起出去玩我们两个都是标准的P人不会提前计划什么第一天心血来潮的骑行的大","paragraph":22,"style":"plain","start":599.78,"end":608.26},{"text":"半天车链子都蹬掉了幸好是共享单车不过第二天累了哪儿都不想去躺在寝室里玩了一天的手机饭","paragraph":22,"style":"plain","start":608.26,"end":618.14},{"text":"都是舍友捎带的当时我以为骑行就算只出去玩了没想到第三天，","paragraph":22,"style":"plain","start":618.14,"end":624.54},{"text":"小学妹又来问我恢复的怎么样我就反问她，您还有什么吩咐","paragraph":22,"style":"plain","start":625.06,"end":629.92},{"text":"她学着古装剧里的调调回答说自从小女子上学以来，","paragraph":23,"style":"plain","start":631.38,"end":635.76},{"text":"对周围还不是了解阁下是否知晓哪处可寻到热闹的市集我心想就是大商场嘛，","paragraph":23,"style":"plain","start":636.4,"end":644.5},{"text":"刚想说点什么舍友看见了，就凑热闹的讲了句人家那意思多明显啊，","paragraph":23,"style":"plain","start":644.82,"end":651.16},{"text":"你说你带她去就这样 第三天我和小学妹跑去逛商场她原本打算看那个七次酒局的我好说歹说没","paragraph":23,"style":"plain","start":651.5,"end":661.04},{"text":"撑住最后试探性地问了句 你追星吗","paragraph":23,"style":"plain","start":661.04,"end":664.28},{"text":"她说 不是啊 我就想凑个热闹那场的人很多 我们临时买票只有靠后很角落的位置我看了一眼","paragraph":24,"style":"plain","start":665.88,"end":675.5},{"text":"前面的观众又看了一眼旁边可爱的小学妹突然想起来这好像是我第一次单独跟一个女生看电影说","paragraph":24,"style":"plain","start":675.5,"end":685.1},{"text":"实话，","paragraph":24,"style":"plain","start":685.1,"end":685.48},{"text":"看得还挺开心的就意外的有一种喜剧的效果小学妹为了整住笑声，","paragraph":24,"style":"plain","start":685.76,"end":692.36},{"text":"时不时就抓着我的胳膊和肩膀疼得我龇牙咧嘴的","paragraph":24,"style":"plain","start":692.7,"end":696.62},{"text":"看完电影买奶茶的时候，舍友那边发了一张学校表白墙的截图问我，","paragraph":25,"style":"plain","start":697.72,"end":703.18},{"text":"这不是最近跟你一起玩的那女生吗？","paragraph":25,"style":"plain","start":703.86,"end":705.96},{"text":"我点开照片，","paragraph":25,"style":"plain","start":706.86,"end":707.64},{"text":"虽然有点模糊但能看出来就是小学妹她在旁边也瞟到一眼有些惊讶我还看什么表白墙然后说她知","paragraph":25,"style":"plain","start":708.04,"end":718.99},{"text":"道这事迎新晚会那天就有好多人来加她微信虽然我们两个没啥关系但听着心里就酸不溜溜的不过","paragraph":25,"style":"plain","start":718.99,"end":728.64},{"text":"嘴上还是故作轻松地问她","paragraph":25,"style":"plain","start":728.64,"end":730.74},{"text":"那你有没有看上呢她歪着脑袋撅着嘴看着我回答说没有我已经有喜欢的人了我下意识地问了句谁","paragraph":26,"style":"plain","start":731.36,"end":741.3},{"text":"呀她指了指我的奶茶说你让我尝一口我就告诉你虽然我对奶茶无感但护食的机制还是触发了双手","paragraph":26,"style":"plain","start":741.3,"end":752.56},{"text":"捂着奶茶说男女授受不亲喝了就是间接接吻你爱说不说小学妹眼睛都瞪纳了一拳就抡了过来嘴上","paragraph":26,"style":"plain","start":752.62,"end":763.22},{"text":"还你她妈的我她妈的说着粗鄙之语我看她生气的样子","paragraph":26,"style":"plain","start":763.22,"end":768.88},{"text":"心里的怨气也缓和了不少刚才就是故意气她的现在又把奶茶放在她面前说嗯 你喝吧她见撞也没","paragraph":27,"style":"plain","start":768.88,"end":780.1},{"text":"跟我客气一口气喝了大半瓶我看她胀肚的样子也没再问她喜欢的是谁反正在这样的一拉一扯之间","paragraph":27,"style":"plain","start":780.1,"end":789.48},{"text":"我们的关系也越来越近就整天在微信上早安晚安地说着中午在食堂不期而遇周末又约在图书馆一","paragraph":27,"style":"plain","start":789.48,"end":798.8},{"text":"起学习不过全程都在玩手机打游戏关系是真的近了","paragraph":27,"style":"plain","start":798.8,"end":805.2},{"text":"但我真是一点没敢多想以前大一高中那会想了多想怕了而且总感觉现在的关系也挺亲近的万一越","paragraph":28,"style":"plain","start":805.2,"end":814.62},{"text":"界给人家吓跑了怎么办转折点在双十一的时候我没有赶购物节的习惯但小学妹跟着请示里的小学","paragraph":28,"style":"plain","start":814.62,"end":824.42},{"text":"妹买了一堆东西那时候天气已经很冷了她还凑单给我买了一条围巾然后吃完午饭让我在楼下等着","paragraph":28,"style":"plain","start":824.5,"end":833.24},{"text":"没一会就拿着一条灰色和卡其色相间的围巾下来了","paragraph":28,"style":"plain","start":833.69,"end":837.76},{"text":"我戴了一下 平好气暖和又好看但很快又给摘了小学妹问我 你摘了干嘛我抓过她的手 在下巴","paragraph":29,"style":"plain","start":838.52,"end":848.88},{"text":"上摸了一把她还是不明白我问她 扎手吗？","paragraph":29,"style":"plain","start":848.88,"end":853.12},{"text":"她点点头我接着说哥们上午刮的胡子下午就又抽于蜜这围巾我戴上一天直接被货原色料了她又伸","paragraph":29,"style":"plain","start":853.52,"end":864.96},{"text":"手摸了一把戴着效益的说没看出来啊你还挺成熟的我白了的一眼说那是哥们刮得勤她说 没事刮","paragraph":29,"style":"plain","start":864.96,"end":875.23},{"text":"烂了","paragraph":29,"style":"plain","start":875.66,"end":876.1},{"text":"再送你一条新的说着又给我围脖子上的我低头看着面前给我系着围巾的小姑娘脖子上暖暖的 心","paragraph":30,"style":"plain","start":876.1,"end":886.26},{"text":"里也暖暖的下午我有两节课 小学妹没课于是就先去图书馆占位置然后我到的时候刚好看到一个","paragraph":30,"style":"plain","start":886.26,"end":895.96},{"text":"男生在跟她搭讪说是什么摄影部的 觉得她漂亮想请她拍两组人像作业我原本打算坐在旁边有点","paragraph":30,"style":"plain","start":895.96,"end":905.46},{"text":"距离的位置看戏","paragraph":30,"style":"plain","start":905.46,"end":906.52},{"text":"但小学妹瞄了我一眼，还真掏出手机，我一下就坐不住了。","paragraph":31,"style":"plain","start":907.24,"end":911.84},{"text":"鄙人不才，大一凑热闹的时候还真加入摄影部，上不全胸。","paragraph":31,"style":"plain","start":912.69,"end":918.06},{"text":"于是就上前按着她的手机说，那同学，不好意思，这是我先找到的模特。","paragraph":31,"style":"plain","start":918.88,"end":925.04},{"text":"那男生看了眼小学妹，发现她在捂嘴笑，就知道我们两个认识吧，所以撂下一句，打扰了，","paragraph":32,"style":"plain","start":926.02,"end":933.02},{"text":"也识趣地离开了。","paragraph":32,"style":"plain","start":933.42,"end":934.48},{"text":"然后我就有点生气地问她妳不知道她是来搭讪的吗小学妹还是一脸笑意地说知道啊 我又没有男","paragraph":32,"style":"plain","start":935.46,"end":944.06},{"text":"朋友为什么不能加呢我一时有些语塞她说的好像也没什么毛病我也没什么身份要求人家所以就只","paragraph":32,"style":"plain","start":944.06,"end":953.62},{"text":"能坐在那生闷气她倒是笑得放肆了","paragraph":32,"style":"plain","start":953.62,"end":956.8},{"text":"凑过来问我生气了 生气了我还在嘴硬说你想加就加吗小学妹这时候攥了一下我脖子上的围巾好","paragraph":33,"style":"plain","start":957.12,"end":967.32},{"text":"像拽着狗绳一样说我已经是有小狗的人了不能让小狗伤心的说实话我不是一个很喜欢向外求的人","paragraph":33,"style":"plain","start":967.32,"end":977.02},{"text":"就万事不求人吧但当时我看着她那副温柔的样子还是没忍住的问了句你以后能不能别加别的男生","paragraph":33,"style":"plain","start":977.86,"end":988.34},{"text":"她看我有些认真也收起了笑容变得有些害羞的回答头","paragraph":33,"style":"plain","start":989.09,"end":993.84},{"text":"可以从那之后我们的关系就有了本质上的改变两个人已经莫名其妙地换上情头每天的聊天都甜得","paragraph":34,"style":"plain","start":994.36,"end":1004.78},{"text":"不行我也确实在计划着寒假之前跟她表白然而圣诞节那两天的时候我发现小学妹整个人都萎靡不","paragraph":34,"style":"plain","start":1004.78,"end":1013.94},{"text":"振的追问之下说她爸妈最后还是离婚了那种情况我也不好意思表白了嘛但状态也很差怎么能说是","paragraph":34,"style":"plain","start":1013.94,"end":1024.46},{"text":"为了冲喜吧时间就这样来到了寒假","paragraph":34,"style":"plain","start":1024.46,"end":1027.92},{"text":"虽然还没有正式在一起但我第一次感受到了异地的痛苦每天都很想见到她小学妹回家以后又开始","paragraph":35,"style":"plain","start":1028.42,"end":1038.04},{"text":"着手准备劝和爸妈我也在远程给她出谋划策大致计划就是过年的时候撮合双方一起吃个年夜饭吧","paragraph":35,"style":"plain","start":1038.04,"end":1047.5},{"text":"找回一些家的温暖勾起一些彼此的回忆但在初一那天爸妈就是聚到一起了不过却和她非常认真的","paragraph":35,"style":"plain","start":1047.5,"end":1056.62},{"text":"聊了一下大意就是两个人不可能和好了","paragraph":35,"style":"plain","start":1056.62,"end":1060.4},{"text":"那是我第一次听见小学妹哭半夜跟我打着语音哭得声泪俱下气不成声我虽然从小就是单亲家庭对","paragraph":36,"style":"plain","start":1061.66,"end":1070.84},{"text":"父母的分开没有太多感觉但也知道对于成长在家庭完整的她来说一定是非常难过的事情我听了对","paragraph":36,"style":"plain","start":1070.84,"end":1080.18},{"text":"面委屈的小姑娘恨不得立刻冲到她面前于是当晚就用压岁钱订了车票大清早跟我爸说了一声初一","paragraph":36,"style":"plain","start":1080.18,"end":1089.66},{"text":"就跑到小学妹的城市好在就是隔壁省的距离","paragraph":36,"style":"plain","start":1089.66,"end":1093.44},{"text":"也不是特别远之前聊天的时候我套路过小学妹的地址所以靠着手机地图还算顺利地找到了她家我","paragraph":37,"style":"plain","start":1093.44,"end":1103.6},{"text":"记得那天刚下完雪温度很低，","paragraph":37,"style":"plain","start":1103.6,"end":1106.0},{"text":"但没有风我带着那条围巾在她楼下发了一个语音问她现在怎么样小学妹回了一条语音听着好像刚","paragraph":37,"style":"plain","start":1106.36,"end":1115.6},{"text":"睡醒昨天晚上哭了很久鼻子还囔囔的说在床上躺着，","paragraph":37,"style":"plain","start":1115.6,"end":1120.78},{"text":"还没起来我去诱导她说那你要不要下楼透透气","paragraph":37,"style":"plain","start":1120.92,"end":1124.98},{"text":"她说不的，太冷了，","paragraph":38,"style":"plain","start":1125.52,"end":1127.4},{"text":"我不出去我就假装打着哆嗦提醒她是挺冷的小姑娘很聪明立刻意识到了什么发了三个感叹号问我","paragraph":38,"style":"plain","start":1127.48,"end":1138.28},{"text":"你在哪我如实回答说在你家楼下她那边好一会没吱声然后就看见楼门口一个小姑娘着急忙慌着跑","paragraph":38,"style":"plain","start":1138.28,"end":1148.76},{"text":"出来看见我之后眼睛又红了眼泪也啪嗒啪嗒地往下掉抿着嘴站在原地不动我看着她穿着睡衣外面","paragraph":38,"style":"plain","start":1148.76,"end":1160.18},{"text":"就套了个羽绒服拉链还没拉","paragraph":38,"style":"plain","start":1160.18,"end":1162.8},{"text":"就赶忙迎上去把她推进了楼道她吸溜着鼻子 问我你怎么来了我说看你太伤心 来陪陪你而且我","paragraph":39,"style":"plain","start":1163.16,"end":1174.7},{"text":"想见你了她听后终于笑了一问我在楼下等了多久说着还用双手捂着我耳朵我没有回答看着她红肿","paragraph":39,"style":"plain","start":1174.7,"end":1185.54},{"text":"的眼睛 有些心疼再加上她举着双手于是就顺势抱住了她小学妹没有闪躲，","paragraph":39,"style":"plain","start":1185.54,"end":1193.88},{"text":"也没有挣扎，她惊讶了一下，双手也环住了我。","paragraph":39,"style":"plain","start":1194.06,"end":1198.56},{"text":"两个人早就知道彼此的心意，但有些话还是要正式的说出来。","paragraph":40,"style":"plain","start":1199.6,"end":1204.22},{"text":"所以我就这样抱着她说，我知道你现在因为爸妈的事情很难过，","paragraph":40,"style":"plain","start":1205.12,"end":1209.52},{"text":"我也没有什么更好的办法可以帮到你。","paragraph":40,"style":"plain","start":1210.16,"end":1212.1},{"text":"但如果你想要有个人陪着我就一定会在你的身边所以我刚想放开一点看着她说话她就反而不肯松","paragraph":40,"style":"plain","start":1212.8,"end":1223.5},{"text":"开便打断我说了句别吵继续抱着我还有我也喜欢你","paragraph":40,"style":"plain","start":1223.5,"end":1230.82},{"text":"故事讲完了我抬头看了看今天的夜晚了没有星星没关系，你眼睛里的光比星星更亮。","paragraph":41,"style":"plain","start":1234.52,"end":1245.64},{"text":"睡个好觉吧，明天又是崭新的一天。","paragraph":41,"style":"plain","start":1246.76,"end":1250.2},{"text":"晚安，愿你的梦里有糖，做个好梦。","paragraph":41,"style":"plain","start":1251.16,"end":1254.54}]},{"id":"you-deserve-it","title":"更是因为你值得","category":"story","sequence":13,"duration":774.321633,"audio":"you-deserve-it.mp3","palette":["#516153","#6d5f54"],"cues":[{"text":"我和她的故事开始的很晚，相遇的时候本科都快结束了。","paragraph":0,"style":"plain","start":2.06,"end":7.48},{"text":"我是那种不喜欢怀旧的人，加上我这冷门又无聊的古生物专业，","paragraph":0,"style":"plain","start":8.38,"end":13.64},{"text":"所以这四年的大学生涯并没有太多的留恋。","paragraph":0,"style":"plain","start":14.36,"end":17.573},{"text":"在我眼中，所谓的毕业仅仅就是在一个平平无奇的午后，匆忙拍下一组毕业合照，","paragraph":0,"style":"plain","start":18.0,"end":24.92},{"text":"然后奔赴下一段未知的人生。","paragraph":0,"style":"plain","start":25.6,"end":27.58},{"text":"契机是某一天，导师甩给我一份课程简介，说是一个澳洲教授要来这里待一周，","paragraph":1,"style":"plain","start":28.94,"end":35.5},{"text":"顺便给我们这些本科生传授一点入门知识。","paragraph":1,"style":"plain","start":36.1,"end":38.84},{"text":"我那时候的心思其实已经不在学业上了，不过导师的命令我还是得听一下，","paragraph":1,"style":"plain","start":40.42,"end":46.06},{"text":"毕竟关系到能否顺利毕业，于是就和十几个同学去捧场。","paragraph":1,"style":"plain","start":46.7,"end":51.04},{"text":"我的室友本来是要和我一起的，但临时跑到另一个导师那边。","paragraph":2,"style":"plain","start":52.04,"end":56.48},{"text":"我为了等他，耽误了不少时间，当我着急忙慌地赶到教室，就只剩下第一排有空位了。","paragraph":2,"style":"plain","start":57.06,"end":63.64},{"text":"我也只能硬着头皮坐下。","paragraph":2,"style":"plain","start":64.28,"end":65.62},{"text":"第一排除了我，还有一个女生。","paragraph":3,"style":"plain","start":66.64,"end":68.7},{"text":"转头正和澳洲教授戏时到道地聊着什么。","paragraph":3,"style":"plain","start":69.58,"end":72.42},{"text":"长发挡住了脸，看不到长相，但气质和身段就已经很说明问题了。","paragraph":3,"style":"plain","start":73.2,"end":78.82},{"text":"我听了一会他们的聊天心里想着这女生的口音还挺纯正的就是那种尾音拉长带着点气泡的口音很","paragraph":3,"style":"plain","start":79.62,"end":88.84},{"text":"卡戴珊也很加州就在我好奇女生长相的时候她还转过头来正好我和她的弯弯的的眼睛似乎相对","paragraph":3,"style":"plain","start":88.84,"end":98.58},{"text":"那双眼睛非常蓝非常干净就像明媚阳光下最清澈的玻璃海一样这时我才反应过来她是个外国人","paragraph":4,"style":"plain","start":99.18,"end":109.52},{"text":"那堂课后来讲了什么我已经记不得了其他同学基本都在后面摸鱼但因为我在第一排于是整整半个","paragraph":5,"style":"plain","start":112.62,"end":121.9},{"text":"小时的提问环节就我和那个美国女生一直在和老教授瞎扯下课以后我们跟老教授合了影临走时那","paragraph":5,"style":"plain","start":121.9,"end":132.08},{"text":"女生说要找我要一些文献我们就以此为由加上了微信晚上回到寝室我跟她放鸽子的室友说起这事","paragraph":5,"style":"plain","start":132.08,"end":141.44},{"text":"没等我找她算账她倒要我请客说是因为她我才认识人家","paragraph":5,"style":"plain","start":141.9,"end":147.48},{"text":"我心情很好于是也就口头上答应了再来那天晚上我和女生在微信上聊得挺开心她跟我同届但并不","paragraph":6,"style":"plain","start":148.12,"end":158.75},{"text":"是我们专业的而是隔壁学院学的是分子生物学跟我的专业也有一定的相关性吧甚至向我要的文献","paragraph":6,"style":"plain","start":158.75,"end":167.66},{"text":"就是在主攻的方向所以作为感谢他也答应了周末会陪我练习口语我们两个就这样认识了吗熟悉了","paragraph":6,"style":"plain","start":167.66,"end":177.44},{"text":"一些以后也会叫上朋友一起玩外国人喜欢社交","paragraph":6,"style":"plain","start":177.44,"end":181.78},{"text":"他的朋友很多在社交场合里他就是那个控场气氛的存在很会开一些不着边际没有分寸但又不会让","paragraph":7,"style":"plain","start":182.2,"end":192.24},{"text":"你觉得冒犯的玩笑","paragraph":7,"style":"plain","start":192.24,"end":193.28},{"text":"我稍微内敛一点不过跟她也算是同类人两个E人在一起其实是最简单的她的直球总是恰到好处的","paragraph":8,"style":"plain","start":195.34,"end":205.22},{"text":"递到我面前又正好在我勾不到的位置就很会拿捏人心吧有天做完研究我们两个去了酒吧喝的不多","paragraph":8,"style":"plain","start":205.22,"end":215.12},{"text":"不少正好处在微醺的状态她就翻着手机跟我看她以前的ins然后我突然发现一张熟悉的照片，","paragraph":8,"style":"plain","start":215.12,"end":223.82},{"text":"是我跟那个老教授的合影。","paragraph":8,"style":"plain","start":224.32,"end":225.8},{"text":"我就下意识地拿过手机，明知故问地追问她，为什么会发这两张照片？","paragraph":9,"style":"plain","start":227.44,"end":232.28},{"text":"她也不回答，整个人扑了过来，一边大笑，一边弓过身子，也来抢手机。","paragraph":9,"style":"plain","start":232.91,"end":239.04},{"text":"当我举高了手，她怎么也够不到，我们就保持着很近的距离。","paragraph":9,"style":"plain","start":240.38,"end":244.94},{"text":"四目相对的时候，她突然停住了，就这样趴在我的身上。","paragraph":10,"style":"plain","start":245.62,"end":250.36},{"text":"我也本能迎了上去，亲在了她的嘴唇上。","paragraph":10,"style":"plain","start":251.12,"end":254.32},{"text":"当时我的大脑很纠结，觉得有些冒犯，同时又很开心。","paragraph":10,"style":"plain","start":255.28,"end":260.18},{"text":"好在她没有拒绝，只是稍微颤抖了一下，随后便给了我更热烈的回应。","paragraph":10,"style":"plain","start":260.94,"end":266.6},{"text":"就好像鲜花盛开在了暮春，却灿烂了整个盛夏。","paragraph":11,"style":"plain","start":267.64,"end":271.907},{"text":"我们两个都不是小孩在一起了那一刻就知道肯定会有分开的那天秋天的时候她就要回国但理智依","paragraph":11,"style":"plain","start":272.32,"end":281.8},{"text":"旧没有办法说服感情我们能做的就只有尽可能的享受这个夏天和很多情侣一样我们在一起了第一","paragraph":11,"style":"plain","start":281.8,"end":290.54},{"text":"件事就是复盘了一下各自的心路历程她说第一天见面就从我的眼中看出了心动我说那个叫见色起","paragraph":11,"style":"plain","start":290.54,"end":299.58},{"text":"意","paragraph":11,"style":"plain","start":299.7,"end":299.76},{"text":"因为欧美人的五官真的是很优越，她又是那种偏精致的长相，如果你看一眼都没感觉，","paragraph":12,"style":"plain","start":300.48,"end":307.46},{"text":"那你真是这个。","paragraph":12,"style":"plain","start":307.92,"end":308.74},{"text":"她听了以后就问我，I don't know，我盯着她那张好看的脸回答说，嗯，","paragraph":12,"style":"plain","start":309.61,"end":316.36},{"text":"still apology，她可能以为我会说一些有深度的话，","paragraph":12,"style":"plain","start":316.98,"end":320.68},{"text":"没想到我还是这样肤浅的回答。","paragraph":12,"style":"plain","start":321.34,"end":323.34},{"text":"但她没有生气反而又亲了过来亲完还嘲笑我的吻技很烂说以后她来教我省得以后出去丢人那天晚","paragraph":13,"style":"plain","start":324.12,"end":335.56},{"text":"上其实也没有发生什么但在她家的楼道里她一直黏着不让我走本来时间就不早了分开的时候听到","paragraph":13,"style":"plain","start":335.56,"end":344.46},{"text":"已经蒙蒙亮了","paragraph":13,"style":"plain","start":344.46,"end":345.48},{"text":"虽然口头上说的是见色起意但实际上她身上的优点实在太多了我也不知道该挑什么说刚才就摆烂","paragraph":14,"style":"plain","start":347.88,"end":356.79},{"text":"似地回答她是那种学术世家的出身原生家庭的条件可以说是非常优渥加上科研的道路上一帆风顺","paragraph":14,"style":"plain","start":356.885,"end":366.1},{"text":"给了她与生俱来的的自信安全感所以她本身就是个很聪明很优秀的人她喜欢我的原因也是第一眼","paragraph":14,"style":"plain","start":366.52,"end":375.38},{"text":"觉得我很睿智也不知道她知不知道","paragraph":14,"style":"plain","start":375.38,"end":378.26},{"text":"这句话现在更多是用来骂人的反正用时下的流行语来说她应该算是智性恋所以在一起以后她很喜","paragraph":15,"style":"plain","start":378.7,"end":389.09},{"text":"欢跟我讨论争论很多东西甚至找到我高中发表过的小说专门挑我语法上的错误我也不甘示弱就跟","paragraph":15,"style":"plain","start":389.09,"end":397.78},{"text":"她互相挑剔对方课题上的研究我们两个都很享受这种斗嘴打趣就像两个幼稚园的小孩也不知道在","paragraph":15,"style":"plain","start":397.84,"end":406.24},{"text":"争什么但却是多年不曾体会过的很热烈的感受","paragraph":15,"style":"plain","start":406.24,"end":410.6},{"text":"虽然她的条件很好，","paragraph":16,"style":"plain","start":412.06,"end":413.38},{"text":"也很优秀但她同样也有烦恼她父母的婚姻比较特殊对她也有很多苛刻的要求所以在家里，","paragraph":16,"style":"plain","start":413.52,"end":422.9},{"text":"她能得到的爱非常有限因此性格虽然外向但也很难有人可以真正走进她的心里那时候一直没有注","paragraph":16,"style":"plain","start":423.2,"end":431.6},{"text":"意到自己能够触碰到她的内心是一件多么难得的事情她甚至愿意为了我放下的高傲的自尊吵架的","paragraph":16,"style":"plain","start":431.6,"end":440.953},{"text":"时候主动跟我求和","paragraph":16,"style":"plain","start":440.953,"end":442.58},{"text":"不过和其他女生一样她也会问我喜欢她什么说如果是优点的话那肯定还会有比自己更好的女生我","paragraph":17,"style":"plain","start":444.86,"end":454.3},{"text":"就摸着她的脑袋有点公式化的回答我当然不是只喜欢你的优点缺点也是你完美的一部分当然她总","paragraph":17,"style":"plain","start":454.3,"end":463.04},{"text":"是不信但又说着哪怕是骗她，","paragraph":17,"style":"plain","start":463.04,"end":466.673},{"text":"她也愿意。","paragraph":17,"style":"plain","start":466.907,"end":467.66},{"text":"总之呢，她的喜欢我看在眼里。","paragraph":18,"style":"plain","start":468.52,"end":471.24},{"text":"她的纠结我也知道，有一天她没头没脑的让我回家偷户口本，说要跟我领证。","paragraph":18,"style":"plain","start":471.67,"end":479.2},{"text":"但又想起刚在一起时对我说过的那句，我始终会离开你的，声音也有逐渐变小了。","paragraph":18,"style":"plain","start":480.08,"end":486.98},{"text":"距离她回国的日子，一天天接近。","paragraph":19,"style":"plain","start":488.22,"end":490.4},{"text":"我们在一起的时间也越来越多收拾行李的时候她抽屉里落下了一张跟猫咪的合影照片里的她还带","paragraph":19,"style":"plain","start":491.32,"end":500.26},{"text":"着一些稚气青涩又天真虽然一眼看得出那是她但和如今成熟知性的样子简直判若两人她接过照片","paragraph":19,"style":"plain","start":500.26,"end":510.34},{"text":"轻柔地抚摸着照片里胖成球的金渐层长长的睫毛在窗外午后的暖阳下多了一层细碎的忧郁","paragraph":19,"style":"plain","start":510.96,"end":519.08},{"text":"她爸妈没空的时候，都是这只猫在陪她。","paragraph":20,"style":"plain","start":520.04,"end":523.12},{"text":"如今，年纪已经不小了。","paragraph":20,"style":"plain","start":523.58,"end":525.42},{"text":"她说，如果这只猫没能等到自己回去，就永远不会再养宠物了。","paragraph":20,"style":"plain","start":525.94,"end":530.64},{"text":"我心里忽然有些酸酸的。","paragraph":20,"style":"plain","start":531.54,"end":533.02},{"text":"不知道她回去以后，会不会像想念这只猫咪一样想念我。","paragraph":20,"style":"plain","start":533.84,"end":537.96},{"text":"所以我第一次求她，回去以后能不能继续保持关系。","paragraph":21,"style":"plain","start":538.84,"end":542.94},{"text":"她答应了。","paragraph":21,"style":"plain","start":543.33,"end":544.28},{"text":"毕业会上她又成了那个把控节奏的交际女王我也藏起了心里的苦涩跟同学们打成一片享受着最后","paragraph":22,"style":"plain","start":546.98,"end":555.4},{"text":"的时刻但紧接着我就被她拉到了走廊无人的地方那是我们最后一次热吻当时她的表现很复杂如今","paragraph":22,"style":"plain","start":555.4,"end":565.26},{"text":"的我才意识到我们的感情基础不足以支撑的3年的时间和13个小时的距离这个夏天太短了，","paragraph":22,"style":"plain","start":565.26,"end":573.88},{"text":"我们从相识到离别，只用了四个月，这个夏天也太长了。","paragraph":22,"style":"plain","start":574.04,"end":579.64},{"text":"长到我可能要用一生，却度过很多次。","paragraph":23,"style":"plain","start":580.26,"end":583.3},{"text":"当离别的钟声响起的时候，她倒是显得特别潇洒，跟朋友们说说笑笑，也不知道在说些什么。","paragraph":23,"style":"plain","start":584.3,"end":591.78},{"text":"曾经谈论的一定跟我有关，但从此以后，恐怕会越来越少。","paragraph":23,"style":"plain","start":592.62,"end":597.96},{"text":"到最后，她穿着那一席白裙，彻底消失在了我的视野里。","paragraph":24,"style":"plain","start":598.9,"end":603.54},{"text":"如今的达拉斯应该依旧四季如春，她应该也一如既往地更新了琐碎的日常。","paragraph":24,"style":"plain","start":604.6,"end":610.94},{"text":"我们之间像大部分异国的恋人一样渐行渐远，最后，只剩下她离开后，","paragraph":24,"style":"plain","start":611.86,"end":617.7},{"text":"朋友圈里置顶了那首Summer Time Friends，","paragraph":24,"style":"plain","start":618.36,"end":621.52},{"text":"还在提醒我们那个肆无忌惮的夏天。","paragraph":24,"style":"plain","start":622.6,"end":624.68},{"text":"遇见她之前，我从来不知道什么是喜欢。","paragraph":25,"style":"plain","start":625.78,"end":628.68},{"text":"或者说在我心里，喜欢是一个很有分量的词。","paragraph":25,"style":"plain","start":629.42,"end":632.62},{"text":"也从来没有女生能在我心里占据着如此重要的位置。","paragraph":25,"style":"plain","start":633.38,"end":636.52},{"text":"曾经我很抗拒和对方长时间的相处。","paragraph":25,"style":"plain","start":637.34,"end":640.16},{"text":"但和她在一起以后，我却总是希望每一次的约会时间能够更久一点。","paragraph":26,"style":"plain","start":640.94,"end":646.16},{"text":"是她让我明白了喜欢的含义。","paragraph":26,"style":"plain","start":647.1,"end":648.84},{"text":"她是一个热烈、骄傲、疯狂、","paragraph":26,"style":"plain","start":649.44,"end":652.12},{"text":"会流出炽热毫无保留爱意的人而我恰好喜欢过度的东西我期望不可理喻的沉迷想要情绪的烈火炙","paragraph":26,"style":"plain","start":652.74,"end":661.62},{"text":"烤我的灵魂希望那些能够消耗我生命的爱情","paragraph":26,"style":"plain","start":661.72,"end":665.6},{"text":"于是我们在夜幕下拉着手奔跑过川流不息的大桥在人声鼎沸的路口旁若无人地拥吻在震耳欲聋的","paragraph":27,"style":"plain","start":667.7,"end":676.24},{"text":"音乐中放声大笑唯独与她在一起的时候我才能完全投入的感受自己短暂的生命所以我整理好了自","paragraph":27,"style":"plain","start":676.24,"end":685.77},{"text":"己的羽毛再一次镇定挥现了那颗会融化我的太阳","paragraph":27,"style":"plain","start":685.77,"end":691.18},{"text":"故事讲完了夜也深了很多时候年轻的我们都不太懂得时间的重量看着那些在岁月里也慢慢走散的","paragraph":28,"style":"plain","start":697.46,"end":708.12},{"text":"人才明白其实人与人之间只要不聊天不互动不见面两个人就真的会一点一点消失在彼此的世界里","paragraph":28,"style":"plain","start":708.12,"end":718.82},{"text":"抓不住那些想要离开的人但也正因为如此我更懂得了留下来的会有多珍贵所以对我来讲爱从来都","paragraph":28,"style":"plain","start":719.82,"end":729.64},{"text":"不识意到全横利宾的选择体更不是稍有不合适的分开","paragraph":28,"style":"plain","start":729.64,"end":734.06},{"text":"也不是腻了就要换掉但是在看清了人来人往之后，依然会感受到温暖和勇敢，","paragraph":29,"style":"plain","start":734.72,"end":741.62},{"text":"是明知不可为而为之的坚定。","paragraph":29,"style":"plain","start":742.42,"end":744.8},{"text":"所以我想让你知道，我对你从来不是一时兴起，而是心里一次又一次的笃定于心动，","paragraph":29,"style":"plain","start":746.0,"end":752.8},{"text":"就像曾经看过的一句话，喜欢一个人不仅仅是想拥抱你，更是会忍不住地在乎你，惦记你，","paragraph":29,"style":"plain","start":753.52,"end":762.18},{"text":"想真正懂你。","paragraph":29,"style":"plain","start":762.72,"end":763.6},{"text":"这不仅是因为我执着，更是因为你值得","paragraph":30,"style":"plain","start":764.54,"end":768.78},{"text":"晚安啦，迷湖宝宝，做个好梦","paragraph":31,"style":"plain","start":770.96,"end":773.24}]}];
